window.RD=[{"id":"r1-01","level":1,"type":"notice","topic":"IT","title":"VPN maintenance this Saturday","title_vi":"Bảo trì VPN vào thứ Bảy này","paras":[[["Notice: VPN maintenance this Saturday","Thông báo: Bảo trì VPN vào thứ Bảy này"]],[["The IT team will carry out maintenance on the company VPN this Saturday, March 14.","Nhóm IT sẽ tiến hành bảo trì VPN của công ty vào thứ Bảy này, ngày 14 tháng 3."],["The work will start at 9 p.m. and last about four hours.","Công việc sẽ bắt đầu lúc 9 giờ tối và kéo dài khoảng bốn tiếng."],["During this time, you will not be able to access the code repository or the test servers from home.","Trong thời gian này, bạn sẽ không thể truy cập kho mã nguồn hoặc các server test từ nhà."]],[["The office network will not be affected.","Mạng nội bộ tại văn phòng sẽ không bị ảnh hưởng."],["If you plan to deploy a release on Saturday evening, please move it to Sunday morning.","Nếu bạn định deploy một bản release vào tối thứ Bảy, vui lòng dời sang sáng Chủ nhật."],["After the update, you must install the new VPN client before Monday.","Sau khi cập nhật, bạn phải cài đặt VPN client mới trước thứ Hai."],["The download link will be sent by email on Sunday.","Đường link tải về sẽ được gửi qua email vào Chủ nhật."]],[["For questions, contact Daniel Cho at the IT help desk, extension 214.","Nếu có câu hỏi, hãy liên hệ Daniel Cho ở bộ phận hỗ trợ IT, số máy lẻ 214."]]],"vocab":[{"w":"carry out","f":"carry out","pos":"phrase","ipa":"","vi":"tiến hành, thực hiện"},{"w":"access","f":"access","pos":"n/v","ipa":"/ˈæksɛs/","vi":"quyền truy cập, lối vào; tiếp cận"},{"w":"affect","f":"affected","pos":"v","ipa":"/əˈfekt/","vi":"ảnh hưởng"},{"w":"network","f":"network","pos":"n/v","ipa":"/ˈnɛt.wɜːrk/","vi":"mạng lưới; kết nối mạng"},{"w":"deploy","f":"deploy","pos":"v","ipa":"/dɪˈplɔɪ/","vi":"triển khai"},{"w":"release","f":"release","pos":"v/n","ipa":"/rɪˈliːs/","vi":"phát hành, tung ra; sự phát hành"},{"w":"contact","f":"contact","pos":"n/v","ipa":"/ˈkɑːntækt/","vi":"liên hệ; sự liên lạc"},{"w":"download","f":"download","pos":"v/n","ipa":"/ˈdaʊnloʊd/","vi":"tải xuống"}],"questions":[{"q":"How long will the maintenance last?","o":["Two hours","About four hours","Until Monday","Nine hours"],"a":1,"vi":"Câu 'The work will start at 9 p.m. and last about four hours.' cho biết kéo dài khoảng bốn tiếng. '9' là giờ bắt đầu (9 p.m.), không phải số giờ."},{"q":"What should staff do with a release planned for Saturday evening?","o":["Cancel it","Deploy it from the office","Ask Daniel Cho to deploy it","Move it to Sunday morning"],"a":3,"vi":"Thông báo ghi 'please move it to Sunday morning'. Mạng văn phòng không bị ảnh hưởng nhưng không hề bảo deploy từ văn phòng; Daniel Cho chỉ là người giải đáp thắc mắc."},{"q":"When will the download link for the new VPN client be sent?","o":["On Sunday","On Saturday evening","On Monday","Before the maintenance starts"],"a":0,"vi":"'The download link will be sent by email on Sunday.' Thứ Hai là hạn cài đặt client mới, không phải ngày gửi link."}],"words":109},{"id":"r1-02","level":1,"type":"email","topic":"HR","title":"Mid-year performance reviews","title_vi":"Đánh giá hiệu suất giữa năm","head":[["From","Grace Tan <grace.tan@lumora-tech.com>"],["To","Engineering team"],["Subject","Mid-year performance reviews"]],"paras":[[["Hi everyone,","Chào mọi người,"]],[["Our mid-year performance reviews will run from June 10 to June 21.","Đợt đánh giá hiệu suất giữa năm của chúng ta sẽ diễn ra từ ngày 10 đến ngày 21 tháng 6."],["Before your meeting, please complete the self-assessment form in the HR portal.","Trước buổi gặp, vui lòng hoàn thành mẫu tự đánh giá trên cổng thông tin HR."],["The deadline for the form is June 7.","Hạn chót nộp mẫu này là ngày 7 tháng 6."]],[["This year, there is one change.","Năm nay có một thay đổi."],["Each review will include feedback from two teammates, not only from your manager.","Mỗi buổi đánh giá sẽ có thêm phản hồi từ hai đồng nghiệp, chứ không chỉ từ quản lý của bạn."],["You can choose these teammates yourself, but you must send me their names by June 3.","Bạn có thể tự chọn hai đồng nghiệp này, nhưng phải gửi tên của họ cho tôi trước ngày 3 tháng 6."]],[["Your manager will send you a calendar invite for a 45-minute meeting.","Quản lý của bạn sẽ gửi cho bạn lời mời trên lịch cho một buổi gặp 45 phút."],["If you are on vacation during the review period, please let me know as soon as possible.","Nếu bạn nghỉ phép trong thời gian đánh giá, vui lòng báo cho tôi càng sớm càng tốt."]],[["Best regards,","Trân trọng,"],["Grace Tan, HR Business Partner","Grace Tan, HR Business Partner"]]],"vocab":[{"w":"performance","f":"performance","pos":"n","ipa":"/pərˈfɔrməns/","vi":"Hiệu suất, hiệu năng"},{"w":"review","f":"review","pos":"n/v","ipa":"/rɪˈvyu/","vi":"xem xét, đánh giá"},{"w":"complete","f":"complete","pos":"adj/v","ipa":"/kəmˈpliːt/","vi":"hoàn thành, đầy đủ"},{"w":"deadline","f":"deadline","pos":"n","ipa":"/ˈdɛˌdlaɪn/","vi":"hạn chót"},{"w":"feedback","f":"feedback","pos":"n","ipa":"/ˈfidˌbæk/","vi":"phản hồi; ý kiến đóng góp"},{"w":"manager","f":"manager","pos":"n","ipa":"/ˈmænɪdʒər/","vi":"quản lý"},{"w":"calendar","f":"calendar","pos":"n","ipa":"/ˈkæləndər/","vi":"lịch"},{"w":"invite","f":"invite","pos":"v","ipa":"/ɪnˈvaɪt/","vi":"mời"},{"w":"vacation","f":"vacation","pos":"n","ipa":"/veɪˈkeɪʃən/","vi":"kỳ nghỉ; sự nghỉ phép"},{"w":"period","f":"period","pos":"n","ipa":"/ˈpɪriəd/","vi":"giai đoạn, thời kỳ; dấu chấm"},{"w":"let me know","f":"let me know","pos":"phrase","ipa":"/ˌlɛmi ˈnoʊ/","vi":"cho tôi biết nhé"},{"w":"as soon as","f":"as soon as","pos":"phrase","ipa":"/əˈsunəz/","vi":"ngay khi (nối âm)"}],"questions":[{"q":"What is the deadline for the self-assessment form?","o":["June 3","June 10","June 7","June 21"],"a":2,"vi":"'The deadline for the form is June 7.' Ngày 3/6 là hạn gửi tên đồng nghiệp; 10-21/6 là thời gian đánh giá."},{"q":"What is new in this year's reviews?","o":["Feedback from two teammates is included","Meetings are 45 minutes long","Managers choose the teammates","The form is in the HR portal"],"a":0,"vi":"Sau câu 'there is one change' là 'Each review will include feedback from two teammates'. Các phương án khác có trong bài nhưng không phải là thay đổi; nhân viên tự chọn đồng nghiệp, không phải quản lý."},{"q":"What should staff do if they are on vacation during the review period?","o":["Cancel their review","Ask a teammate to join instead","Complete the form after June 21","Tell Grace Tan as soon as possible"],"a":3,"vi":"'If you are on vacation during the review period, please let me know as soon as possible.' Người viết ('me') là Grace Tan."}],"words":105},{"id":"r1-03","level":1,"type":"chat","topic":"Office","title":"Moving to the 5th floor","title_vi":"Chuyển lên tầng 5","paras":[[["Lena (Office Manager): Hi all, a quick update about the office move.","Lena (Quản lý văn phòng): Chào mọi người, cập nhật nhanh về việc chuyển chỗ làm việc."]],[["Lena: The AI team will move from the 3rd floor to the 5th floor next Friday.","Lena: Nhóm AI sẽ chuyển từ tầng 3 lên tầng 5 vào thứ Sáu tuần sau."],["Lena: Please pack your desk into the boxes by 5 p.m. on Thursday.","Lena: Vui lòng cho đồ trên bàn làm việc vào thùng trước 5 giờ chiều thứ Năm."]],[["Huy: Will the movers take our monitors too?","Huy: Bên chuyển đồ có mang cả màn hình của chúng tôi không?"]],[["Lena: Yes, but please take your laptops home on Thursday night.","Lena: Có, nhưng vui lòng mang laptop về nhà vào tối thứ Năm."]],[["Priya: What about the GPU server in room 302?","Priya: Còn server GPU ở phòng 302 thì sao?"]],[["Lena: It will stay on the 3rd floor until the new server room is ready in April.","Lena: Nó sẽ ở lại tầng 3 cho đến khi phòng server mới sẵn sàng vào tháng 4."]],[["Huy: Should we work from home on Friday?","Huy: Thứ Sáu chúng tôi có nên làm việc ở nhà không?"]],[["Lena: Yes, everyone on the team should work from home that day.","Lena: Đúng vậy, mọi người trong nhóm nên làm việc ở nhà hôm đó."],["Lena: Your new desks will be ready on Monday morning.","Lena: Bàn làm việc mới của các bạn sẽ sẵn sàng vào sáng thứ Hai."],["Lena: Let me know if you have any questions.","Lena: Nếu có câu hỏi gì thì cứ báo mình nhé."]]],"vocab":[{"w":"a quick update","f":"a quick update","pos":"phrase","ipa":"","vi":"cập nhật nhanh"},{"w":"monitor","f":"monitors","pos":"n/v","ipa":"/ˈmɑnətər/","vi":"màn hình; giám sát, theo dõi"},{"w":"ready","f":"ready","pos":"adj","ipa":"/ˈredi/","vi":"sẵn sàng"},{"w":"stay","f":"stay","pos":"v/n","ipa":"/steɪ/","vi":"ở lại, duy trì; sự ở lại"},{"w":"laptop","f":"laptops","pos":"n","ipa":"/ˈlæpˌtɑp/","vi":"máy tính xách tay"},{"w":"what about","f":"what about","pos":"phrase","ipa":"/ˌwʌɾəˈbaʊt/","vi":"còn ... thì sao (nối âm)"},{"w":"manager","f":"manager","pos":"n","ipa":"/ˈmænɪdʒər/","vi":"quản lý"},{"w":"let me know if you have any questions","f":"let me know if you have any questions","pos":"phrase","ipa":"","vi":"có câu hỏi gì cứ báo tôi"}],"questions":[{"q":"When must staff pack their desks?","o":["Next Friday morning","Monday morning","Thursday night","By 5 p.m. on Thursday"],"a":3,"vi":"'Please pack your desk into the boxes by 5 p.m. on Thursday.' Tối thứ Năm là lúc mang laptop về nhà; sáng thứ Hai là lúc bàn mới sẵn sàng."},{"q":"What will happen to the GPU server?","o":["It will move to the 5th floor next Friday","It will stay on the 3rd floor until April","Huy will take it home","It will move to room 302"],"a":1,"vi":"Lena trả lời Priya: 'It will stay on the 3rd floor until the new server room is ready in April.' Phòng 302 là nơi server đang đặt."},{"q":"What should the team do next Friday?","o":["Pack their boxes","Go to the 5th floor","Work from home","Set up the new server room"],"a":2,"vi":"Huy hỏi có nên làm ở nhà vào thứ Sáu không, Lena trả lời 'everyone on the team should work from home that day'. Việc đóng thùng phải xong trước thứ Năm."}],"words":126},{"id":"r1-04","level":1,"type":"email","topic":"Travel","title":"Your trip to Osaka","title_vi":"Chuyến công tác Osaka của bạn","head":[["From","Mai Hoang <mai.hoang@kestrelsoft.com>"],["To","Linh Tran"],["Subject","Your trip to Osaka"]],"paras":[[["Hi Linh,","Chào Linh,"]],[["Your trip to Osaka for the Hanabi Retail workshop is now booked.","Chuyến đi Osaka của bạn để dự buổi workshop với Hanabi Retail đã được đặt xong."],["You will fly out on Tuesday, May 5, at 8:40 a.m. and return on Friday, May 8.","Bạn sẽ bay đi vào thứ Ba, ngày 5 tháng 5, lúc 8 giờ 40 sáng và trở về vào thứ Sáu, ngày 8 tháng 5."],["Your hotel is a ten-minute walk from the client's office.","Khách sạn của bạn cách văn phòng khách hàng mười phút đi bộ."]],[["The company will pay for your flight and hotel directly.","Công ty sẽ thanh toán trực tiếp vé máy bay và khách sạn cho bạn."],["For meals and taxis, you can spend up to 60 dollars per day.","Với chi phí ăn uống và taxi, bạn có thể chi tối đa 60 đô la mỗi ngày."],["Please keep all receipts and send your expense report within two weeks after you return.","Vui lòng giữ lại tất cả hóa đơn và gửi báo cáo chi phí trong vòng hai tuần sau khi trở về."]],[["One more thing: the client asked us to bring a demo of the new search model.","Một điều nữa: khách hàng đã đề nghị chúng ta mang theo bản demo của mô hình tìm kiếm mới."],["Please check with Ken that it runs on your laptop before you leave.","Vui lòng kiểm tra cùng Ken để chắc chắn nó chạy được trên laptop của bạn trước khi đi."]],[["Have a good trip!","Chúc bạn có một chuyến đi suôn sẻ!"],["Mai","Mai"]]],"vocab":[{"w":"workshop","f":"workshop","pos":"n","ipa":"/ˈwɜrkˌʃɑp/","vi":"hội thảo; xưởng"},{"w":"client","f":"client","pos":"n","ipa":"/ˈklaɪənt/","vi":"khách hàng"},{"w":"return","f":"return","pos":"n/v","ipa":"/rɪˈtɜːrn/","vi":"trở về, trả lại; sự hoàn trả"},{"w":"directly","f":"directly","pos":"adv","ipa":"/dəˈrektli/","vi":"trực tiếp"},{"w":"expense","f":"expense","pos":"n","ipa":"/ɪkˈspens/","vi":"chi phí"},{"w":"receipt","f":"receipts","pos":"n","ipa":"/rɪˈsit/","vi":"biên lai; hóa đơn"},{"w":"trip","f":"trip","pos":"n/v","ipa":"/trɪp/","vi":"chuyến đi công tác; vấp ngã"},{"w":"search","f":"search","pos":"n/v","ipa":"/sɜːrtʃ/","vi":"tìm kiếm"},{"w":"model","f":"model","pos":"n/v","ipa":"/ˈmɑːdl/","vi":"mô hình; mẫu"},{"w":"check","f":"check","pos":"v/n","ipa":"/tʃɛk/","vi":"kiểm tra; sự kiểm tra"}],"questions":[{"q":"How much can Linh spend on meals and taxis?","o":["Up to 60 dollars per day","60 dollars for the whole trip","Nothing, because the company pays directly","Up to 60 dollars per meal"],"a":0,"vi":"'For meals and taxis, you can spend up to 60 dollars per day.' Công ty chỉ trả trực tiếp vé máy bay và khách sạn."},{"q":"When should Linh send the expense report?","o":["Before leaving for Osaka","On May 8","Within two weeks after returning","Within ten days"],"a":2,"vi":"'send your expense report within two weeks after you return'. 8/5 là ngày về; 'ten-minute' là khoảng cách đi bộ đến khách sạn."},{"q":"What did the client ask for?","o":["A hotel near the office","A demo of the new search model","A new laptop","A longer workshop"],"a":1,"vi":"'the client asked us to bring a demo of the new search model.' Khách sạn gần văn phòng là do công ty đặt, không phải yêu cầu của khách hàng."}],"words":115},{"id":"r1-05","level":1,"type":"notice","topic":"Events","title":"Spring hackathon","title_vi":"Hackathon mùa xuân","paras":[[["Spring Hackathon: Sign-up Now Open","Hackathon mùa xuân: Đã mở đăng ký"]],[["Our yearly hackathon will be on April 18 and 19 at the main office.","Cuộc thi hackathon hằng năm của chúng ta sẽ diễn ra vào ngày 18 và 19 tháng 4 tại văn phòng chính."],["This year, the goal is to build tools that save time for our support team.","Năm nay, mục tiêu là xây dựng các công cụ giúp đội hỗ trợ khách hàng tiết kiệm thời gian."],["Teams can have three to five people.","Mỗi đội có thể có từ ba đến năm người."]],[["To join, register your team on the events page by April 4.","Để tham gia, hãy đăng ký đội của bạn trên trang sự kiện trước ngày 4 tháng 4."],["Each team will demonstrate its project in five minutes on Sunday afternoon.","Mỗi đội sẽ trình diễn dự án của mình trong năm phút vào chiều Chủ nhật."],["The winning team will receive 1,000 dollars and the chance to build its idea in the next quarter.","Đội chiến thắng sẽ nhận 1.000 đô la và cơ hội phát triển ý tưởng của mình trong quý tới."]],[["Food and drinks will be free on both days.","Đồ ăn và thức uống sẽ được miễn phí trong cả hai ngày."],["Because the room is small, only the first 12 teams can participate.","Vì phòng nhỏ nên chỉ 12 đội đăng ký đầu tiên được tham gia."],["For questions, contact the organizer, Sara Kim, at sara.kim@talonworks.com.","Nếu có câu hỏi, hãy liên hệ người tổ chức, Sara Kim, qua địa chỉ sara.kim@talonworks.com."]]],"vocab":[{"w":"yearly","f":"yearly","pos":"adj/adv","ipa":"/ˈjɪrli/","vi":"hàng năm"},{"w":"register","f":"register","pos":"v/n","ipa":"/ˈredʒɪstər/","vi":"đăng ký; sổ sách"},{"w":"demonstrate","f":"demonstrate","pos":"v","ipa":"/ˈdɛmənˌstreɪt/","vi":"chứng minh, thể hiện; demo sản phẩm"},{"w":"receive","f":"receive","pos":"v","ipa":"/rɪˈsiːv/","vi":"nhận"},{"w":"chance","f":"chance","pos":"n","ipa":"/tʃæns/","vi":"Cơ hội, sự may rủi"},{"w":"quarter","f":"quarter","pos":"n","ipa":"/ˈkwɔːrtər/","vi":"quý (trong năm)"},{"w":"free","f":"free","pos":"adj/v","ipa":"/friː/","vi":"miễn phí; rảnh rỗi"},{"w":"participate","f":"participate","pos":"v","ipa":"/pɑːrˈtɪsəpeɪt/","vi":"tham gia"},{"w":"organizer","f":"organizer","pos":"n","ipa":"/ˈɔːrɡənaɪzər/","vi":"người tổ chức, vật dụng sắp xếp"},{"w":"goal","f":"goal","pos":"n","ipa":"/ɡoʊl/","vi":"mục tiêu"},{"w":"tool","f":"tools","pos":"n","ipa":"/tul/","vi":"công cụ, dụng cụ"}],"questions":[{"q":"What is the deadline to register a team?","o":["April 18","April 4","April 19","Sunday afternoon"],"a":1,"vi":"'register your team on the events page by April 4.' Ngày 18-19/4 là ngày diễn ra hackathon; chiều Chủ nhật là lúc các đội trình diễn."},{"q":"What will the winning team get?","o":["1,000 dollars and a chance to build its idea","Free food for the next quarter","A five-minute meeting with Sara Kim","A place on the support team"],"a":0,"vi":"'The winning team will receive 1,000 dollars and the chance to build its idea in the next quarter.' Đồ ăn miễn phí chỉ trong hai ngày thi, cho tất cả mọi người."},{"q":"Why can only 12 teams take part?","o":["The prize money is small","Teams have up to five people","The hackathon lasts only two days","The room is small"],"a":3,"vi":"'Because the room is small, only the first 12 teams can participate.' Các phương án khác đều có thông tin trong bài nhưng không phải là lý do."}],"words":117},{"id":"r1-06","level":1,"type":"memo","topic":"HR","title":"Changes to expense claims","title_vi":"Thay đổi về hoàn tiền chi phí","head":[["From","HR and Finance"],["To","All staff"],["Date","October 1"],["Subject","Changes to expense claims"]],"paras":[[["Starting November 1, all expense claims must be sent through our new app, ClaimPad.","Bắt đầu từ ngày 1 tháng 11, mọi yêu cầu hoàn tiền chi phí phải được gửi qua ứng dụng mới của chúng ta, ClaimPad."],["We will no longer accept paper forms or claims by email.","Chúng tôi sẽ không còn chấp nhận mẫu giấy hoặc yêu cầu gửi qua email."]],[["Please take a photo of each receipt and add it to your claim.","Vui lòng chụp ảnh từng hóa đơn và đính kèm vào yêu cầu của bạn."],["Claims must be sent within 30 days of the purchase.","Yêu cầu phải được gửi trong vòng 30 ngày kể từ ngày mua."],["Your team leader will review them, and the payment will come with your monthly pay.","Trưởng nhóm của bạn sẽ xem xét, và khoản tiền sẽ được trả cùng lương hằng tháng."]],[["We are making this change because paper claims took up to six weeks.","Chúng tôi thực hiện thay đổi này vì các yêu cầu bằng giấy mất tới sáu tuần mới xử lý xong."],["With the app, most claims will be paid in less than ten days.","Với ứng dụng này, hầu hết các yêu cầu sẽ được thanh toán trong vòng chưa đầy mười ngày."]],[["A short online session about the app will be held on October 20 at 3 p.m.","Một buổi hướng dẫn trực tuyến ngắn về ứng dụng sẽ được tổ chức vào ngày 20 tháng 10 lúc 3 giờ chiều."],["It is optional, but we recommend it for all team leaders.","Buổi này không bắt buộc, nhưng chúng tôi khuyến khích tất cả trưởng nhóm tham dự."]]],"vocab":[{"w":"expense","f":"expense","pos":"n","ipa":"/ɪkˈspens/","vi":"chi phí"},{"w":"accept","f":"accept","pos":"v","ipa":"/əkˈsɛpt/","vi":"Chấp nhận, thừa nhận"},{"w":"receipt","f":"receipt","pos":"n","ipa":"/rɪˈsit/","vi":"biên lai; hóa đơn"},{"w":"purchase","f":"purchase","pos":"n/v","ipa":"/ˈpɜːrtʃəs/","vi":"mua hàng; vật phẩm, sự mua"},{"w":"review","f":"review","pos":"n/v","ipa":"/rɪˈvyu/","vi":"xem xét, đánh giá"},{"w":"payment","f":"payment","pos":"n","ipa":"/ˈpeɪmənt/","vi":"thanh toán"},{"w":"optional","f":"optional","pos":"adj","ipa":"/ˈɑːpʃənl/","vi":"tùy chọn; không bắt buộc"},{"w":"recommend","f":"recommend","pos":"v","ipa":"/ˌrekəˈmend/","vi":"giới thiệu, đề xuất"},{"w":"leader","f":"leader","pos":"n","ipa":"/ˈliːdər/","vi":"lãnh đạo, người dẫn đầu"}],"questions":[{"q":"When does the new process start?","o":["October 1","October 20","November 1","In 30 days"],"a":2,"vi":"'Starting November 1, all expense claims must be sent through our new app.' 1/10 là ngày ra thông báo; 20/10 là buổi hướng dẫn."},{"q":"Why is the company making this change?","o":["Team leaders asked for an app","Receipts were often lost","Monthly pay was often late","Paper claims took too long"],"a":3,"vi":"'We are making this change because paper claims took up to six weeks.' Bài không nói hóa đơn bị mất hay trưởng nhóm yêu cầu ứng dụng."},{"q":"Who is the online session recommended for?","o":["Team leaders","All new staff","The Finance team only","Staff with paper claims"],"a":0,"vi":"'It is optional, but we recommend it for all team leaders.'"}],"words":117},{"id":"r1-07","level":1,"type":"chat","topic":"IT","title":"Nightly pipeline failed","title_vi":"Pipeline chạy đêm bị lỗi","paras":[[["Omar: Morning, team. The nightly data pipeline failed at 2:15 a.m.","Omar: Chào buổi sáng cả nhóm. Data pipeline chạy hằng đêm đã bị lỗi lúc 2 giờ 15 sáng."],["Omar: Because of this, the sales dashboard still shows yesterday's numbers.","Omar: Vì vậy, dashboard bán hàng vẫn đang hiển thị số liệu của hôm qua."]],[["Thu: I checked the logs.","Thu: Mình đã kiểm tra log rồi."],["Thu: One of our vendors changed the date format in their file without telling us.","Thu: Một nhà cung cấp đã đổi định dạng ngày trong file của họ mà không báo cho chúng ta."]],[["Omar: Can you fix it today?","Omar: Bạn có sửa được trong hôm nay không?"]],[["Thu: Yes, I can push a fix by 11 a.m. and run the job again.","Thu: Được, mình có thể đẩy bản sửa trước 11 giờ sáng và chạy lại job."],["Thu: It takes about 40 minutes.","Thu: Việc đó mất khoảng 40 phút."]],[["Omar: Great. I will tell the sales team that the dashboard will be fixed before lunch.","Omar: Tốt. Mình sẽ báo đội sales rằng dashboard sẽ được sửa xong trước giờ ăn trưa."]],[["Ben: I will contact the vendor and ask them to tell us in advance about any changes.","Ben: Mình sẽ liên hệ nhà cung cấp và yêu cầu họ báo trước cho chúng ta về mọi thay đổi."]],[["Omar: Thanks. Let's add a format check to the pipeline in the next sprint.","Omar: Cảm ơn. Hãy thêm bước kiểm tra định dạng vào pipeline trong sprint tới."]]],"vocab":[{"w":"pipeline","f":"pipeline","pos":"n","ipa":"/ˈpaɪplaɪn/","vi":"đường ống; quy trình xử lý"},{"w":"fail","f":"failed","pos":"v","ipa":"/feɪl/","vi":"thất bại; hỏng"},{"w":"vendor","f":"vendor","pos":"n","ipa":"/ˈvɛndər/","vi":"nhà cung cấp, người bán hàng"},{"w":"fix","f":"fix","pos":"v/n","ipa":"/fɪks/","vi":"sửa lỗi; giải pháp"},{"w":"push","f":"push","pos":"v/n","ipa":"/pʊʃ/","vi":"đẩy, đưa lên; cú đẩy"},{"w":"contact","f":"contact","pos":"n/v","ipa":"/ˈkɑːntækt/","vi":"liên hệ; sự liên lạc"},{"w":"in advance","f":"in advance","pos":"phrase","ipa":"","vi":"trước, sẵn"},{"w":"in the next sprint","f":"in the next sprint","pos":"phrase","ipa":"","vi":"trong sprint tới"},{"w":"data","f":"data","pos":"n","ipa":"/ˈdeɪtə/","vi":"Dữ liệu"},{"w":"file","f":"file","pos":"n/v","ipa":"/faɪl/","vi":"tài liệu, tệp tin; lưu trữ"}],"questions":[{"q":"What caused the pipeline failure?","o":["A server crash at 2:15 a.m.","A bug in the sales dashboard","A missing log file","A vendor changed its date format"],"a":3,"vi":"Thu kiểm tra log và thấy 'One of our vendors changed the date format in their file without telling us.' 2:15 a.m. chỉ là thời điểm lỗi xảy ra."},{"q":"When will the dashboard probably be fixed?","o":["At 2:15 a.m.","In the next sprint","Before lunch","At the end of the day"],"a":2,"vi":"Omar nói 'the dashboard will be fixed before lunch' (sửa trước 11 giờ, chạy lại 40 phút). Sprint tới là lúc thêm bước kiểm tra định dạng."},{"q":"What will Ben do?","o":["Push a fix by 11 a.m.","Contact the vendor","Tell the sales team","Add a format check"],"a":1,"vi":"'Ben: I will contact the vendor...' Đẩy bản sửa là việc của Thu; báo đội sales là việc của Omar."}],"words":119},{"id":"r1-08","level":1,"type":"email","topic":"Office","title":"Your first day on Monday","title_vi":"Ngày làm việc đầu tiên vào thứ Hai","head":[["From","Rachel Wong <rachel@quillbyte.io>"],["To","Kevin Do"],["Subject","Your first day on Monday"]],"paras":[[["Dear Kevin,","Kevin thân mến,"]],[["Welcome to Quillbyte!","Chào mừng bạn đến với Quillbyte!"],["We are happy to have you on the platform team.","Chúng tôi rất vui khi có bạn trong nhóm platform."],["Your first day is Monday, July 7.","Ngày làm việc đầu tiên của bạn là thứ Hai, ngày 7 tháng 7."],["Please arrive at 9:30 a.m. and go to reception on the 2nd floor.","Vui lòng đến lúc 9 giờ 30 sáng và tới quầy lễ tân ở tầng 2."],["Bring your ID card, because you will need it to get your building pass.","Hãy mang theo căn cước, vì bạn sẽ cần nó để làm thẻ ra vào tòa nhà."]],[["In the morning, IT will set up your laptop and accounts.","Buổi sáng, bộ phận IT sẽ cài đặt laptop và các tài khoản cho bạn."],["After lunch, your mentor, Tomas Silva, will show you our code and the release process.","Sau bữa trưa, người hướng dẫn của bạn, Tomas Silva, sẽ giới thiệu cho bạn về code và quy trình release."],["During your first two weeks, you will not need to handle production incidents.","Trong hai tuần đầu, bạn sẽ chưa phải xử lý các sự cố trên production."]],[["If you have any questions before Monday, feel free to reply to this email.","Nếu có bất kỳ câu hỏi nào trước thứ Hai, cứ thoải mái trả lời email này."]],[["Rachel Wong, Engineering Manager","Rachel Wong, Quản lý kỹ thuật"]]],"vocab":[{"w":"arrive","f":"arrive","pos":"v","ipa":"/əˈraɪv/","vi":"đến"},{"w":"reception","f":"reception","pos":"n","ipa":"/rɪˈsɛpʃn/","vi":"quầy lễ tân; tiệc chiêu đãi"},{"w":"pass","f":"pass","pos":"v/n","ipa":"/pæs/","vi":"vượt qua, đỗ"},{"w":"set up","f":"set up","pos":"phrase","ipa":"","vi":"thiết lập, sắp xếp"},{"w":"account","f":"accounts","pos":"n/v","ipa":"/əˈkaʊnt/","vi":"tài khoản; giải thích"},{"w":"mentor","f":"mentor","pos":"n/v","ipa":"/ˈmentɔːr/","vi":"người hướng dẫn; hướng dẫn"},{"w":"release","f":"release","pos":"v/n","ipa":"/rɪˈliːs/","vi":"phát hành, tung ra; sự phát hành"},{"w":"production","f":"production","pos":"n","ipa":"/prəˈdʌkʃən/","vi":"sự sản xuất; môi trường thật"},{"w":"handle","f":"handle","pos":"v/n","ipa":"/ˈhændl/","vi":"xử lý, giải quyết; tay cầm"},{"w":"reply","f":"reply","pos":"v/n","ipa":"/rɪˈplaɪ/","vi":"trả lời; hồi âm"}],"questions":[{"q":"What should Kevin bring on his first day?","o":["His ID card","His own laptop","A building pass","A copy of his contract"],"a":0,"vi":"'Bring your ID card, because you will need it to get your building pass.' Thẻ ra vào là thứ sẽ được cấp, không phải thứ mang theo; laptop do IT cài đặt."},{"q":"Who will show Kevin the release process?","o":["Rachel Wong","Tomas Silva","The IT team","The receptionist"],"a":1,"vi":"'your mentor, Tomas Silva, will show you our code and the release process.' IT chỉ cài đặt laptop và tài khoản."},{"q":"What is true about Kevin's first two weeks?","o":["He will work on the 2nd floor","He will set up his own accounts","He will not handle production incidents","He will lead the platform team"],"a":2,"vi":"'During your first two weeks, you will not need to handle production incidents.' Tầng 2 chỉ là nơi có quầy lễ tân."}],"words":108},{"id":"r1-09","level":1,"type":"memo","topic":"Events","title":"Training on model evaluation","title_vi":"Khóa đào tạo về đánh giá mô hình","head":[["From","Anh Pham, AI Lead"],["To","AI and Data teams"],["Date","September 2"],["Subject","Training on model evaluation"]],"paras":[[["Next month, we will run a two-day training on how to test our AI models.","Tháng tới, chúng ta sẽ tổ chức một khóa đào tạo hai ngày về cách kiểm thử các mô hình AI."],["The sessions will be on October 8 and 9 in Room A on the 6th floor.","Các buổi học sẽ diễn ra vào ngày 8 và 9 tháng 10 tại Phòng A, tầng 6."]],[["The trainer is Marco Lee from our partner, Bluefin Labs.","Giảng viên là Marco Lee đến từ công ty đối tác của chúng ta, Bluefin Labs."],["He will cover test data, accuracy metrics, and human review.","Anh ấy sẽ trình bày về dữ liệu kiểm thử, các chỉ số độ chính xác và việc đánh giá bởi con người."]],[["We require everyone on the chatbot project to attend.","Chúng tôi yêu cầu tất cả thành viên dự án chatbot tham dự."],["Others are welcome to join, but the room only holds 30 people.","Những người khác cũng có thể tham gia, nhưng phòng chỉ chứa được 30 người."]],[["Before the training, please read the short guide in the shared folder.","Trước khóa đào tạo, vui lòng đọc tài liệu hướng dẫn ngắn trong thư mục chung."],["Please confirm that you will attend by sending a message to Jin by September 25.","Vui lòng xác nhận việc tham dự bằng cách nhắn tin cho Jin trước ngày 25 tháng 9."]]],"vocab":[{"w":"trainer","f":"trainer","pos":"n","ipa":"/ˈtreɪnər/","vi":"giảng viên; huấn luyện viên"},{"w":"partner","f":"partner","pos":"n/v","ipa":"/ˈpɑːrtnər/","vi":"đối tác; cộng tác"},{"w":"cover","f":"cover","pos":"v/n","ipa":"/ˈkʌvər/","vi":"bao phủ, chi trả; vỏ bọc"},{"w":"accuracy","f":"accuracy","pos":"n","ipa":"/ˈækjərəsi/","vi":"độ chính xác"},{"w":"metric","f":"metrics","pos":"n","ipa":"/ˈmetrɪk/","vi":"số đo, hệ thống đo lường"},{"w":"require","f":"require","pos":"v","ipa":"/rɪˈkwaɪər/","vi":"yêu cầu, đòi hỏi"},{"w":"attend","f":"attend","pos":"v","ipa":"/əˈtɛnd/","vi":"tham dự, tham gia"},{"w":"share","f":"shared","pos":"v/n","ipa":"/ʃɛr/","vi":"chia sẻ, dùng chung; cổ phần"},{"w":"folder","f":"folder","pos":"n","ipa":"/ˈfoʊldər/","vi":"thư mục; bìa hồ sơ"},{"w":"guide","f":"guide","pos":"n/v","ipa":"/ɡaɪd/","vi":"hướng dẫn viên; hướng dẫn"},{"w":"confirm","f":"confirm","pos":"v","ipa":"/kənˈfɜːrm/","vi":"xác nhận; khẳng định"}],"questions":[{"q":"Where will the training take place?","o":["At Bluefin Labs","Online","In Room A on the 6th floor","In the chatbot team's office"],"a":2,"vi":"'The sessions will be on October 8 and 9 in Room A on the 6th floor.' Bluefin Labs là công ty của giảng viên, không phải địa điểm."},{"q":"Who must attend the training?","o":["Everyone on the Data team","Only new engineers","The first 30 people who sign up","Everyone on the chatbot project"],"a":3,"vi":"'We require everyone on the chatbot project to attend.' Con số 30 là sức chứa của phòng; người khác chỉ được mời nếu muốn."},{"q":"What should staff do by September 25?","o":["Confirm their attendance with Jin","Read the guide","Send test data to Marco Lee","Book Room A"],"a":0,"vi":"'Please confirm that you will attend by sending a message to Jin by September 25.' Đọc tài liệu là việc cần làm trước khóa học, không gắn với ngày 25/9."}],"words":99},{"id":"r1-10","level":1,"type":"chat","topic":"Travel","title":"Flight delay before the conference","title_vi":"Chuyến bay bị hoãn trước hội nghị","paras":[[["Nam: Hi Julia, my flight to Berlin has a five-hour delay.","Nam: Chào Julia, chuyến bay đi Berlin của mình bị hoãn năm tiếng."],["Nam: I will arrive at 11 p.m. instead of 6 p.m.","Nam: Mình sẽ đến nơi lúc 11 giờ đêm thay vì 6 giờ tối."]],[["Julia: Oh no. Your talk at the conference is tomorrow at 10 a.m., right?","Julia: Ôi không. Bài nói của bạn ở hội nghị là lúc 10 giờ sáng mai, đúng không?"]],[["Nam: Yes. I will still be there on time, but I will miss the speakers' dinner tonight.","Nam: Đúng vậy. Mình vẫn sẽ đến kịp giờ, nhưng sẽ lỡ bữa tối dành cho diễn giả tối nay."]],[["Julia: No problem. I will tell the organizer.","Julia: Không sao. Mình sẽ báo cho ban tổ chức."],["Julia: Should I change your hotel reservation?","Julia: Mình có nên đổi đặt phòng khách sạn của bạn không?"]],[["Nam: Please just ask them to keep the room for a late check-in.","Nam: Bạn chỉ cần nhờ họ giữ phòng vì mình sẽ nhận phòng muộn nhé."]],[["Julia: Done. The hotel will keep the room until 2 a.m.","Julia: Xong rồi. Khách sạn sẽ giữ phòng đến 2 giờ sáng."]],[["Nam: Thanks! Also, could you send me the final version of my slides?","Nam: Cảm ơn! Ngoài ra, bạn có thể gửi cho mình bản cuối cùng của slide không?"]],[["Julia: Sure, I will email them in a bit.","Julia: Chắc chắn rồi, lát nữa mình sẽ gửi email cho bạn."]]],"vocab":[{"w":"delay","f":"delay","pos":"n/v","ipa":"/dɪˈleɪ/","vi":"sự chậm trễ; trì hoãn"},{"w":"instead of","f":"instead of","pos":"phrase","ipa":"","vi":"thay vì"},{"w":"conference","f":"conference","pos":"n","ipa":"/ˈkɑnfərəns/","vi":"hội nghị, cuộc họp lớn"},{"w":"on time","f":"on time","pos":"phrase","ipa":"","vi":"đúng giờ, đúng hạn"},{"w":"miss","f":"miss","pos":"v","ipa":"/mɪs/","vi":"bỏ lỡ; nhớ"},{"w":"organizer","f":"organizer","pos":"n","ipa":"/ˈɔːrɡənaɪzər/","vi":"người tổ chức, vật dụng sắp xếp"},{"w":"reservation","f":"reservation","pos":"n","ipa":"/ˌrɛzərˈveɪʃən/","vi":"sự đặt chỗ; sự dè dặt"},{"w":"final","f":"final","pos":"adj/n","ipa":"/ˈfaɪnəl/","vi":"cuối cùng"},{"w":"version","f":"version","pos":"n","ipa":"/ˈvɜːrʒn/","vi":"phiên bản"},{"w":"in a bit","f":"in a bit","pos":"phrase","ipa":"","vi":"lát nữa"},{"w":"could you send me","f":"could you send me","pos":"phrase","ipa":"/ˌkʊdʒə ˈsɛn mi/","vi":"bạn gửi tôi ... được không"}],"questions":[{"q":"What time will Nam arrive in Berlin?","o":["6 p.m.","11 p.m.","10 a.m.","2 a.m."],"a":1,"vi":"'I will arrive at 11 p.m. instead of 6 p.m.' 6 giờ tối là giờ dự kiến ban đầu; 10 giờ sáng là giờ bài nói; 2 giờ sáng là giờ khách sạn giữ phòng."},{"q":"What will Nam miss?","o":["The speakers' dinner","His talk at the conference","His hotel check-in","The final slides"],"a":0,"vi":"'I will still be there on time, but I will miss the speakers' dinner tonight.' Anh ấy vẫn kịp bài nói."},{"q":"What did Julia arrange with the hotel?","o":["A booking at another hotel","An early check-in","A room for two nights","Keeping the room until 2 a.m."],"a":3,"vi":"'The hotel will keep the room until 2 a.m.' Nam nhận phòng muộn, không phải sớm, và không đổi khách sạn."}],"words":118},{"id":"r1-11","level":1,"type":"email","topic":"Service","title":"Export bug for Harbor Foods","title_vi":"Lỗi xuất file cho Harbor Foods","head":[["From","Mai Tran <mai.tran@lumenstack.io>"],["To","Dev team"],["Subject","Client request: CSV export bug"]],"paras":[[["Hi team,","Chào cả nhóm,"]],[["Our client Harbor Foods reported a problem yesterday.","Khách hàng Harbor Foods của chúng ta đã báo một sự cố vào hôm qua."],["When they export a report to CSV, the dates are in the wrong format.","Khi họ xuất báo cáo ra file CSV, ngày tháng bị sai định dạng."],["This affects about 40 of their users.","Lỗi này ảnh hưởng đến khoảng 40 người dùng của họ."]],[["Kevin will be in charge of the fix.","Kevin sẽ phụ trách việc sửa lỗi."],["Please make sure it is tested on both Windows and Mac.","Vui lòng đảm bảo bản sửa được kiểm thử trên cả Windows và Mac."],["The client needs the fix by Thursday at noon, because they send monthly reports to their managers on Friday.","Khách hàng cần bản sửa trước trưa thứ Năm, vì họ gửi báo cáo hàng tháng cho các quản lý vào thứ Sáu."]],[["I will follow up on the ticket and keep the client updated.","Tôi sẽ theo dõi ticket này và cập nhật tình hình cho khách hàng."],["Let me know if you need more details.","Hãy cho tôi biết nếu các bạn cần thêm chi tiết."]],[["Thanks,","Cảm ơn,"],["Mai","Mai"]]],"vocab":[{"w":"client","f":"client","pos":"n","ipa":"/ˈklaɪənt/","vi":"khách hàng"},{"w":"affect","f":"affects","pos":"v","ipa":"/əˈfekt/","vi":"ảnh hưởng"},{"w":"user","f":"users","pos":"n","ipa":"/ˈjuːzər/","vi":"người dùng"},{"w":"be in charge of","f":"be in charge of","pos":"phrase","ipa":"","vi":"phụ trách"},{"w":"make sure","f":"make sure","pos":"phrase","ipa":"","vi":"đảm bảo"},{"w":"test","f":"tested","pos":"n/v","ipa":"/tɛst/","vi":"kiểm tra, bài kiểm tra"},{"w":"manager","f":"managers","pos":"n","ipa":"/ˈmænɪdʒər/","vi":"quản lý"},{"w":"follow up on","f":"follow up on","pos":"phrase","ipa":"","vi":"theo dõi tiếp, hỏi lại về"},{"w":"ticket","f":"ticket","pos":"n","ipa":"/ˈtɪkɪt/","vi":"vé; phiếu yêu cầu hỗ trợ"},{"w":"detail","f":"details","pos":"n/v","ipa":"/ˈdiːteɪl/","vi":"chi tiết; trình bày chi tiết"}],"questions":[{"q":"What is the problem with the export?","o":["The dates are in the wrong format","The file is empty","The export is very slow","Some users cannot log in"],"a":0,"vi":"Câu 'the dates are in the wrong format' nêu rõ lỗi. Các lựa chọn khác không được nhắc đến."},{"q":"Who is responsible for fixing the bug?","o":["Mai","Kevin","A manager at Harbor Foods","The Windows team"],"a":1,"vi":"'Kevin will be in charge of the fix' – Kevin phụ trách sửa lỗi. Mai chỉ theo dõi ticket và cập nhật cho khách hàng."},{"q":"Why does the client need the fix by Thursday?","o":["Their contract ends on Thursday","They have 40 new users","They send monthly reports on Friday","They will test it on Mac"],"a":2,"vi":"Câu cuối đoạn 2: 'because they send monthly reports to their managers on Friday'. Con số 40 là số người dùng bị ảnh hưởng, là bẫy."}],"words":91},{"id":"r1-12","level":1,"type":"chat","topic":"Data","title":"Nightly pipeline failed","title_vi":"Pipeline chạy đêm bị lỗi","head":[],"paras":[[["Huy (8:05): Good morning. The nightly data pipeline failed at 2 a.m.","Huy (8:05): Chào buổi sáng. Pipeline dữ liệu chạy đêm đã bị lỗi lúc 2 giờ sáng."],["Huy (8:06): The sales dashboard still shows numbers from Tuesday.","Huy (8:06): Dashboard doanh số vẫn đang hiển thị số liệu từ thứ Ba."]],[["Sara (8:10): Do you know why?","Sara (8:10): Anh có biết vì sao không?"],["Huy (8:12): It looks like the database password expired.","Huy (8:12): Có vẻ như mật khẩu cơ sở dữ liệu đã hết hạn."],["Huy (8:12): I updated it, and I am running the job again now.","Huy (8:12): Tôi đã cập nhật mật khẩu và đang chạy lại job ngay bây giờ."]],[["Sara (8:15): How long will it take?","Sara (8:15): Mất bao lâu vậy anh?"],["Huy (8:16): About 90 minutes, so the data should be ready before 10.","Huy (8:16): Khoảng 90 phút, nên dữ liệu sẽ sẵn sàng trước 10 giờ."]],[["Sara (8:18): Great. The sales team has a meeting at 10:30, so please let me know when it is done.","Sara (8:18): Tốt quá. Nhóm sales có cuộc họp lúc 10:30, nên khi xong anh báo tôi nhé."],["Sara (8:19): Also, could you set a reminder so the password does not expire again?","Sara (8:19): Ngoài ra, anh có thể đặt lời nhắc để mật khẩu không bị hết hạn nữa được không?"],["Huy (8:20): Will do.","Huy (8:20): Được, tôi sẽ làm."]]],"vocab":[{"w":"pipeline","f":"pipeline","pos":"n","ipa":"/ˈpaɪplaɪn/","vi":"đường ống; quy trình xử lý"},{"w":"fail","f":"failed","pos":"v","ipa":"/feɪl/","vi":"thất bại; hỏng"},{"w":"expire","f":"expire","pos":"v","ipa":"/ɪkˈspaɪər/","vi":"hết hạn; kết thúc"},{"w":"password","f":"password","pos":"n","ipa":"/ˈpæswɜːrd/","vi":"mật khẩu"},{"w":"it looks like","f":"it looks like","pos":"phrase","ipa":"","vi":"trông có vẻ như"},{"w":"how long will it take","f":"how long will it take","pos":"phrase","ipa":"","vi":"sẽ mất bao lâu"},{"w":"let me know when","f":"let me know when","pos":"phrase","ipa":"","vi":"báo tôi khi"},{"w":"reminder","f":"reminder","pos":"n","ipa":"/rɪˈmaɪndər/","vi":"lời nhắc; giấy nhắc"},{"w":"will do","f":"will do","pos":"phrase","ipa":"","vi":"sẽ làm vậy"}],"questions":[{"q":"What caused the pipeline to fail?","o":["The dashboard was broken","The job ran too long","The server was turned off","A database password expired"],"a":3,"vi":"Huy viết: 'It looks like the database password expired.' Các phương án khác không phải nguyên nhân."},{"q":"When should the data be ready?","o":["Before 10 a.m.","At 2 a.m.","At 10:30 a.m.","On Tuesday"],"a":0,"vi":"'the data should be ready before 10'. 10:30 là giờ họp của nhóm sales, 2 giờ sáng là lúc lỗi xảy ra."},{"q":"What does Sara ask Huy to do?","o":["Cancel the sales meeting","Set a reminder for the password","Build a new dashboard","Call the sales team"],"a":1,"vi":"Sara hỏi: 'could you set a reminder so the password does not expire again?' và Huy đồng ý 'Will do'."}],"words":121},{"id":"r1-13","level":1,"type":"notice","topic":"Logistics","title":"Office move to the 7th floor","title_vi":"Chuyển văn phòng lên tầng 7","head":[],"paras":[[["Office Move Notice","Thông báo chuyển văn phòng"]],[["The engineering team will move from the 4th floor to the 7th floor on Saturday, March 14.","Nhóm kỹ thuật sẽ chuyển từ tầng 4 lên tầng 7 vào thứ Bảy, ngày 14 tháng 3."],["The new space has more meeting rooms and a quiet area for focus work.","Không gian mới có nhiều phòng họp hơn và một khu yên tĩnh để làm việc tập trung."]],[["Please pack your desk items into the boxes provided by Friday at 5 p.m.","Vui lòng đóng đồ trên bàn làm việc vào các thùng được cung cấp trước 5 giờ chiều thứ Sáu."],["Write your name and new desk number on each box.","Hãy ghi tên và số bàn mới của bạn lên từng thùng."],["Movers will carry the boxes and monitors.","Nhân viên chuyển đồ sẽ mang các thùng và màn hình."],["However, you must take your laptop home over the weekend.","Tuy nhiên, bạn phải mang laptop về nhà trong dịp cuối tuần."]],[["Your access card will work on the new floor from Monday morning.","Thẻ ra vào của bạn sẽ sử dụng được ở tầng mới từ sáng thứ Hai."],["If you have any questions, contact Linda Pham in Facilities at extension 214.","Nếu có câu hỏi, hãy liên hệ chị Linda Pham ở bộ phận Cơ sở vật chất qua số máy lẻ 214."]]],"vocab":[{"w":"notice","f":"notice","pos":"n/v","ipa":"/ˈnoʊtɪs/","vi":"thông báo; chú ý"},{"w":"item","f":"items","pos":"n","ipa":"/ˈaɪtəm/","vi":"mục, món hàng"},{"w":"carry","f":"carry","pos":"v","ipa":"/ˈkæri/","vi":"mang, vác; thực hiện"},{"w":"monitor","f":"monitors","pos":"n/v","ipa":"/ˈmɑnətər/","vi":"màn hình; giám sát, theo dõi"},{"w":"over the weekend","f":"over the weekend","pos":"phrase","ipa":"","vi":"trong cuối tuần"},{"w":"access","f":"access","pos":"n/v","ipa":"/ˈæksɛs/","vi":"quyền truy cập, lối vào; tiếp cận"},{"w":"contact","f":"contact","pos":"n/v","ipa":"/ˈkɑːntækt/","vi":"liên hệ; sự liên lạc"},{"w":"focus","f":"focus","pos":"v/n","ipa":"/ˈfoʊkəs/","vi":"Tập trung; trọng tâm"}],"questions":[{"q":"When is the deadline to pack desk items?","o":["Saturday, March 14","Monday morning","Friday at 5 p.m.","Sunday evening"],"a":2,"vi":"'pack your desk items ... by Friday at 5 p.m.' Thứ Bảy 14/3 là ngày chuyển, sáng thứ Hai là lúc thẻ có hiệu lực."},{"q":"What should employees do with their laptops?","o":["Put them in a box","Give them to Linda Pham","Leave them on the 4th floor","Take them home"],"a":3,"vi":"'you must take your laptop home over the weekend'. Người chuyển đồ chỉ mang thùng và màn hình."},{"q":"What will happen on Monday morning?","o":["Access cards will work on the 7th floor","Movers will carry the monitors","New meeting rooms will be built","Employees will get new laptops"],"a":0,"vi":"'Your access card will work on the new floor from Monday morning.' Việc chuyển màn hình diễn ra vào thứ Bảy."}],"words":101},{"id":"r1-14","level":1,"type":"job","topic":"Product","title":"Junior AI Engineer","title_vi":"Kỹ sư AI cấp junior","head":[],"paras":[[["Junior AI Engineer – Nova Retail Labs","Kỹ sư AI cấp junior – Nova Retail Labs"]],[["Nova Retail Labs is hiring a junior AI engineer for our product search team.","Nova Retail Labs đang tuyển một kỹ sư AI cấp junior cho nhóm tìm kiếm sản phẩm."],["You will help build models that recommend products to online shoppers.","Bạn sẽ tham gia xây dựng các mô hình gợi ý sản phẩm cho người mua sắm trực tuyến."]],[["Requirements: one year of experience with Python and basic knowledge of machine learning.","Yêu cầu: một năm kinh nghiệm với Python và kiến thức cơ bản về machine learning."],["Good written English is important, because our team works with offices in three countries.","Tiếng Anh viết tốt là điều quan trọng, vì nhóm chúng tôi làm việc với văn phòng ở ba quốc gia."]],[["This is a full-time position based in Da Nang.","Đây là vị trí toàn thời gian làm việc tại Đà Nẵng."],["You may work from home two days a week.","Bạn có thể làm việc tại nhà hai ngày mỗi tuần."],["We offer a yearly training budget of 1,000 dollars.","Chúng tôi hỗ trợ ngân sách đào tạo 1.000 đô la mỗi năm."]],[["To apply, send your CV and a short code sample to jobs@novaretail.dev by April 30.","Để ứng tuyển, hãy gửi CV và một đoạn code mẫu ngắn tới jobs@novaretail.dev trước ngày 30 tháng 4."],["Only selected candidates will be contacted for an interview.","Chỉ những ứng viên được chọn mới được liên hệ phỏng vấn."]]],"vocab":[{"w":"hire","f":"hiring","pos":"v/n","ipa":"/ˈhaɪər/","vi":"thuê, tuyển dụng"},{"w":"junior","f":"junior","pos":"adj/n","ipa":"/ˈdʒuːnjər/","vi":"cấp dưới; trẻ hơn"},{"w":"recommend","f":"recommend","pos":"v","ipa":"/ˌrekəˈmend/","vi":"giới thiệu, đề xuất"},{"w":"requirement","f":"requirements","pos":"n","ipa":"/rɪˈkwɑɪərmənt/","vi":"yêu cầu; điều kiện tiên quyết"},{"w":"knowledge","f":"knowledge","pos":"n","ipa":"/ˈnɑːlɪdʒ/","vi":"kiến thức, hiểu biết"},{"w":"position","f":"position","pos":"n/v","ipa":"/pəˈzɪʃən/","vi":"vị trí công việc; định vị"},{"w":"budget","f":"budget","pos":"n/v","ipa":"/ˈbʌdʒɪt/","vi":"ngân sách; lên ngân sách"},{"w":"apply","f":"apply","pos":"v","ipa":"/əˈplaɪ/","vi":"nộp đơn; áp dụng"},{"w":"sample","f":"sample","pos":"n/v","ipa":"/ˈsæmpəl/","vi":"mẫu, hàng mẫu; lấy mẫu thử"},{"w":"interview","f":"interview","pos":"n/v","ipa":"/ˈɪntərvjuː/","vi":"phuốc phỏng vấn; phỏng vấn"}],"questions":[{"q":"What will the new engineer work on?","o":["Payment systems","Models that recommend products","Mobile app design","Office IT support"],"a":1,"vi":"'help build models that recommend products to online shoppers' – mô hình gợi ý sản phẩm."},{"q":"Why is good written English important?","o":["The job is in another country","Candidates must write a test","The team works with offices in three countries","The training is in English"],"a":2,"vi":"Câu 'because our team works with offices in three countries' giải thích lý do."},{"q":"What must applicants send?","o":["A CV and a letter from a manager","A training plan","A list of three countries","A CV and a short code sample"],"a":3,"vi":"'send your CV and a short code sample'. Các phương án khác không được yêu cầu."}],"words":112},{"id":"r1-15","level":1,"type":"review","topic":"Product","title":"Review: TagFlow labeling tool","title_vi":"Đánh giá: công cụ gán nhãn TagFlow","head":[],"paras":[[["TagFlow labeling tool – 4 out of 5 stars","Công cụ gán nhãn TagFlow – 4 trên 5 sao"],["Reviewed by Minh Le, ML engineer at Brightfield AI","Người đánh giá: Minh Le, kỹ sư ML tại Brightfield AI"]],[["Our team used TagFlow for a two-week trial to label 20,000 product images.","Nhóm chúng tôi đã dùng thử TagFlow trong hai tuần để gán nhãn 20.000 ảnh sản phẩm."],["The interface is clean and easy to learn.","Giao diện gọn gàng và dễ học."],["New team members started labeling after only one hour of training.","Các thành viên mới đã bắt đầu gán nhãn chỉ sau một giờ đào tạo."]],[["The best feature is the quality check.","Tính năng tốt nhất là kiểm tra chất lượng."],["It shows when two people give the same image different labels.","Nó cho biết khi hai người gán nhãn khác nhau cho cùng một ảnh."]],[["However, the price is high for small teams.","Tuy nhiên, giá khá cao đối với các nhóm nhỏ."],["It costs 30 dollars per user each month.","Phí là 30 đô la cho mỗi người dùng mỗi tháng."],["Also, exporting large files was slow.","Ngoài ra, việc xuất các file lớn khá chậm."]],[["Overall, I would recommend it, and we plan to sign a one-year contract in June.","Nhìn chung, tôi sẽ giới thiệu công cụ này, và chúng tôi dự định ký hợp đồng một năm vào tháng 6."]]],"vocab":[{"w":"interface","f":"interface","pos":"n/v","ipa":"/ˈɪntərfeɪs/","vi":"giao diện; tương tác"},{"w":"feature","f":"feature","pos":"n/v","ipa":"/ˈfiːtʃər/","vi":"tính năng; đặc điểm"},{"w":"quality","f":"quality","pos":"n","ipa":"/ˈkwɑːləti/","vi":"chất lượng"},{"w":"contract","f":"contract","pos":"n/v","ipa":"/ˈkɑntrækt/","vi":"hợp đồng; ký kết"},{"w":"recommend","f":"recommend","pos":"v","ipa":"/ˌrekəˈmend/","vi":"giới thiệu, đề xuất"},{"w":"overall","f":"overall","pos":"adj/adv","ipa":"/ˌoʊvərˈɔːl/","vi":"tổng thể; toàn bộ"},{"w":"image","f":"image","pos":"n","ipa":"/ˈɪmɪdʒ/","vi":"hình ảnh; ảnh đĩa"},{"w":"file","f":"files","pos":"n/v","ipa":"/faɪl/","vi":"tài liệu, tệp tin; lưu trữ"},{"w":"however","f":"however","pos":"phrase","ipa":"","vi":"tuy nhiên"}],"questions":[{"q":"What does the reviewer like most about TagFlow?","o":["The quality check","The low price","The fast export","The one-hour training"],"a":0,"vi":"'The best feature is the quality check.' Giá cao và xuất file chậm là điểm trừ."},{"q":"How much does TagFlow cost?","o":["20,000 dollars a year","1 dollar per image","30 dollars per team","30 dollars per user each month"],"a":3,"vi":"'It costs 30 dollars per user each month.' Lưu ý là theo người dùng, không phải theo nhóm."},{"q":"What will the team do in June?","o":["Start a free trial","Sign a one-year contract","Label 20,000 images","Train new team members"],"a":1,"vi":"Câu cuối: 'we plan to sign a one-year contract in June'. Việc gán nhãn 20.000 ảnh đã xảy ra trong thời gian dùng thử."}],"words":105},{"id":"r1-16","level":1,"type":"email","topic":"Sales","title":"Demo for Greenline Logistics","title_vi":"Buổi demo cho Greenline Logistics","head":[["From","Tom Becker <tom.becker@quillai.co>"],["To","Anh Nguyen <anh.nguyen@quillai.co>"],["Subject","Demo next Wednesday"]],"paras":[[["Hi Anh,","Chào Anh,"]],[["Greenline Logistics wants to see a demo of our document reader next Wednesday at 2 p.m.","Greenline Logistics muốn xem demo công cụ đọc tài liệu của chúng ta vào 2 giờ chiều thứ Tư tới."],["They are comparing us with two other vendors.","Họ đang so sánh chúng ta với hai nhà cung cấp khác."],["If they choose us, the deal is worth about 80,000 dollars a year.","Nếu họ chọn chúng ta, hợp đồng trị giá khoảng 80.000 đô la mỗi năm."]],[["I will present the pricing, but I need you to show the technical part.","Tôi sẽ trình bày phần giá, nhưng tôi cần bạn trình bày phần kỹ thuật."],["Their main concern is invoices in Vietnamese and Thai.","Mối quan tâm chính của họ là hóa đơn bằng tiếng Việt và tiếng Thái."],["Could you prepare five sample invoices in each language?","Bạn có thể chuẩn bị năm hóa đơn mẫu cho mỗi ngôn ngữ được không?"]],[["Let's do a practice run on Monday at 4 p.m.","Chúng ta hãy tập dượt vào 4 giờ chiều thứ Hai nhé."],["Please send me your slides before then.","Vui lòng gửi tôi slide của bạn trước lúc đó."]],[["Best,","Thân mến,"],["Tom","Tom"]]],"vocab":[{"w":"vendor","f":"vendors","pos":"n","ipa":"/ˈvɛndər/","vi":"nhà cung cấp, người bán hàng"},{"w":"deal","f":"deal","pos":"n/v","ipa":"/dil/","vi":"thỏa thuận; giải quyết"},{"w":"concern","f":"concern","pos":"n/v","ipa":"/kənˈsɜrn/","vi":"mối bận tâm; liên quan, lo lắng"},{"w":"invoice","f":"invoices","pos":"n/v","ipa":"/ˈɪnvɔɪs/","vi":"hóa đơn; lập hóa đơn"},{"w":"technical","f":"technical","pos":"adj","ipa":"/ˈtɛknɪkəl/","vi":"thuộc kỹ thuật; chuyên môn"},{"w":"prepare","f":"prepare","pos":"v","ipa":"/prɪˈper/","vi":"chuẩn bị"},{"w":"sample","f":"sample","pos":"n/v","ipa":"/ˈsæmpəl/","vi":"mẫu, hàng mẫu; lấy mẫu thử"},{"w":"practice","f":"practice","pos":"n/v","ipa":"/ˈpræktɪs/","vi":"thực tiễn, thực hành"},{"w":"need you to","f":"need you to","pos":"phrase","ipa":"/ˈnidʒə tə/","vi":"cần bạn (làm gì)"}],"questions":[{"q":"What is Greenline Logistics doing?","o":["Hiring new engineers","Sending invoices to Thailand","Comparing three vendors","Changing its prices"],"a":2,"vi":"'They are comparing us with two other vendors' – tức là tổng cộng ba nhà cung cấp."},{"q":"What will Anh show during the demo?","o":["The technical part","The pricing","A contract","The company history"],"a":0,"vi":"Tom viết: 'I will present the pricing, but I need you to show the technical part.' Phần giá là của Tom."},{"q":"When will Tom and Anh practice the demo?","o":["Wednesday at 2 p.m.","Wednesday morning","Friday at 4 p.m.","Monday at 4 p.m."],"a":3,"vi":"'Let's do a practice run on Monday at 4 p.m.' Thứ Tư 2 giờ chiều là buổi demo thật."}],"words":93},{"id":"r1-17","level":1,"type":"chat","topic":"Service","title":"Login outage","title_vi":"Sự cố đăng nhập","head":[],"paras":[[["Ravi (14:02): Heads up. Customers cannot log in to the mobile app.","Ravi (14:02): Mọi người chú ý. Khách hàng không thể đăng nhập vào ứng dụng di động."],["Ravi (14:03): Support has received 25 tickets in the last ten minutes.","Ravi (14:03): Bộ phận hỗ trợ đã nhận 25 ticket trong mười phút vừa qua."]],[["Lan (14:05): I'm on it. It started right after the 13:45 release.","Lan (14:05): Tôi đang xử lý. Lỗi bắt đầu ngay sau bản phát hành lúc 13:45."],["Lan (14:06): I'm going to roll back to the old version first.","Lan (14:06): Tôi sẽ rollback về phiên bản cũ trước."]],[["Ravi (14:20): Logins are working again. Thanks!","Ravi (14:20): Đăng nhập đã hoạt động lại. Cảm ơn nhé!"],["Ravi (14:21): Should I tell customers?","Ravi (14:21): Tôi có nên thông báo cho khách hàng không?"]],[["Lan (14:23): Yes, please post an update on the status page.","Lan (14:23): Có, vui lòng đăng cập nhật lên trang trạng thái."],["Lan (14:24): I will find out the root cause and write up a short report by tomorrow morning.","Lan (14:24): Tôi sẽ tìm ra nguyên nhân gốc và viết một báo cáo ngắn trước sáng mai."],["Lan (14:25): We will not release again until the review is done.","Lan (14:25): Chúng ta sẽ không phát hành lại cho đến khi xem xét xong."]]],"vocab":[{"w":"customer","f":"customers","pos":"n","ipa":"/ˈkʌstəmər/","vi":"khách hàng"},{"w":"ticket","f":"tickets","pos":"n","ipa":"/ˈtɪkɪt/","vi":"vé; phiếu yêu cầu hỗ trợ"},{"w":"release","f":"release","pos":"v/n","ipa":"/rɪˈliːs/","vi":"phát hành, tung ra; sự phát hành"},{"w":"I'm on it","f":"I'm on it","pos":"phrase","ipa":"","vi":"tôi đang xử lý ngay"},{"w":"roll back","f":"roll back","pos":"phrase","ipa":"","vi":"quay về bản trước"},{"w":"version","f":"version","pos":"n","ipa":"/ˈvɜːrʒn/","vi":"phiên bản"},{"w":"status","f":"status","pos":"n","ipa":"/ˈsteɪtəs/","vi":"trạng thái, địa vị"},{"w":"find out","f":"find out","pos":"phrase","ipa":"","vi":"tìm ra, phát hiện"},{"w":"the root cause","f":"the root cause","pos":"phrase","ipa":"","vi":"nguyên nhân gốc"},{"w":"write up","f":"write up","pos":"phrase","ipa":"","vi":"viết tóm tắt, viết báo cáo"},{"w":"by tomorrow morning","f":"by tomorrow morning","pos":"phrase","ipa":"","vi":"trước sáng mai"}],"questions":[{"q":"When did the problem start?","o":["At 14:02","Right after the 13:45 release","Ten minutes before the release","Yesterday morning"],"a":1,"vi":"Lan viết: 'It started right after the 13:45 release.' 14:02 là lúc Ravi báo lỗi."},{"q":"What does Lan ask Ravi to do?","o":["Roll back the app","Write a report","Post an update on the status page","Close the 25 tickets"],"a":2,"vi":"'please post an update on the status page'. Rollback và viết báo cáo là việc của Lan."},{"q":"What will Lan do by tomorrow morning?","o":["Write a short report on the cause","Release a new version","Call 25 customers","Fix the status page"],"a":0,"vi":"'write up a short report by tomorrow morning'. Họ sẽ không phát hành lại cho tới khi xem xét xong."}],"words":112},{"id":"r1-18","level":1,"type":"notice","topic":"Data","title":"Training: model evaluation basics","title_vi":"Khóa đào tạo: cơ bản về đánh giá mô hình","head":[],"paras":[[["Training Session: Model Evaluation Basics","Buổi đào tạo: Cơ bản về đánh giá mô hình"]],[["All new data and AI engineers are invited to a training session on Thursday, May 8, from 9:30 to 11:30 a.m.","Tất cả kỹ sư dữ liệu và AI mới được mời tham gia buổi đào tạo vào thứ Năm, ngày 8 tháng 5, từ 9:30 đến 11:30 sáng."],["It will take place in Room 5B.","Buổi đào tạo sẽ diễn ra tại phòng 5B."]],[["The trainer, Dr. Hana Sato, will explain how to choose the right metrics and how to avoid common mistakes with test data.","Giảng viên, tiến sĩ Hana Sato, sẽ giải thích cách chọn đúng metric và cách tránh những lỗi thường gặp với dữ liệu test."],["There will also be a short hands-on exercise.","Buổi học cũng có một bài thực hành ngắn."]],[["Please bring your laptop with Python 3.11 installed.","Vui lòng mang theo laptop đã cài Python 3.11."],["Seats are limited to 20 people.","Số chỗ ngồi giới hạn ở 20 người."],["To register, fill in the form on the HR portal by May 2.","Để đăng ký, hãy điền vào biểu mẫu trên cổng HR trước ngày 2 tháng 5."]],[["The session will be recorded for people who cannot attend.","Buổi học sẽ được ghi hình cho những ai không thể tham dự."]]],"vocab":[{"w":"invite","f":"invited","pos":"v","ipa":"/ɪnˈvaɪt/","vi":"mời"},{"w":"trainer","f":"trainer","pos":"n","ipa":"/ˈtreɪnər/","vi":"giảng viên; huấn luyện viên"},{"w":"metric","f":"metrics","pos":"n","ipa":"/ˈmetrɪk/","vi":"số đo, hệ thống đo lường"},{"w":"avoid","f":"avoid","pos":"v","ipa":"/əˈvɔɪd/","vi":"tránh; né"},{"w":"mistake","f":"mistakes","pos":"n","ipa":"/mɪˈsteɪk/","vi":"lỗi, sai lầm"},{"w":"limit","f":"limited","pos":"n/v","ipa":"/ˈlɪmɪt/","vi":"giới hạn"},{"w":"register","f":"register","pos":"v/n","ipa":"/ˈredʒɪstər/","vi":"đăng ký; sổ sách"},{"w":"attend","f":"attend","pos":"v","ipa":"/əˈtɛnd/","vi":"tham dự, tham gia"},{"w":"record","f":"recorded","pos":"n/v","ipa":"/ˈrɛkərd/","vi":"hồ sơ, ghi chép; lưu trữ"}],"questions":[{"q":"Where will the training take place?","o":["On the HR portal","Online only","In Dr. Sato's office","In Room 5B"],"a":3,"vi":"'It will take place in Room 5B.' Cổng HR là nơi đăng ký, không phải nơi học."},{"q":"What is the deadline to register?","o":["May 8","May 2","May 11","May 20"],"a":1,"vi":"'fill in the form on the HR portal by May 2'. Ngày 8/5 là ngày đào tạo."},{"q":"What should people do if they cannot attend?","o":["Ask Dr. Sato for notes","Join the next session in June","Watch the recording","Do the exercise at home"],"a":2,"vi":"'The session will be recorded for people who cannot attend' – họ có thể xem bản ghi hình."}],"words":104},{"id":"r1-19","level":1,"type":"email","topic":"Logistics","title":"Travel and expense claims for the summit","title_vi":"Công tác và hoàn ứng chi phí cho hội nghị","head":[["From","Julia Moreno <julia.moreno@peakcloud.net>"],["To","Khanh Vo, Ben Ortiz"],["Subject","Your trip to the Singapore summit"]],"paras":[[["Hi Khanh and Ben,","Chào Khánh và Ben,"]],[["Your trip to the Data Systems Summit in Singapore is approved.","Chuyến đi tới hội nghị Data Systems Summit tại Singapore của các bạn đã được duyệt."],["I have booked your flights for June 10 and your hotel for three nights.","Tôi đã đặt vé máy bay cho ngày 10 tháng 6 và khách sạn ba đêm cho các bạn."],["The tickets are attached to this email.","Vé được đính kèm trong email này."]],[["Each of you has a daily allowance of 60 dollars for meals and local transport.","Mỗi người có phụ cấp 60 đô la mỗi ngày cho ăn uống và đi lại tại địa phương."],["Please keep all your receipts.","Vui lòng giữ lại tất cả hóa đơn."],["After the trip, submit your expense claim in the finance app within ten days.","Sau chuyến đi, hãy nộp yêu cầu hoàn ứng chi phí trên ứng dụng tài chính trong vòng mười ngày."],["Claims without receipts cannot be paid.","Các yêu cầu không có hóa đơn sẽ không được thanh toán."]],[["One more thing: please share your notes from the talks with the team at the stand-up meeting on June 16.","Thêm một việc nữa: vui lòng chia sẻ ghi chú từ các bài nói với cả nhóm trong buổi họp stand-up ngày 16 tháng 6."]],[["Have a good trip,","Chúc chuyến đi tốt đẹp,"],["Julia","Julia"]]],"vocab":[{"w":"summit","f":"summit","pos":"n","ipa":"/ˈsʌmɪt/","vi":"hội nghị thượng đỉnh"},{"w":"trip","f":"trip","pos":"n/v","ipa":"/trɪp/","vi":"chuyến đi công tác; vấp ngã"},{"w":"allowance","f":"allowance","pos":"n","ipa":"/əˈlaʊəns/","vi":"tiền phụ cấp; hạn mức"},{"w":"receipt","f":"receipts","pos":"n","ipa":"/rɪˈsit/","vi":"biên lai; hóa đơn"},{"w":"expense","f":"expense","pos":"n","ipa":"/ɪkˈspens/","vi":"chi phí"},{"w":"daily","f":"daily","pos":"adj/adv/n","ipa":"/ˈdeɪli/","vi":"hàng ngày"},{"w":"finance","f":"finance","pos":"n/v","ipa":"/ˈfaɪnæns/","vi":"tài chính; tài trợ"},{"w":"stand-up meeting","f":"stand-up meeting","pos":"phrase","ipa":"","vi":"họp nhanh hằng ngày (đứng)"},{"w":"share","f":"share","pos":"v/n","ipa":"/ʃɛr/","vi":"chia sẻ, dùng chung; cổ phần"}],"questions":[{"q":"What has Julia already done?","o":["Booked the flights and hotel","Paid the daily allowance","Registered them for the talks","Submitted their expense claims"],"a":0,"vi":"'I have booked your flights ... and your hotel for three nights.' Các việc khác là việc của Khánh và Ben hoặc không được nhắc tới."},{"q":"What is the daily allowance for?","o":["Hotel rooms","Flights","Conference tickets","Meals and local transport"],"a":3,"vi":"'a daily allowance of 60 dollars for meals and local transport'. Khách sạn và vé máy bay đã được Julia đặt riêng."},{"q":"When must they submit their expense claims?","o":["Before June 10","On June 16","Within ten days after the trip","Within three days after the trip"],"a":2,"vi":"'submit your expense claim ... within ten days' sau chuyến đi. Ngày 16/6 là buổi họp stand-up, 'three' là số đêm khách sạn."}],"words":101},{"id":"r1-20","level":1,"type":"job","topic":"Sales","title":"Sales Engineer (AI products)","title_vi":"Kỹ sư bán hàng (sản phẩm AI)","head":[],"paras":[[["Sales Engineer – Orbis Data","Kỹ sư bán hàng – Orbis Data"]],[["Orbis Data sells AI tools that help factories predict when machines will break.","Orbis Data bán các công cụ AI giúp nhà máy dự đoán khi nào máy móc sẽ hỏng."],["We are looking for a sales engineer to join our team in Ho Chi Minh City.","Chúng tôi đang tìm một kỹ sư bán hàng gia nhập đội ngũ tại TP. Hồ Chí Minh."]],[["You will give product demos, answer technical questions from customers, and help the sales team prepare proposals.","Bạn sẽ demo sản phẩm, trả lời các câu hỏi kỹ thuật của khách hàng và giúp nhóm sales chuẩn bị đề xuất."],["You will report to Peter Wong, Head of Sales.","Bạn sẽ báo cáo trực tiếp cho Peter Wong, Trưởng phòng Kinh doanh."]],[["We need someone with at least two years of experience in software or data engineering.","Chúng tôi cần người có ít nhất hai năm kinh nghiệm về kỹ thuật phần mềm hoặc dữ liệu."],["You should be comfortable speaking with clients in English.","Bạn cần tự tin khi giao tiếp với khách hàng bằng tiếng Anh."],["The job includes travel to client sites about twice a month.","Công việc bao gồm đi công tác tới địa điểm của khách hàng khoảng hai lần mỗi tháng."]],[["The salary is 1,800 to 2,500 dollars a month, plus a bonus.","Mức lương từ 1.800 đến 2.500 đô la mỗi tháng, cộng thêm thưởng."],["Please apply through our careers page before May 15.","Vui lòng ứng tuyển qua trang tuyển dụng của chúng tôi trước ngày 15 tháng 5."]]],"vocab":[{"w":"proposal","f":"proposals","pos":"n","ipa":"/prəˈpoʊzl/","vi":"đề xuất, bản đề xuất"},{"w":"technical","f":"technical","pos":"adj","ipa":"/ˈtɛknɪkəl/","vi":"thuộc kỹ thuật; chuyên môn"},{"w":"prepare","f":"prepare","pos":"v","ipa":"/prɪˈper/","vi":"chuẩn bị"},{"w":"customer","f":"customers","pos":"n","ipa":"/ˈkʌstəmər/","vi":"khách hàng"},{"w":"client","f":"client","pos":"n","ipa":"/ˈklaɪənt/","vi":"khách hàng"},{"w":"site","f":"sites","pos":"n/v","ipa":"/saɪt/","vi":"trang web, địa điểm"},{"w":"bonus","f":"bonus","pos":"n","ipa":"/ˈboʊnəs/","vi":"tiền thưởng"},{"w":"apply","f":"apply","pos":"v","ipa":"/əˈplaɪ/","vi":"nộp đơn; áp dụng"},{"w":"twice","f":"twice","pos":"adv","ipa":"/twaɪs/","vi":"hai lần"},{"w":"join","f":"join","pos":"v","ipa":"/dʒɔɪn/","vi":"tham gia; kết nối"}],"questions":[{"q":"Who will the sales engineer report to?","o":["A factory manager","Peter Wong","The data engineering team","A client in Ho Chi Minh City"],"a":1,"vi":"'You will report to Peter Wong, Head of Sales.'"},{"q":"How much experience is required?","o":["At least two years","At least one year","Five years","No experience"],"a":0,"vi":"'at least two years of experience in software or data engineering'. 'twice a month' là tần suất đi công tác, là bẫy."},{"q":"How often will the sales engineer travel?","o":["Every week","Once a year","Only when needed","About twice a month"],"a":3,"vi":"'travel to client sites about twice a month'."}],"words":117},{"id":"r2-01","level":2,"type":"email","topic":"IT","title":"Nightly pipeline failure","title_vi":"Sự cố pipeline chạy hằng đêm","head":[["From","Minh Tran <minh.tran@lumora.io>"],["To","Data Platform team"],["Subject","Tuesday's pipeline failure and next steps"]],"paras":[[["Hi all,","Chào mọi người,"]],[["As you all know, the nightly data pipeline failed on Tuesday, and the sales reports were not updated until 11 a.m. on Wednesday.","Như mọi người đã biết, pipeline dữ liệu chạy hằng đêm đã bị lỗi vào thứ Ba, và các báo cáo bán hàng không được cập nhật cho đến 11 giờ sáng thứ Tư."],["The cause of the failure was a change in the orders table that nobody had announced.","Nguyên nhân của sự cố là một thay đổi trong bảng orders mà không ai thông báo trước."],["Our job expected a column called 'region_code', but it had been renamed to 'region'.","Job của chúng ta cần một cột tên là 'region_code', nhưng cột này đã bị đổi tên thành 'region'."],["Kenji fixed the bug and ran the job again, so all data is now up to date.","Kenji đã fix bug và chạy lại job, nên hiện tại toàn bộ dữ liệu đã được cập nhật đầy đủ."]],[["To make sure this does not happen again, we will take three steps.","Để đảm bảo chuyện này không lặp lại, chúng ta sẽ thực hiện ba bước."],["First, Sara will set up an alert that notifies the on-call engineer if the job runs more than 30 minutes late.","Thứ nhất, Sara sẽ thiết lập một cảnh báo để thông báo cho kỹ sư trực nếu job chạy trễ hơn 30 phút."],["Second, any change to a table must be announced in the #data-changes channel at least two days in advance.","Thứ hai, mọi thay đổi đối với một bảng phải được thông báo trên kênh #data-changes trước ít nhất hai ngày."],["Third, Kenji will add a test that checks column names before each run.","Thứ ba, Kenji sẽ thêm một bài test kiểm tra tên các cột trước mỗi lần chạy."]],[["Sara's alert should be live by Friday, and Kenji's test is planned in the next sprint.","Cảnh báo của Sara sẽ hoạt động trước thứ Sáu, còn bài test của Kenji được lên kế hoạch trong sprint tới."],["I will write up a short report on the outage and share it with the analytics team on Thursday.","Tôi sẽ viết một báo cáo ngắn về sự cố và chia sẻ với nhóm phân tích vào thứ Năm."],["Please let me know if you have any questions.","Nếu có câu hỏi gì, mọi người cứ cho tôi biết nhé."]],[["Thanks,","Cảm ơn,"],["Minh","Minh"]]],"vocab":[{"w":"as you all know","f":"As you all know","pos":"phrase","ipa":"","vi":"như mọi người đã biết"},{"w":"pipeline","f":"pipeline","pos":"n","ipa":"/ˈpaɪplaɪn/","vi":"đường ống; quy trình xử lý"},{"w":"failure","f":"failure","pos":"n","ipa":"/ˈfeɪljər/","vi":"sự thất bại, lỗi"},{"w":"announce","f":"announced","pos":"v","ipa":"/əˈnaʊns/","vi":"thông báo, công bố"},{"w":"up to date","f":"up to date","pos":"phrase","ipa":"","vi":"cập nhật mới nhất"},{"w":"make sure","f":"make sure","pos":"phrase","ipa":"","vi":"đảm bảo"},{"w":"set up","f":"set up","pos":"phrase","ipa":"","vi":"thiết lập, sắp xếp"},{"w":"notify","f":"notifies","pos":"v","ipa":"/ˈnoʊtɪfaɪ/","vi":"thông báo, cho hay"},{"w":"in advance","f":"in advance","pos":"phrase","ipa":"","vi":"trước, sẵn"},{"w":"in the next sprint","f":"in the next sprint","pos":"phrase","ipa":"","vi":"trong sprint tới"},{"w":"write up","f":"write up","pos":"phrase","ipa":"","vi":"viết tóm tắt, viết báo cáo"},{"w":"outage","f":"outage","pos":"n","ipa":"/ˈaʊtɪdʒ/","vi":"sự gián đoạn dịch vụ, cúp điện"}],"questions":[{"q":"What caused the pipeline failure?","o":["A server ran out of memory","A column was renamed without notice","The on-call engineer missed an alert","The sales reports were deleted"],"a":1,"vi":"Câu 'Our job expected a column called region_code, but it had been renamed to region' cho thấy cột bị đổi tên mà không thông báo. Các lựa chọn về alert hay báo cáo bán hàng có nhắc đến nhưng không phải nguyên nhân."},{"q":"Who will set up the new alert?","o":["Kenji","Minh","The analytics team","Sara"],"a":3,"vi":"'Sara will set up an alert...' – Sara phụ trách cảnh báo. Kenji fix bug và viết test, Minh viết báo cáo."},{"q":"How early must table changes be announced?","o":["At least two days in advance","30 minutes before the job runs","By Friday","During the next sprint"],"a":0,"vi":"'...must be announced ... at least two days in advance.' 30 phút là ngưỡng trễ của cảnh báo, thứ Sáu là hạn của Sara – đều là bẫy."},{"q":"What will Minh do on Thursday?","o":["Add a test for column names","Run the nightly job again","Share a report on the outage with the analytics team","Rename the column back"],"a":2,"vi":"'I will write up a short report ... and share it with the analytics team on Thursday.' Việc thêm test và chạy lại job là của Kenji."}],"words":186},{"id":"r2-02","level":2,"type":"memo","topic":"HR","title":"Onboarding plan for March hires","title_vi":"Kế hoạch hội nhập cho nhân viên mới tháng Ba","head":[["From","Laura Pham, HR Manager"],["To","Engineering managers"],["Date","March 3"],["Subject","Onboarding plan for March hires"]],"paras":[[["Four new engineers will join Veltrix Labs on Monday, March 10.","Bốn kỹ sư mới sẽ gia nhập Veltrix Labs vào thứ Hai, ngày 10 tháng 3."],["Two will work on the mobile team, one on the ML platform team, and one in QA.","Hai người sẽ làm ở nhóm mobile, một người ở nhóm nền tảng ML và một người ở QA."]],[["On their first day, they will spend the morning with HR to sign their contracts and complete the security training.","Trong ngày đầu tiên, họ sẽ dành buổi sáng làm việc với HR để ký hợp đồng và hoàn thành khóa đào tạo bảo mật."],["IT will hand over laptops and access badges at 1 p.m., so please do not schedule meetings for them before 2 p.m.","IT sẽ bàn giao laptop và thẻ ra vào lúc 1 giờ chiều, vì vậy vui lòng không xếp lịch họp cho họ trước 2 giờ chiều."],["From Tuesday to Thursday, each new engineer will pair up with a mentor from their team.","Từ thứ Ba đến thứ Năm, mỗi kỹ sư mới sẽ được ghép cặp với một mentor trong nhóm của mình."],["Mentors should help them set up their development environment and walk them through the documentation.","Các mentor cần giúp họ cài đặt môi trường phát triển và hướng dẫn họ đọc tài liệu."]],[["Please note one change from last quarter.","Xin lưu ý một thay đổi so với quý trước."],["Instead of a single review after three months, managers will now hold a short check-in at the end of the first week and again after 30 days.","Thay vì chỉ đánh giá một lần sau ba tháng, giờ đây các quản lý sẽ có một buổi trao đổi ngắn vào cuối tuần đầu tiên và một lần nữa sau 30 ngày."],["Please send me the name of each mentor by Wednesday, March 5, at the latest.","Vui lòng gửi cho tôi tên của từng mentor chậm nhất là thứ Tư, ngày 5 tháng 3."]],[["If anyone on your team cannot attend the welcome lunch on Friday, let me know so I can update the reservation.","Nếu ai trong nhóm của bạn không thể tham dự bữa trưa chào mừng vào thứ Sáu, hãy cho tôi biết để tôi cập nhật lại việc đặt chỗ."]]],"vocab":[{"w":"contract","f":"contracts","pos":"n/v","ipa":"/ˈkɑntrækt/","vi":"hợp đồng; ký kết"},{"w":"security","f":"security","pos":"n","ipa":"/sɪˈkjʊrəti/","vi":"Bảo mật, an ninh"},{"w":"hand over","f":"hand over","pos":"phrase","ipa":"","vi":"bàn giao"},{"w":"access","f":"access","pos":"n/v","ipa":"/ˈæksɛs/","vi":"quyền truy cập, lối vào; tiếp cận"},{"w":"badge","f":"badges","pos":"n","ipa":"/bædʒ/","vi":"thẻ nhân viên, huy hiệu"},{"w":"schedule","f":"schedule","pos":"n/v","ipa":"/ˈskɛdʒul/","vi":"lịch trình, tiến độ; lên lịch"},{"w":"pair up with","f":"pair up with","pos":"phrase","ipa":"","vi":"làm cặp với"},{"w":"mentor","f":"mentor","pos":"n/v","ipa":"/ˈmentɔːr/","vi":"người hướng dẫn; hướng dẫn"},{"w":"environment","f":"environment","pos":"n","ipa":"/ɪnˈvaɪrənmənt/","vi":"môi trường"},{"w":"documentation","f":"documentation","pos":"n","ipa":"/ˌdɑːkjumənˈteɪʃn/","vi":"tài liệu hướng dẫn"},{"w":"instead of","f":"Instead of","pos":"phrase","ipa":"","vi":"thay vì"},{"w":"at the latest","f":"at the latest","pos":"phrase","ipa":"","vi":"muộn nhất là"}],"questions":[{"q":"When will the new engineers receive their laptops?","o":["During the morning with HR","At 2 p.m. on Monday","At 1 p.m. on Monday","On Tuesday with their mentor"],"a":2,"vi":"'IT will hand over laptops and access badges at 1 p.m.' vào ngày đầu tiên (thứ Hai). 2 giờ chiều là mốc được phép xếp họp – bẫy."},{"q":"What are mentors expected to do?","o":["Help set up the development environment","Sign the new contracts","Run the security training","Book the welcome lunch"],"a":0,"vi":"'Mentors should help them set up their development environment...' Ký hợp đồng và đào tạo bảo mật là việc với HR."},{"q":"What has changed since last quarter?","o":["New engineers now start on Mondays","Mentors are now chosen by HR","The welcome lunch moved to Friday","Managers hold check-ins after one week and after 30 days"],"a":3,"vi":"Đoạn 3: 'Instead of a single review after three months, managers will now hold a short check-in at the end of the first week and again after 30 days.'"},{"q":"What is the deadline for sending mentor names?","o":["Monday, March 10","Wednesday, March 5","Friday, March 14","30 days after the start date"],"a":1,"vi":"'...by Wednesday, March 5, at the latest.' Ngày 10/3 là ngày nhân viên mới bắt đầu làm việc."}],"words":173},{"id":"r2-03","level":2,"type":"minutes","topic":"Product","title":"Sprint 14 planning","title_vi":"Họp lên kế hoạch Sprint 14","head":[["Meeting","Sprint 14 planning"],["Date","Monday, June 2"],["Attendees","Hana (PM), Duc, Priya, Tom (QA)"],["Notes by","Priya"]],"paras":[[["1. Sprint goal: The team agreed that the goal of Sprint 14 is to release the new search filters to all users by June 13.","1. Mục tiêu sprint: Nhóm thống nhất rằng mục tiêu của Sprint 14 là phát hành bộ lọc tìm kiếm mới cho toàn bộ người dùng trước ngày 13 tháng 6."],["The filters were tested with 5% of users last sprint, and the feedback was mostly positive.","Bộ lọc đã được thử nghiệm với 5% người dùng trong sprint trước và phản hồi phần lớn là tích cực."]],[["2. Changes: The CSV export feature will move to Sprint 15 because the design is not final yet.","2. Thay đổi: Tính năng xuất CSV sẽ được chuyển sang Sprint 15 vì thiết kế vẫn chưa được chốt."],["Hana asked the team to take on an urgent bug that makes the app crash when a filter is empty.","Hana đề nghị nhóm nhận xử lý một bug khẩn cấp khiến ứng dụng bị crash khi bộ lọc để trống."],["Duc will take ownership of the fix and expects to finish it by Wednesday.","Duc sẽ chịu trách nhiệm sửa lỗi này và dự kiến hoàn thành trước thứ Tư."]],[["3. Risks: Tom pointed out that the test server is out of date, which could slow down testing.","3. Rủi ro: Tom chỉ ra rằng server test đã lỗi thời, điều này có thể làm chậm việc kiểm thử."],["Priya will upgrade it before Tuesday's stand-up meeting.","Priya sẽ nâng cấp server trước buổi họp stand-up hôm thứ Ba."],["The team also agreed to hold off on any new feature requests until the release is done.","Nhóm cũng đồng ý tạm hoãn mọi yêu cầu tính năng mới cho đến khi phát hành xong."]],[["4. Action items: Hana will send the updated plan to the sales team by Thursday.","4. Đầu việc: Hana sẽ gửi kế hoạch đã cập nhật cho nhóm sales trước thứ Năm."],["The next review is on Friday, June 13, at 3 p.m.","Buổi review tiếp theo diễn ra vào thứ Sáu, ngày 13 tháng 6, lúc 3 giờ chiều."]]],"vocab":[{"w":"release","f":"release","pos":"v/n","ipa":"/rɪˈliːs/","vi":"phát hành, tung ra; sự phát hành"},{"w":"feedback","f":"feedback","pos":"n","ipa":"/ˈfidˌbæk/","vi":"phản hồi; ý kiến đóng góp"},{"w":"feature","f":"feature","pos":"n/v","ipa":"/ˈfiːtʃər/","vi":"tính năng; đặc điểm"},{"w":"design","f":"design","pos":"v/n","ipa":"/dɪˈzaɪn/","vi":"thiết kế"},{"w":"take on","f":"take on","pos":"phrase","ipa":"","vi":"nhận thêm (việc)"},{"w":"take ownership of","f":"take ownership of","pos":"phrase","ipa":"","vi":"nhận trách nhiệm chính"},{"w":"point out","f":"pointed out","pos":"phrase","ipa":"","vi":"chỉ ra"},{"w":"out of date","f":"out of date","pos":"phrase","ipa":"","vi":"lỗi thời, cũ"},{"w":"upgrade","f":"upgrade","pos":"n/v","ipa":"/ˈʌpɡreɪd/","vi":"nâng cấp"},{"w":"stand-up meeting","f":"stand-up meeting","pos":"phrase","ipa":"","vi":"họp nhanh hằng ngày (đứng)"},{"w":"hold off on","f":"hold off on","pos":"phrase","ipa":"","vi":"tạm hoãn"},{"w":"action item","f":"Action items","pos":"phrase","ipa":"","vi":"việc cần làm (sau họp)"}],"questions":[{"q":"What is the main goal of Sprint 14?","o":["To release the search filters to all users","To finish the CSV export feature","To test the filters with 5% of users","To replace the test server"],"a":0,"vi":"'...the goal of Sprint 14 is to release the new search filters to all users by June 13.' Thử nghiệm với 5% người dùng đã làm ở sprint trước."},{"q":"Why was the CSV export moved to Sprint 15?","o":["The sales team asked for a delay","Duc is busy with a bug","Its design is not finished","The test server is broken"],"a":2,"vi":"'...will move to Sprint 15 because the design is not final yet.' Các lựa chọn khác đều có trong bài nhưng không phải lý do."},{"q":"Who is responsible for fixing the crash bug?","o":["Hana","Duc","Priya","Tom"],"a":1,"vi":"'Duc will take ownership of the fix...' Hana chỉ đề nghị nhóm nhận bug, Priya lo server, Tom nêu rủi ro."},{"q":"What will Hana do by Thursday?","o":["Upgrade the test server","Lead the stand-up meeting","Review new feature requests","Send the updated plan to the sales team"],"a":3,"vi":"Mục 4: 'Hana will send the updated plan to the sales team by Thursday.' Nâng cấp server là việc của Priya."}],"words":163},{"id":"r2-04","level":2,"type":"email","topic":"Finance","title":"Conference travel expenses","title_vi":"Chi phí công tác dự hội nghị","head":[["From","Grace Nguyen <grace.nguyen@corvanta.com>"],["To","AI Summit attendees"],["Subject","Reimbursement for your Singapore trip"]],"paras":[[["Hello everyone,","Chào mọi người,"]],[["Thank you for representing Corvanta at the AI Summit in Singapore last week.","Cảm ơn mọi người đã đại diện Corvanta tham dự AI Summit tại Singapore tuần trước."],["Please send your expense reports through the finance portal by Friday, October 24.","Vui lòng gửi báo cáo chi phí qua cổng tài chính trước thứ Sáu, ngày 24 tháng 10."],["Reports received after this deadline will be paid in the November payroll instead of October.","Các báo cáo nhận được sau hạn này sẽ được thanh toán vào kỳ lương tháng 11 thay vì tháng 10."]],[["Here are a few reminders about our travel policy.","Dưới đây là một vài lưu ý về chính sách công tác của chúng ta."],["Hotels are covered up to 180 US dollars per night, and the meal allowance is 50 dollars per day.","Tiền khách sạn được chi trả tối đa 180 đô la Mỹ mỗi đêm, và phụ cấp ăn uống là 50 đô la mỗi ngày."],["Taxis to and from the airport are covered, but you must keep a receipt for every item over 10 dollars.","Chi phí taxi đến và đi từ sân bay được chi trả, nhưng bạn phải giữ hóa đơn cho mọi khoản trên 10 đô la."],["Flights were arranged by our travel agent, so you do not need to include them.","Vé máy bay đã được đại lý du lịch của công ty sắp xếp, nên bạn không cần đưa vào báo cáo."]],[["There is one change this year.","Năm nay có một thay đổi."],["Conference fees paid with a personal card must now be signed off by your manager before you send the report.","Phí hội nghị thanh toán bằng thẻ cá nhân giờ đây phải được quản lý của bạn duyệt trước khi bạn gửi báo cáo."],["Without this, we cannot reimburse the fee.","Nếu không có bước này, chúng tôi không thể hoàn trả khoản phí đó."]],[["If you have lost a receipt, please complete the missing receipt form and send it to me directly.","Nếu bạn bị mất hóa đơn, vui lòng điền mẫu báo mất hóa đơn và gửi trực tiếp cho tôi."]],[["Best regards,","Trân trọng,"],["Grace","Grace"]]],"vocab":[{"w":"expense","f":"expense","pos":"n","ipa":"/ɪkˈspens/","vi":"chi phí"},{"w":"deadline","f":"deadline","pos":"n","ipa":"/ˈdɛˌdlaɪn/","vi":"hạn chót"},{"w":"instead of","f":"instead of","pos":"phrase","ipa":"","vi":"thay vì"},{"w":"reminder","f":"reminders","pos":"n","ipa":"/rɪˈmaɪndər/","vi":"lời nhắc; giấy nhắc"},{"w":"policy","f":"policy","pos":"n","ipa":"/ˈpɑːləsi/","vi":"chính sách"},{"w":"allowance","f":"allowance","pos":"n","ipa":"/əˈlaʊəns/","vi":"tiền phụ cấp; hạn mức"},{"w":"airport","f":"airport","pos":"n","ipa":"/ˈɛrpɔrt/","vi":"sân bay"},{"w":"receipt","f":"receipt","pos":"n","ipa":"/rɪˈsit/","vi":"biên lai; hóa đơn"},{"w":"arrange","f":"arranged","pos":"v","ipa":"/əˈreɪndʒ/","vi":"sắp xếp, bố trí"},{"w":"reimburse","f":"reimburse","pos":"v","ipa":"/ˌriɪmˈbɜrs/","vi":"hoàn trả chi phí"},{"w":"manager","f":"manager","pos":"n","ipa":"/ˈmænɪdʒər/","vi":"quản lý"}],"questions":[{"q":"What happens if an expense report arrives after October 24?","o":["It will be rejected","It must be signed off by Grace","It will be sent to the travel agent","It will be paid in November"],"a":3,"vi":"'Reports received after this deadline will be paid in the November payroll instead of October.' Báo cáo không bị từ chối, chỉ thanh toán muộn hơn."},{"q":"What is the maximum amount covered for a hotel?","o":["50 dollars per day","180 dollars per night","10 dollars per item","There is no limit"],"a":1,"vi":"'Hotels are covered up to 180 US dollars per night.' 50 đô là phụ cấp ăn, 10 đô là mức cần giữ hóa đơn."},{"q":"What is new this year?","o":["Flights are arranged by a travel agent","Airport taxis are covered","Conference fees on personal cards need manager approval first","Receipts are required for all items"],"a":2,"vi":"'There is one change this year. Conference fees paid with a personal card must now be signed off by your manager...' Các ý khác là quy định có sẵn."},{"q":"What should someone who lost a receipt do?","o":["Complete a form and send it to Grace","Ask the hotel for a new copy","Wait until the November payroll","Ask the travel agent for help"],"a":0,"vi":"Đoạn cuối: '...complete the missing receipt form and send it to me directly' – 'me' là Grace."}],"words":160},{"id":"r2-05","level":2,"type":"report","topic":"IT","title":"Support chatbot v2 evaluation","title_vi":"Đánh giá chatbot hỗ trợ phiên bản 2","head":[["Prepared by","ML Applications team"],["Date","May 20"]],"paras":[[["This report sums up the test results for version 2 of our customer support chatbot, which ran from May 5 to May 16.","Báo cáo này tóm tắt kết quả thử nghiệm phiên bản 2 của chatbot hỗ trợ khách hàng, diễn ra từ ngày 5 đến ngày 16 tháng 5."],["We tested it against the current version using 1,200 real customer questions from last quarter.","Chúng tôi so sánh nó với phiên bản hiện tại bằng 1.200 câu hỏi thật của khách hàng từ quý trước."]],[["Overall, version 2 answered 84% of questions correctly, up from 71% for version 1.","Nhìn chung, phiên bản 2 trả lời đúng 84% câu hỏi, tăng so với 71% của phiên bản 1."],["It did especially well on billing questions, where accuracy rose to 90%.","Nó làm đặc biệt tốt với các câu hỏi về thanh toán, nơi độ chính xác tăng lên 90%."],["However, its average response time went up from 1.2 to 2.1 seconds, mainly because it uses a larger model.","Tuy nhiên, thời gian phản hồi trung bình tăng từ 1,2 lên 2,1 giây, chủ yếu do nó dùng một model lớn hơn."],["Made-up answers also fell by about half, but the model still gave the wrong refund amount in 15 cases.","Số câu trả lời bịa đặt cũng giảm khoảng một nửa, nhưng model vẫn đưa ra sai số tiền hoàn trả trong 15 trường hợp."]],[["Based on these results, we recommend that we roll out version 2 to 20% of users on June 2.","Dựa trên các kết quả này, chúng tôi đề xuất triển khai phiên bản 2 cho 20% người dùng vào ngày 2 tháng 6."],["Before that, the team will add a rule that sends all refund questions to a human agent.","Trước đó, nhóm sẽ thêm một quy tắc chuyển tất cả câu hỏi về hoàn tiền cho nhân viên hỗ trợ."],["Linh will be in charge of the launch, and Omar will look into ways to speed up responses, such as caching common answers.","Linh sẽ phụ trách việc ra mắt, còn Omar sẽ tìm hiểu các cách tăng tốc phản hồi, chẳng hạn như cache những câu trả lời phổ biến."]],[["We will review user ratings two weeks after launch and then decide whether to extend it to all users.","Chúng tôi sẽ xem xét đánh giá của người dùng hai tuần sau khi ra mắt rồi quyết định có mở rộng cho toàn bộ người dùng hay không."]]],"vocab":[{"w":"version","f":"version","pos":"n","ipa":"/ˈvɜːrʒn/","vi":"phiên bản"},{"w":"customer","f":"customer","pos":"n","ipa":"/ˈkʌstəmər/","vi":"khách hàng"},{"w":"accuracy","f":"accuracy","pos":"n","ipa":"/ˈækjərəsi/","vi":"độ chính xác"},{"w":"response","f":"response","pos":"n","ipa":"/rɪˈspɑːns/","vi":"phản hồi, câu trả lời"},{"w":"refund","f":"refund","pos":"n/v","ipa":"/ˈriˌfʌnd/","vi":"hoàn tiền; sự hoàn tiền"},{"w":"recommend","f":"recommend","pos":"v","ipa":"/ˌrekəˈmend/","vi":"giới thiệu, đề xuất"},{"w":"roll out","f":"roll out","pos":"phrase","ipa":"","vi":"triển khai dần"},{"w":"be in charge of","f":"be in charge of","pos":"phrase","ipa":"","vi":"phụ trách"},{"w":"launch","f":"launch","pos":"v/n","ipa":"/lɔːntʃ/","vi":"ra mắt, khởi động; sự ra mắt"},{"w":"look into","f":"look into","pos":"phrase","ipa":"","vi":"tìm hiểu, xem xét"},{"w":"speed up","f":"speed up","pos":"phrase","ipa":"","vi":"tăng tốc"},{"w":"extend","f":"extend","pos":"v","ipa":"/ɪkˈstɛnd/","vi":"kéo dài, mở rộng"}],"questions":[{"q":"What percentage of questions did version 2 answer correctly overall?","o":["71%","84%","90%","20%"],"a":1,"vi":"'Overall, version 2 answered 84% of questions correctly.' 71% là phiên bản 1, 90% chỉ là câu hỏi thanh toán, 20% là tỷ lệ người dùng triển khai."},{"q":"What got worse in version 2?","o":["Response time","Billing accuracy","The number of made-up answers","User ratings"],"a":0,"vi":"'...its average response time went up from 1.2 to 2.1 seconds.' Độ chính xác tăng, câu trả lời bịa giảm, đánh giá người dùng chưa có."},{"q":"What will happen before the rollout on June 2?","o":["The model will be made larger","All users will get version 2","User ratings will be reviewed","Refund questions will be sent to human agents"],"a":3,"vi":"'Before that, the team will add a rule that sends all refund questions to a human agent.' Xem đánh giá người dùng là việc làm sau khi ra mắt hai tuần."},{"q":"What is Omar's task?","o":["Lead the launch","Collect 1,200 customer questions","Find ways to make responses faster","Fix the refund amounts"],"a":2,"vi":"'Omar will look into ways to speed up responses...' Linh mới là người phụ trách ra mắt."}],"words":183},{"id":"r2-06","level":2,"type":"memo","topic":"Events","title":"Autumn Hack Days","title_vi":"Hack Days mùa thu","head":[["From","Events Committee, Norbrook Systems"],["To","All engineering and product staff"],["Date","August 18"],["Subject","Autumn Hack Days"]],"paras":[[["We are happy to announce that our first internal hackathon, Hack Days, will be held on September 25 and 26 at the Riverside office.","Chúng tôi vui mừng thông báo hackathon nội bộ đầu tiên của công ty, Hack Days, sẽ được tổ chức vào ngày 25 và 26 tháng 9 tại văn phòng Riverside."],["This year's theme is 'AI tools that save us time at work'.","Chủ đề năm nay là 'Công cụ AI giúp chúng ta tiết kiệm thời gian trong công việc'."]],[["Teams can have two to five members, and people from different departments are welcome to work together.","Mỗi đội có từ hai đến năm thành viên, và khuyến khích mọi người từ các phòng ban khác nhau cùng làm việc với nhau."],["To register, the team leader should complete the online form by September 12.","Để đăng ký, trưởng nhóm cần điền mẫu đơn trực tuyến trước ngày 12 tháng 9."],["Each team will have three minutes to show its project on the afternoon of the second day.","Mỗi đội sẽ có ba phút để trình bày dự án vào buổi chiều ngày thứ hai."]],[["Please note that the event was first planned for early September, but we had to postpone it because of the quarterly release.","Xin lưu ý rằng sự kiện ban đầu được lên kế hoạch vào đầu tháng 9, nhưng chúng tôi đã phải lùi lại vì đợt phát hành hằng quý."],["Managers have agreed that attendees do not need to join their usual stand-ups during the two days.","Các quản lý đã đồng ý rằng người tham gia không cần dự các buổi stand-up thường lệ trong hai ngày này."]],[["A panel of three judges, including our CTO, will choose the winners.","Một hội đồng gồm ba giám khảo, trong đó có CTO, sẽ chọn ra đội chiến thắng."],["The top team will receive a budget of 5,000 dollars to turn its idea into a real internal tool.","Đội đứng đầu sẽ nhận được ngân sách 5.000 đô la để biến ý tưởng thành một công cụ nội bộ thực sự."],["Food and drinks will be served, and a small number of meeting rooms can be reserved in advance.","Đồ ăn và thức uống sẽ được phục vụ, và có thể đặt trước một số ít phòng họp."],["For questions, please reach out to Mai Hoang in the events team.","Nếu có thắc mắc, vui lòng liên hệ Mai Hoang ở nhóm sự kiện."]]],"vocab":[{"w":"announce","f":"announce","pos":"v","ipa":"/əˈnaʊns/","vi":"thông báo, công bố"},{"w":"department","f":"departments","pos":"n","ipa":"/dɪˈpɑrtmənt/","vi":"phòng ban"},{"w":"register","f":"register","pos":"v/n","ipa":"/ˈredʒɪstər/","vi":"đăng ký; sổ sách"},{"w":"postpone","f":"postpone","pos":"v","ipa":"/poʊˈspoʊn/","vi":"hoãn lại"},{"w":"because of","f":"because of","pos":"phrase","ipa":"","vi":"vì, do"},{"w":"release","f":"release","pos":"v/n","ipa":"/rɪˈliːs/","vi":"phát hành, tung ra; sự phát hành"},{"w":"attendee","f":"attendees","pos":"n","ipa":"/əˌtɛnˈdi/","vi":"người tham dự"},{"w":"budget","f":"budget","pos":"n/v","ipa":"/ˈbʌdʒɪt/","vi":"ngân sách; lên ngân sách"},{"w":"in advance","f":"in advance","pos":"phrase","ipa":"","vi":"trước, sẵn"},{"w":"reach out to","f":"reach out to","pos":"phrase","ipa":"","vi":"liên hệ với"}],"questions":[{"q":"What is the deadline for registering a team?","o":["August 18","September 25","September 12","September 26"],"a":2,"vi":"'...complete the online form by September 12.' 18/8 là ngày gửi memo, 25-26/9 là ngày diễn ra sự kiện."},{"q":"Why was the event postponed?","o":["The office was not available","The CTO was traveling","Not enough teams registered","Because of the quarterly release"],"a":3,"vi":"'...we had to postpone it because of the quarterly release.'"},{"q":"What will the winning team receive?","o":["A budget to build its idea","A trip to the Riverside office","Three extra days off","A meeting with the CTO"],"a":0,"vi":"'The top team will receive a budget of 5,000 dollars to turn its idea into a real internal tool.' CTO chỉ là giám khảo."},{"q":"What have managers agreed to?","o":["Join the panel of judges","Excuse attendees from their usual stand-ups","Pay for food and drinks","Reserve meeting rooms for all teams"],"a":1,"vi":"'Managers have agreed that attendees do not need to join their usual stand-ups during the two days.'"}],"words":184},{"id":"r2-07","level":2,"type":"email","topic":"Product","title":"Client request for PDF export","title_vi":"Yêu cầu xuất PDF từ khách hàng","head":[["From","Daniel Kim <daniel.kim@quillset.com>"],["To","Ngoc Anh Vu"],["Cc","Rachel Ford"],["Subject","Request from Pinewell Logistics"]],"paras":[[["Hi Ngoc Anh,","Chào Ngọc Anh,"]],[["I had a call with Pinewell Logistics this morning, and they asked if we could add a PDF export to the monthly delivery report.","Sáng nay tôi có cuộc gọi với Pinewell Logistics, và họ hỏi liệu chúng ta có thể thêm tính năng xuất PDF cho báo cáo giao hàng hằng tháng không."],["At the moment, users can only download the report as a CSV file, and their managers find it hard to read.","Hiện tại, người dùng chỉ có thể tải báo cáo dưới dạng file CSV, và các quản lý bên họ thấy khó đọc."],["They would like the PDF to show their company logo and a chart on the first page.","Họ muốn file PDF hiển thị logo công ty và một biểu đồ ở trang đầu."]],[["Pinewell is our second-largest client, and their agreement is up for renewal on November 30.","Pinewell là khách hàng lớn thứ hai của chúng ta, và hợp đồng của họ sẽ đến hạn gia hạn vào ngày 30 tháng 11."],["They are hoping to see the feature before then, ideally by mid-November.","Họ mong được thấy tính năng này trước thời điểm đó, tốt nhất là vào giữa tháng 11."],["I know your team is busy with the billing release, so I wanted to check with you before promising anything.","Tôi biết nhóm của bạn đang bận với đợt phát hành tính năng thanh toán, nên tôi muốn hỏi ý bạn trước khi hứa hẹn điều gì."]],[["Could you estimate how long this would take and let me know by Wednesday?","Bạn có thể ước tính việc này mất bao lâu và báo cho tôi trước thứ Tư được không?"],["If it is too much for this quarter, a simpler version without the chart might be enough for now.","Nếu khối lượng quá lớn cho quý này, thì trước mắt một phiên bản đơn giản hơn không có biểu đồ có thể là đủ."],["Rachel has agreed to review the request and decide when it fits into the plan once we have your estimate.","Rachel đã đồng ý xem xét yêu cầu và quyết định thời điểm đưa nó vào kế hoạch khi có ước tính của bạn."]],[["Thanks,","Cảm ơn,"],["Daniel","Daniel"]]],"vocab":[{"w":"client","f":"client","pos":"n","ipa":"/ˈklaɪənt/","vi":"khách hàng"},{"w":"at the moment","f":"At the moment","pos":"phrase","ipa":"","vi":"hiện tại, lúc này"},{"w":"agreement","f":"agreement","pos":"n","ipa":"/əˈɡriːmənt/","vi":"hợp đồng, thỏa thuận"},{"w":"feature","f":"feature","pos":"n/v","ipa":"/ˈfiːtʃər/","vi":"tính năng; đặc điểm"},{"w":"release","f":"release","pos":"v/n","ipa":"/rɪˈliːs/","vi":"phát hành, tung ra; sự phát hành"},{"w":"estimate","f":"estimate","pos":"v/n","ipa":"/ˈestɪmeɪt/","vi":"ước tính; bản dự toán"},{"w":"let me know","f":"let me know","pos":"phrase","ipa":"/ˌlɛmi ˈnoʊ/","vi":"cho tôi biết nhé"},{"w":"version","f":"version","pos":"n","ipa":"/ˈvɜːrʒn/","vi":"phiên bản"},{"w":"for now","f":"for now","pos":"phrase","ipa":"","vi":"tạm thời, bây giờ"}],"questions":[{"q":"What does Pinewell Logistics want?","o":["A PDF version of the monthly report","A faster CSV download","A new billing system","A lower price at renewal"],"a":0,"vi":"'...they asked if we could add a PDF export to the monthly delivery report.' CSV là định dạng hiện có, billing là việc nhóm đang làm."},{"q":"When is the client's agreement up for renewal?","o":["Mid-November","November 30","Wednesday","The end of the quarter"],"a":1,"vi":"'...their agreement is up for renewal on November 30.' Giữa tháng 11 là thời điểm khách mong có tính năng – bẫy."},{"q":"What does Daniel ask Ngoc Anh to do?","o":["Start building the feature right away","Call the client directly","Estimate the work and reply by Wednesday","Delay the billing release"],"a":2,"vi":"'Could you estimate how long this would take and let me know by Wednesday?'"},{"q":"What does Daniel suggest if there is not enough time?","o":["Asking another team for help","Moving the renewal date","Offering the client a discount","Delivering a version without the chart"],"a":3,"vi":"'...a simpler version without the chart might be enough for now.'"}],"words":167},{"id":"r2-08","level":2,"type":"minutes","topic":"HR","title":"Hiring committee: ML engineers","title_vi":"Hội đồng tuyển dụng: kỹ sư ML","head":[["Meeting","Hiring committee"],["Date","Thursday, July 10"],["Attendees","Quang Le (Engineering Director), Julia Brandt (HR), Ravi Menon, An Do"]],"paras":[[["1. Status: HR has received 64 applications for the two ML engineer positions.","1. Tình hình: HR đã nhận được 64 hồ sơ ứng tuyển cho hai vị trí kỹ sư ML."],["Twelve applicants passed the online coding test, and eight have been invited to technical interviews.","Mười hai ứng viên đã vượt qua bài test lập trình trực tuyến, và tám người đã được mời phỏng vấn kỹ thuật."]],[["2. Process: Quang proposed replacing the home assignment with a 60-minute live system design interview.","2. Quy trình: Quang đề xuất thay bài tập làm ở nhà bằng một buổi phỏng vấn thiết kế hệ thống trực tiếp kéo dài 60 phút."],["Several strong applicants dropped out due to the time the assignment required.","Một số ứng viên giỏi đã bỏ ngang do bài tập đòi hỏi quá nhiều thời gian."],["The committee agreed, and the change will apply from next week.","Hội đồng đã đồng ý, và thay đổi này sẽ áp dụng từ tuần sau."],["Julia will update the job post and inform applicants who are already in the process.","Julia sẽ cập nhật tin tuyển dụng và thông báo cho những ứng viên đang trong quy trình."]],[["3. Interviewers: Ravi and An will conduct the technical interviews.","3. Người phỏng vấn: Ravi và An sẽ thực hiện các buổi phỏng vấn kỹ thuật."],["Each interviewer must send written feedback within 24 hours so that decisions are not delayed.","Mỗi người phỏng vấn phải gửi nhận xét bằng văn bản trong vòng 24 giờ để các quyết định không bị chậm trễ."]],[["4. Timeline: The goal is to make offers by August 8 so that new engineers can start in September.","4. Tiến độ: Mục tiêu là gửi thư mời làm việc trước ngày 8 tháng 8 để kỹ sư mới có thể bắt đầu vào tháng 9."],["Finance has agreed to a pay range of 45 to 60 million VND per month for these roles.","Bộ phận tài chính đã đồng ý mức lương từ 45 đến 60 triệu đồng mỗi tháng cho các vị trí này."],["The committee will meet again on July 24 to discuss the final applicants.","Hội đồng sẽ họp lại vào ngày 24 tháng 7 để thảo luận về các ứng viên cuối cùng."]]],"vocab":[{"w":"application","f":"applications","pos":"n","ipa":"/ˌæplɪˈkeɪʃn/","vi":"ứng dụng; đơn xin"},{"w":"position","f":"positions","pos":"n/v","ipa":"/pəˈzɪʃən/","vi":"vị trí công việc; định vị"},{"w":"applicant","f":"applicants","pos":"n","ipa":"/ˈæplɪkənt/","vi":"ứng viên"},{"w":"propose","f":"proposed","pos":"v","ipa":"/prəˈpoʊz/","vi":"đề xuất, đề nghị"},{"w":"due to","f":"due to","pos":"phrase","ipa":"","vi":"do, bởi vì"},{"w":"inform","f":"inform","pos":"v","ipa":"/ɪnˈfɔrm/","vi":"thông báo"},{"w":"conduct","f":"conduct","pos":"v/n","ipa":"/kənˈdʌkt/","vi":"tiến hành; hạnh kiểm"},{"w":"feedback","f":"feedback","pos":"n","ipa":"/ˈfidˌbæk/","vi":"phản hồi; ý kiến đóng góp"},{"w":"so that","f":"so that","pos":"phrase","ipa":"","vi":"để mà"},{"w":"decision","f":"decisions","pos":"n","ipa":"/dɪˈsɪʒən/","vi":"sự quyết định; quyết định"},{"w":"delay","f":"delayed","pos":"n/v","ipa":"/dɪˈleɪ/","vi":"sự chậm trễ; trì hoãn"}],"questions":[{"q":"How many applicants have been invited to technical interviews?","o":["64","Twelve","Two","Eight"],"a":3,"vi":"'...eight have been invited to technical interviews.' 64 là số hồ sơ, 12 là số người qua bài test, 2 là số vị trí."},{"q":"Why will the home assignment be replaced?","o":["It was too easy","Interviewers had no time to grade it","Strong applicants dropped out because it took too long","Finance did not agree to it"],"a":2,"vi":"'Several strong applicants dropped out due to the time the assignment required.'"},{"q":"What must interviewers do within 24 hours?","o":["Make offers","Send written feedback","Update the job post","Contact Finance"],"a":1,"vi":"'Each interviewer must send written feedback within 24 hours...' Cập nhật tin tuyển dụng là việc của Julia."},{"q":"By when does the company hope to make offers?","o":["August 8","July 24","Next week","September"],"a":0,"vi":"'The goal is to make offers by August 8...' 24/7 là buổi họp tiếp theo, tháng 9 là lúc kỹ sư mới bắt đầu làm."}],"words":156},{"id":"r2-09","level":2,"type":"report","topic":"Finance","title":"GPU cloud contract review","title_vi":"Rà soát hợp đồng cloud GPU","head":[["Prepared by","Hoa Bui, Finance"],["Date","April 7"]],"paras":[[["Our agreement with our current GPU cloud vendor, Stratacloud, ends on June 30, and the infrastructure team has asked Finance to review two other options.","Hợp đồng với nhà cung cấp cloud GPU hiện tại, Stratacloud, sẽ kết thúc vào ngày 30 tháng 6, và nhóm hạ tầng đã đề nghị bộ phận Tài chính xem xét hai phương án khác."],["Last year we spent about 420,000 dollars on GPU time, mostly for model training.","Năm ngoái chúng ta đã chi khoảng 420.000 đô la cho thời gian sử dụng GPU, chủ yếu để huấn luyện model."]],[["Stratacloud is willing to renew for two years at the same hourly price, with a 5% reduction if we agree to a minimum spend.","Stratacloud sẵn sàng gia hạn hai năm với cùng mức giá theo giờ, kèm mức giảm 5% nếu chúng ta cam kết chi tiêu tối thiểu."],["Arkwell Compute is 18% cheaper, but its nearest data center is in another region, which would slow down responses for our users in Asia.","Arkwell Compute rẻ hơn 18%, nhưng trung tâm dữ liệu gần nhất của họ nằm ở khu vực khác, điều này sẽ làm chậm phản hồi cho người dùng của chúng ta ở châu Á."],["Bluefen is about 10% cheaper and offers monthly billing, but it needs a one-month setup and a data migration.","Bluefen rẻ hơn khoảng 10% và cho phép thanh toán theo tháng, nhưng cần một tháng để thiết lập và chuyển dữ liệu."]],[["Finance recommends a one-year contract with Bluefen for training only, while keeping live services on Stratacloud.","Bộ phận Tài chính đề xuất ký hợp đồng một năm với Bluefen chỉ cho việc huấn luyện, trong khi vẫn giữ các dịch vụ đang chạy thật trên Stratacloud."],["This option would save about 35,000 dollars in the first year.","Phương án này sẽ tiết kiệm khoảng 35.000 đô la trong năm đầu tiên."],["The legal team must review Bluefen's terms by May 15 so that the migration can start in June.","Nhóm pháp lý phải xem xét các điều khoản của Bluefen trước ngày 15 tháng 5 để việc chuyển đổi có thể bắt đầu vào tháng 6."]],[["A final decision is expected at the leadership meeting on April 21.","Quyết định cuối cùng dự kiến sẽ được đưa ra tại cuộc họp ban lãnh đạo vào ngày 21 tháng 4."]]],"vocab":[{"w":"agreement","f":"agreement","pos":"n","ipa":"/əˈɡriːmənt/","vi":"hợp đồng, thỏa thuận"},{"w":"vendor","f":"vendor","pos":"n","ipa":"/ˈvɛndər/","vi":"nhà cung cấp, người bán hàng"},{"w":"infrastructure","f":"infrastructure","pos":"n","ipa":"/ˈɪnfrəstrʌktʃər/","vi":"cơ sở hạ tầng"},{"w":"option","f":"options","pos":"n","ipa":"/ˈɑːp.ʃən/","vi":"tùy chọn; sự lựa chọn"},{"w":"renew","f":"renew","pos":"v","ipa":"/rɪˈnu/","vi":"gia hạn, làm mới"},{"w":"migration","f":"migration","pos":"n","ipa":"/maɪˈɡreɪ.ʃən/","vi":"sự di cư; quá trình chuyển đổi dữ liệu"},{"w":"recommend","f":"recommends","pos":"v","ipa":"/ˌrekəˈmend/","vi":"giới thiệu, đề xuất"},{"w":"save","f":"save","pos":"v","ipa":"/seɪv/","vi":"lưu, tiết kiệm"},{"w":"so that","f":"so that","pos":"phrase","ipa":"","vi":"để mà"},{"w":"decision","f":"decision","pos":"n","ipa":"/dɪˈsɪʒən/","vi":"sự quyết định; quyết định"}],"questions":[{"q":"When does the current agreement with Stratacloud end?","o":["April 21","June 30","May 15","In two years"],"a":1,"vi":"'...Stratacloud, ends on June 30.' 21/4 là ngày ra quyết định, 15/5 là hạn rà soát pháp lý."},{"q":"What is a disadvantage of Arkwell Compute?","o":["Its prices are higher","It requires a minimum spend","It needs a one-month setup","It would be slower for users in Asia"],"a":3,"vi":"'...its nearest data center is in another region, which would slow down responses for our users in Asia.' Mức chi tối thiểu là của Stratacloud, một tháng thiết lập là của Bluefen."},{"q":"What does Finance recommend?","o":["Renewing with Stratacloud for two years","Moving everything to Arkwell Compute","Using Bluefen for training and Stratacloud for live services","Delaying the decision until June"],"a":2,"vi":"'Finance recommends a one-year contract with Bluefen for training only, while keeping live services on Stratacloud.'"},{"q":"What must happen by May 15?","o":["The legal team must review Bluefen's terms","The migration must be finished","Leadership must make a decision","Stratacloud must send a new price"],"a":0,"vi":"'The legal team must review Bluefen's terms by May 15...' Việc chuyển đổi chỉ bắt đầu vào tháng 6."}],"words":165},{"id":"r2-10","level":2,"type":"email","topic":"Events","title":"Cloud security workshop trip","title_vi":"Chuyến đi dự workshop bảo mật cloud","head":[["From","Tuan Ly <tuan.ly@orbiq.vn>"],["To","Backend team"],["Subject","Cloud security workshop: travel details"]],"paras":[[["Hi team,","Chào cả nhóm,"]],[["As discussed last month, the two-day cloud security workshop will take place at our Da Nang office on November 13 and 14.","Như đã bàn tháng trước, workshop hai ngày về bảo mật cloud sẽ diễn ra tại văn phòng Đà Nẵng vào ngày 13 và 14 tháng 11."],["The trainer is an outside expert, and the sessions will run from 9 a.m. to 5 p.m. on both days.","Người đào tạo là một chuyên gia bên ngoài, và các buổi học sẽ kéo dài từ 9 giờ sáng đến 5 giờ chiều cả hai ngày."],["All backend engineers are required to attend, as the training is part of our new security policy.","Tất cả kỹ sư backend bắt buộc phải tham dự, vì khóa đào tạo này là một phần của chính sách bảo mật mới."]],[["We have booked flights from Hanoi on the morning of November 12 and rooms at the Seaview Hotel for two nights.","Chúng tôi đã đặt vé máy bay từ Hà Nội vào sáng ngày 12 tháng 11 và phòng tại khách sạn Seaview trong hai đêm."],["Your tickets and itinerary will be sent by email early next week.","Vé và lịch trình của bạn sẽ được gửi qua email vào đầu tuần sau."],["If you would rather travel on your own, please tell me by Friday so that I can release your ticket.","Nếu bạn muốn tự đi, vui lòng báo cho tôi trước thứ Sáu để tôi hủy vé của bạn."]],[["Please bring your laptop with admin access, because you will need to set up some tools before the first session.","Vui lòng mang theo laptop có quyền admin, vì bạn sẽ cần cài đặt một số công cụ trước buổi học đầu tiên."],["Instructions will be shared in the #sec-training channel on November 10.","Hướng dẫn sẽ được chia sẻ trên kênh #sec-training vào ngày 10 tháng 11."],["There is one change from the original plan: the team dinner has moved from the second evening to the first evening.","Có một thay đổi so với kế hoạch ban đầu: bữa tối của nhóm đã chuyển từ tối ngày thứ hai sang tối ngày đầu tiên."],["Let me know if you have any food requirements.","Hãy cho tôi biết nếu bạn có yêu cầu gì về đồ ăn."]],[["Best,","Thân,"],["Tuan","Tuấn"]]],"vocab":[{"w":"trainer","f":"trainer","pos":"n","ipa":"/ˈtreɪnər/","vi":"giảng viên; huấn luyện viên"},{"w":"security","f":"security","pos":"n","ipa":"/sɪˈkjʊrəti/","vi":"Bảo mật, an ninh"},{"w":"policy","f":"policy","pos":"n","ipa":"/ˈpɑːləsi/","vi":"chính sách"},{"w":"ticket","f":"tickets","pos":"n","ipa":"/ˈtɪkɪt/","vi":"vé; phiếu yêu cầu hỗ trợ"},{"w":"itinerary","f":"itinerary","pos":"n","ipa":"/aɪˈtɪnəˌrɛri/","vi":"lịch trình"},{"w":"early next week","f":"early next week","pos":"phrase","ipa":"","vi":"đầu tuần sau"},{"w":"so that","f":"so that","pos":"phrase","ipa":"","vi":"để mà"},{"w":"laptop","f":"laptop","pos":"n","ipa":"/ˈlæpˌtɑp/","vi":"máy tính xách tay"},{"w":"access","f":"access","pos":"n/v","ipa":"/ˈæksɛs/","vi":"quyền truy cập, lối vào; tiếp cận"},{"w":"requirement","f":"requirements","pos":"n","ipa":"/rɪˈkwɑɪərmənt/","vi":"yêu cầu; điều kiện tiên quyết"}],"questions":[{"q":"When will the workshop take place?","o":["November 10 and 11","November 12","November 13 and 14","Early next week"],"a":2,"vi":"'...will take place at our Da Nang office on November 13 and 14.' 12/11 là ngày bay, 10/11 là ngày chia sẻ hướng dẫn."},{"q":"Why must all backend engineers attend?","o":["The training is part of the new security policy","The trainer asked for it","The Da Nang office is opening","They need to set up new laptops"],"a":0,"vi":"'All backend engineers are required to attend, as the training is part of our new security policy.'"},{"q":"What should staff do if they want to travel on their own?","o":["Book a different hotel","Tell Tuan by Friday","Contact the trainer","Bring their own ticket"],"a":1,"vi":"'If you would rather travel on your own, please tell me by Friday...' – 'me' là Tuấn."},{"q":"What has changed from the original plan?","o":["The workshop location","The flight date","The hotel","The evening of the team dinner"],"a":3,"vi":"'...the team dinner has moved from the second evening to the first evening.'"}],"words":179},{"id":"r2-11","level":2,"type":"email","topic":"Sales","title":"Demo request from a new client","title_vi":"Yêu cầu demo từ khách hàng mới","head":[["From","Grace Tan <grace.tan@novalinea.com>"],["To","Minh Pham <minh.pham@novalinea.com>"],["Subject","Demo for Harbor Foods next Thursday"]],"paras":[[["Hi Minh,","Chào Minh,"]],[["Harbor Foods, a regional grocery chain, has asked us for a live demo of our support chatbot.","Harbor Foods, một chuỗi siêu thị trong khu vực, đã đề nghị chúng ta demo trực tiếp chatbot hỗ trợ khách hàng."],["They are comparing us with two other vendors and plan to make a decision by the end of the month.","Họ đang so sánh chúng ta với hai nhà cung cấp khác và dự định đưa ra quyết định trước cuối tháng."],["The demo is scheduled for next Thursday at 10 a.m., and it will run for about forty-five minutes.","Buổi demo được lên lịch vào 10 giờ sáng thứ Năm tới và sẽ kéo dài khoảng bốn mươi lăm phút."]],[["Their main concern is accuracy, because their current tool gives wrong answers about store opening hours.","Mối quan tâm chính của họ là độ chính xác, vì công cụ hiện tại của họ trả lời sai về giờ mở cửa của cửa hàng."],["Could you prepare a short example using their public FAQ page instead of our usual sample data?","Bạn có thể chuẩn bị một ví dụ ngắn dùng trang FAQ công khai của họ thay vì dữ liệu mẫu thường dùng của chúng ta không?"],["I will handle the pricing part, so you only need to cover the technical questions.","Tôi sẽ lo phần giá, nên bạn chỉ cần trả lời các câu hỏi kỹ thuật."]],[["Please send me the demo script by Tuesday afternoon so that I can review it before we rehearse on Wednesday.","Vui lòng gửi tôi kịch bản demo trước chiều thứ Ba để tôi có thể xem lại trước khi chúng ta tập dượt vào thứ Tư."],["If you need more time, let me know and I will ask Daniel from the solutions team to help.","Nếu bạn cần thêm thời gian, hãy cho tôi biết và tôi sẽ nhờ Daniel bên nhóm giải pháp hỗ trợ."]],[["Thanks,","Cảm ơn,"],["Grace","Grace"]]],"vocab":[{"w":"vendor","f":"vendors","pos":"n","ipa":"/ˈvɛndər/","vi":"nhà cung cấp, người bán hàng"},{"w":"accuracy","f":"accuracy","pos":"n","ipa":"/ˈækjərəsi/","vi":"độ chính xác"},{"w":"concern","f":"concern","pos":"n/v","ipa":"/kənˈsɜrn/","vi":"mối bận tâm; liên quan, lo lắng"},{"w":"decision","f":"decision","pos":"n","ipa":"/dɪˈsɪʒən/","vi":"sự quyết định; quyết định"},{"w":"make a decision","f":"make a decision","pos":"phrase","ipa":"","vi":"đưa ra quyết định"},{"w":"instead of","f":"instead of","pos":"phrase","ipa":"","vi":"thay vì"},{"w":"sample","f":"sample","pos":"n/v","ipa":"/ˈsæmpəl/","vi":"mẫu, hàng mẫu; lấy mẫu thử"},{"w":"script","f":"script","pos":"n/v","ipa":"/skrɪpt/","vi":"kịch bản, tập lệnh; viết kịch bản"},{"w":"handle","f":"handle","pos":"v/n","ipa":"/ˈhændl/","vi":"xử lý, giải quyết; tay cầm"},{"w":"schedule","f":"scheduled","pos":"n/v","ipa":"/ˈskɛdʒul/","vi":"lịch trình, tiến độ; lên lịch"},{"w":"rehearse","f":"rehearse","pos":"v","ipa":"/rɪˈhɜːrs/","vi":"diễn tập"},{"w":"let me know","f":"let me know","pos":"phrase","ipa":"/ˌlɛmi ˈnoʊ/","vi":"cho tôi biết nhé"}],"questions":[{"q":"Why is Harbor Foods interested in a new chatbot?","o":["Their current tool is too expensive","Their current tool gives wrong answers","Their contract will end this month","They are opening new stores"],"a":1,"vi":"Câu 'their current tool gives wrong answers about store opening hours' cho đáp án. Chuyện 'cuối tháng' là hạn ra quyết định, không phải hợp đồng hết hạn."},{"q":"What data should Minh use for the demo?","o":["The usual sample data","Data from two other vendors","Pricing data from Grace","Harbor Foods' public FAQ page"],"a":3,"vi":"Grace nhờ dùng 'their public FAQ page instead of our usual sample data'. Dữ liệu mẫu thường dùng là bẫy."},{"q":"When does Grace want to receive the demo script?","o":["By Tuesday afternoon","On Wednesday","Next Thursday at 10 a.m.","By the end of the month"],"a":0,"vi":"'Please send me the demo script by Tuesday afternoon'. Thứ Tư là buổi tập, thứ Năm là buổi demo."},{"q":"What will Grace do during the demo?","o":["Answer technical questions","Prepare the example","Explain the pricing","Contact Daniel"],"a":2,"vi":"'I will handle the pricing part' – Grace lo phần giá; Minh trả lời câu hỏi kỹ thuật. Daniel chỉ được nhờ nếu Minh cần thêm thời gian."}],"words":147},{"id":"r2-12","level":2,"type":"notice","topic":"Logistics","title":"GPU server delivery delayed","title_vi":"Việc giao máy chủ GPU bị chậm","head":[],"paras":[[["Notice to the ML Platform and Research teams","Thông báo gửi nhóm ML Platform và nhóm Research"]],[["The four new GPU servers ordered from our hardware supplier will not arrive on May 6 as planned.","Bốn máy chủ GPU mới đặt từ nhà cung cấp phần cứng sẽ không đến vào ngày 6 tháng 5 như kế hoạch."],["The shipment is being held at the port because some import documents were incomplete.","Lô hàng đang bị giữ ở cảng vì một số giấy tờ nhập khẩu chưa đầy đủ."],["The supplier has now sent the missing papers, and the new expected delivery date is May 20.","Nhà cung cấp đã gửi bổ sung giấy tờ còn thiếu, và ngày giao hàng dự kiến mới là 20 tháng 5."]],[["Because of this delay, the planned training runs for the new speech model will move to the last week of May.","Do sự chậm trễ này, các đợt huấn luyện dự kiến cho mô hình giọng nói mới sẽ dời sang tuần cuối tháng 5."],["In the meantime, teams with urgent jobs may request extra cloud capacity through the usual form.","Trong thời gian chờ, các nhóm có công việc gấp có thể yêu cầu thêm tài nguyên cloud qua biểu mẫu thông thường."],["Requests above 200 GPU hours need approval from Kevin Ross, the infrastructure manager.","Các yêu cầu trên 200 giờ GPU cần được Kevin Ross, trưởng bộ phận hạ tầng, phê duyệt."]],[["When the servers arrive, the facilities team will need two days to install them in the server room on the third floor.","Khi máy chủ đến, nhóm cơ sở vật chất sẽ cần hai ngày để lắp đặt chúng trong phòng máy chủ ở tầng ba."],["During installation, the room will be closed to all visitors.","Trong thời gian lắp đặt, phòng sẽ đóng cửa với tất cả khách."],["Please contact Linda Wu in Operations with any questions about the delivery.","Vui lòng liên hệ Linda Wu bên Vận hành nếu có thắc mắc về việc giao hàng."]]],"vocab":[{"w":"shipment","f":"shipment","pos":"n","ipa":"/ˈʃɪpmənt/","vi":"lô hàng; sự vận chuyển"},{"w":"delivery","f":"delivery","pos":"n","ipa":"/dɪˈlɪvəri/","vi":"sự giao hàng; việc bàn giao"},{"w":"delay","f":"delay","pos":"n/v","ipa":"/dɪˈleɪ/","vi":"sự chậm trễ; trì hoãn"},{"w":"hardware","f":"hardware","pos":"n","ipa":"/ˈhɑrdˌwɛr/","vi":"phần cứng máy tính; thiết bị kim khí"},{"w":"incomplete","f":"incomplete","pos":"adj","ipa":"/ˌɪnkəmˈpliːt/","vi":"chưa hoàn thành"},{"w":"in the meantime","f":"in the meantime","pos":"phrase","ipa":"","vi":"trong lúc chờ đợi"},{"w":"urgent","f":"urgent","pos":"adj","ipa":"/ˈɜːrdʒənt/","vi":"khẩn cấp; cấp bách"},{"w":"capacity","f":"capacity","pos":"n","ipa":"/kəˈpæsəti/","vi":"sức chứa, năng lực"},{"w":"infrastructure","f":"infrastructure","pos":"n","ipa":"/ˈɪnfrəstrʌktʃər/","vi":"cơ sở hạ tầng"},{"w":"installation","f":"installation","pos":"n","ipa":"/ˌɪnstəˈleɪʃn/","vi":"sự cài đặt; việc lắp đặt"},{"w":"request","f":"request","pos":"n/v","ipa":"/rɪˈkwest/","vi":"yêu cầu, lời thỉnh cầu"},{"w":"because of","f":"because of","pos":"phrase","ipa":"","vi":"vì, do"}],"questions":[{"q":"Why has the shipment been delayed?","o":["The supplier ran out of servers","The server room is not ready","Some import documents were incomplete","The order was placed too late"],"a":2,"vi":"'being held at the port because some import documents were incomplete'. Phòng máy chủ chỉ được nhắc tới khi lắp đặt."},{"q":"What is the new expected delivery date?","o":["May 20","May 6","The last week of May","Two days after May 6"],"a":0,"vi":"'the new expected delivery date is May 20'. Ngày 6/5 là ngày cũ; tuần cuối tháng 5 là lịch huấn luyện mới."},{"q":"Who must approve a request for 300 GPU hours of cloud capacity?","o":["Linda Wu","The facilities team","The hardware supplier","Kevin Ross"],"a":3,"vi":"Yêu cầu trên 200 giờ GPU 'need approval from Kevin Ross'. 300 > 200 nên cần Kevin duyệt. Linda Wu chỉ giải đáp về giao hàng."},{"q":"What will happen while the servers are being installed?","o":["Training runs will start","The server room will be closed to visitors","Cloud requests will be stopped","Operations will move to the third floor"],"a":1,"vi":"'During installation, the room will be closed to all visitors'. Tầng ba là vị trí phòng máy chủ, không phải nơi Operations chuyển đến."}],"words":151},{"id":"r2-13","level":2,"type":"job","topic":"Data","title":"Data Engineer (Pipelines)","title_vi":"Kỹ sư dữ liệu (Pipeline)","head":[],"paras":[[["Lumora Analytics is hiring a Data Engineer to join our Hanoi office.","Lumora Analytics đang tuyển một Kỹ sư dữ liệu làm việc tại văn phòng Hà Nội."],["The role reports to the Head of Data Platform and works closely with our machine learning team.","Vị trí này báo cáo cho Trưởng nhóm Data Platform và làm việc chặt chẽ với nhóm machine learning."]],[["You will build and maintain the pipelines that move customer data from our apps into the data warehouse.","Bạn sẽ xây dựng và duy trì các pipeline chuyển dữ liệu khách hàng từ các ứng dụng của chúng tôi vào kho dữ liệu."],["You will also improve data quality checks and help reduce our daily processing time, which is currently about six hours.","Bạn cũng sẽ cải thiện các bước kiểm tra chất lượng dữ liệu và giúp giảm thời gian xử lý hằng ngày, hiện mất khoảng sáu tiếng."]],[["Candidates should have at least three years of experience with Python and SQL.","Ứng viên cần có ít nhất ba năm kinh nghiệm với Python và SQL."],["Experience with Spark or a similar tool is required, while knowledge of cloud cost management is a plus.","Bắt buộc có kinh nghiệm với Spark hoặc công cụ tương tự, còn hiểu biết về quản lý chi phí cloud là một điểm cộng."],["Good written English is important because most of our documentation and meetings are in English.","Tiếng Anh viết tốt là quan trọng vì phần lớn tài liệu và các cuộc họp của chúng tôi bằng tiếng Anh."]],[["We offer a hybrid schedule with three office days per week, a yearly training budget of 1,000 dollars, and private health insurance.","Chúng tôi có lịch làm việc kết hợp với ba ngày lên văn phòng mỗi tuần, ngân sách đào tạo 1.000 đô la mỗi năm và bảo hiểm sức khỏe tư nhân."],["To apply, send your CV and a short description of one pipeline you have built to jobs@lumora-analytics.com.","Để ứng tuyển, hãy gửi CV và một đoạn mô tả ngắn về một pipeline bạn từng xây dựng tới jobs@lumora-analytics.com."],["Applications close on June 30, and the first interviews will take place in early July.","Hạn nộp hồ sơ là ngày 30 tháng 6, và vòng phỏng vấn đầu tiên sẽ diễn ra vào đầu tháng 7."]]],"vocab":[{"w":"pipeline","f":"pipeline","pos":"n","ipa":"/ˈpaɪplaɪn/","vi":"đường ống; quy trình xử lý"},{"w":"warehouse","f":"warehouse","pos":"n","ipa":"/ˈwɛrˌhaʊs/","vi":"kho hàng"},{"w":"maintain","f":"maintain","pos":"v","ipa":"/mɛnˈteɪn/","vi":"duy trì, bảo trì"},{"w":"require","f":"required","pos":"v","ipa":"/rɪˈkwaɪər/","vi":"yêu cầu, đòi hỏi"},{"w":"knowledge","f":"knowledge","pos":"n","ipa":"/ˈnɑːlɪdʒ/","vi":"kiến thức, hiểu biết"},{"w":"hybrid","f":"hybrid","pos":"adj/n","ipa":"/ˈhaɪbrɪd/","vi":"lai, kết hợp"},{"w":"budget","f":"budget","pos":"n/v","ipa":"/ˈbʌdʒɪt/","vi":"ngân sách; lên ngân sách"},{"w":"apply","f":"apply","pos":"v","ipa":"/əˈplaɪ/","vi":"nộp đơn; áp dụng"},{"w":"application","f":"applications","pos":"n","ipa":"/ˌæplɪˈkeɪʃn/","vi":"ứng dụng; đơn xin"},{"w":"interview","f":"interviews","pos":"n/v","ipa":"/ˈɪntərvjuː/","vi":"phuốc phỏng vấn; phỏng vấn"},{"w":"reduce","f":"reduce","pos":"v","ipa":"/rɪˈduːs/","vi":"giảm bớt, cắt giảm"},{"w":"documentation","f":"documentation","pos":"n","ipa":"/ˌdɑːkjumənˈteɪʃn/","vi":"tài liệu hướng dẫn"}],"questions":[{"q":"What is one goal of the job?","o":["Building mobile apps","Managing the machine learning team","Writing English documentation","Reducing daily processing time"],"a":3,"vi":"'help reduce our daily processing time, which is currently about six hours'. Nhóm ML chỉ là nhóm phối hợp, không phải người được quản lý."},{"q":"Which skill is described as a plus, not a requirement?","o":["Python and SQL","Cloud cost management","Spark or a similar tool","Written English"],"a":1,"vi":"'knowledge of cloud cost management is a plus'. Spark là 'required', Python/SQL là yêu cầu ba năm kinh nghiệm."},{"q":"What must applicants send besides their CV?","o":["A reference letter","A training plan","A description of a pipeline they built","Their salary expectations"],"a":2,"vi":"'send your CV and a short description of one pipeline you have built'. Ngân sách đào tạo là quyền lợi, không phải hồ sơ."},{"q":"How many days per week must the employee work in the office?","o":["Three","Five","Six","One"],"a":0,"vi":"'a hybrid schedule with three office days per week'. Số sáu là số giờ xử lý dữ liệu hiện tại."}],"words":170},{"id":"r2-14","level":2,"type":"chat","topic":"Service","title":"Customers cannot log in","title_vi":"Khách hàng không đăng nhập được","head":[],"paras":[[["Rachel (Support), 9:12: We've had 40 tickets in the last hour from customers who can't log in to the mobile app.","Rachel (Hỗ trợ), 9:12: Trong một giờ qua chúng ta đã nhận 40 ticket từ khách hàng không đăng nhập được vào ứng dụng di động."],["Rachel (Support), 9:12: The web version seems fine.","Rachel (Hỗ trợ), 9:12: Bản web có vẻ vẫn bình thường."]],[["Tuan (Backend), 9:15: Thanks, I'm looking into it now.","Tuấn (Backend), 9:15: Cảm ơn, mình đang kiểm tra ngay."],["Tuan (Backend), 9:15: It started right after this morning's release, so the new token setting is my first guess.","Tuấn (Backend), 9:15: Lỗi bắt đầu ngay sau bản phát hành sáng nay, nên mình đoán trước tiên là do cấu hình token mới."]],[["Rachel (Support), 9:18: Should I tell customers to reinstall the app?","Rachel (Hỗ trợ), 9:18: Mình có nên bảo khách cài lại ứng dụng không?"]],[["Tuan (Backend), 9:20: No, that won't help.","Tuấn (Backend), 9:20: Không, cách đó không giúp được gì."],["Tuan (Backend), 9:20: Please ask them to use the website for now, and I'll roll back the release.","Tuấn (Backend), 9:20: Bạn hãy nhờ họ dùng website tạm thời, còn mình sẽ rollback bản phát hành."],["Tuan (Backend), 9:20: It should take about twenty minutes.","Tuấn (Backend), 9:20: Việc này mất khoảng hai mươi phút."]],[["Helen (Eng Manager), 9:22: I'll post an update on the status page and let the account managers know.","Helen (Quản lý kỹ thuật), 9:22: Mình sẽ đăng cập nhật lên trang trạng thái và báo cho các account manager."],["Helen (Eng Manager), 9:22: Tuan, once it's fixed, please write a short incident report by tomorrow noon.","Helen (Quản lý kỹ thuật), 9:22: Tuấn, khi sửa xong, em viết giúp một báo cáo sự cố ngắn trước trưa mai nhé."]],[["Tuan (Backend), 9:45: Rollback done, and logins are working again.","Tuấn (Backend), 9:45: Đã rollback xong, đăng nhập hoạt động lại rồi."],["Tuan (Backend), 9:45: Rachel, could you reply to the affected customers and close the tickets after they confirm?","Tuấn (Backend), 9:45: Rachel, bạn có thể trả lời những khách hàng bị ảnh hưởng và đóng ticket sau khi họ xác nhận không?"]]],"vocab":[{"w":"ticket","f":"tickets","pos":"n","ipa":"/ˈtɪkɪt/","vi":"vé; phiếu yêu cầu hỗ trợ"},{"w":"release","f":"release","pos":"v/n","ipa":"/rɪˈliːs/","vi":"phát hành, tung ra; sự phát hành"},{"w":"roll back","f":"roll back","pos":"phrase","ipa":"","vi":"quay về bản trước"},{"w":"for now","f":"for now","pos":"phrase","ipa":"","vi":"tạm thời, bây giờ"},{"w":"status","f":"status","pos":"n","ipa":"/ˈsteɪtəs/","vi":"trạng thái, địa vị"},{"w":"affect","f":"affected","pos":"v","ipa":"/əˈfekt/","vi":"ảnh hưởng"},{"w":"version","f":"version","pos":"n","ipa":"/ˈvɜːrʒn/","vi":"phiên bản"},{"w":"reply","f":"reply","pos":"v/n","ipa":"/rɪˈplaɪ/","vi":"trả lời; hồi âm"},{"w":"confirm","f":"confirm","pos":"v","ipa":"/kənˈfɜːrm/","vi":"xác nhận; khẳng định"},{"w":"account","f":"account","pos":"n/v","ipa":"/əˈkaʊnt/","vi":"tài khoản; giải thích"},{"w":"could you","f":"could you","pos":"phrase","ipa":"/ˈkʊdʒə/","vi":"bạn có thể ... không (nối âm)"}],"questions":[{"q":"What does Tuan think caused the problem?","o":["A setting in this morning's release","An old version of the app","Problems with the website","Too many support tickets"],"a":0,"vi":"'It started right after this morning's release, so the new token setting is my first guess'. Bản web vẫn bình thường nên C sai."},{"q":"What should customers do until the issue is fixed?","o":["Reinstall the app","Wait twenty minutes","Use the website","Contact their account manager"],"a":2,"vi":"'Please ask them to use the website for now'. Cài lại ứng dụng thì Tuấn nói 'that won't help'."},{"q":"Who will update the status page?","o":["Rachel","Helen","Tuan","The account managers"],"a":1,"vi":"Helen viết 'I'll post an update on the status page'. Account manager chỉ là người được thông báo."},{"q":"What is Tuan asked to do by tomorrow noon?","o":["Close the tickets","Release a new version","Call the affected customers","Write an incident report"],"a":3,"vi":"Helen yêu cầu 'write a short incident report by tomorrow noon'. Đóng ticket là việc Tuấn nhờ Rachel làm."}],"words":177},{"id":"r2-15","level":2,"type":"article","topic":"Legal","title":"Faster contract reviews for vendors","title_vi":"Rà soát hợp đồng nhà cung cấp nhanh hơn","head":[],"paras":[[["From next month, engineering teams at Corvane Systems will follow a new process when they want to use an outside software vendor.","Từ tháng tới, các nhóm kỹ thuật tại Corvane Systems sẽ áp dụng quy trình mới khi muốn sử dụng một nhà cung cấp phần mềm bên ngoài."],["In the past, every vendor contract went to the legal team, and a review often took four to six weeks.","Trước đây, mọi hợp đồng với nhà cung cấp đều chuyển đến nhóm pháp lý, và một lần rà soát thường mất từ bốn đến sáu tuần."]],[["Under the new process, contracts worth less than 10,000 dollars a year can use a standard agreement prepared by the legal team.","Theo quy trình mới, các hợp đồng trị giá dưới 10.000 đô la mỗi năm có thể dùng mẫu thỏa thuận chuẩn do nhóm pháp lý soạn sẵn."],["Team leads can sign these agreements themselves after completing a short online checklist.","Trưởng nhóm có thể tự ký các thỏa thuận này sau khi hoàn thành một bảng kiểm trực tuyến ngắn."],["Larger contracts, or any contract where the vendor will store customer data, still need a full legal review.","Các hợp đồng lớn hơn, hoặc bất kỳ hợp đồng nào mà nhà cung cấp sẽ lưu trữ dữ liệu khách hàng, vẫn cần được nhóm pháp lý rà soát đầy đủ."]],[["According to Sofia Marin, head of legal, the change will let her team focus on high-risk agreements.","Theo Sofia Marin, trưởng bộ phận pháp lý, thay đổi này giúp nhóm của cô tập trung vào các thỏa thuận có rủi ro cao."],["\"Most small tools, such as design plugins or testing services, carry very little risk,\" she said.","\"Phần lớn công cụ nhỏ, như plugin thiết kế hay dịch vụ kiểm thử, có rủi ro rất thấp,\" cô nói."],["The company expects the average review time for small contracts to drop to three days.","Công ty kỳ vọng thời gian rà soát trung bình cho hợp đồng nhỏ sẽ giảm xuống còn ba ngày."]],[["A one-hour training session on the checklist will be held on the 14th for all team leads.","Một buổi đào tạo một giờ về bảng kiểm sẽ được tổ chức vào ngày 14 cho tất cả trưởng nhóm."]]],"vocab":[{"w":"vendor","f":"vendor","pos":"n","ipa":"/ˈvɛndər/","vi":"nhà cung cấp, người bán hàng"},{"w":"contract","f":"contract","pos":"n/v","ipa":"/ˈkɑntrækt/","vi":"hợp đồng; ký kết"},{"w":"agreement","f":"agreement","pos":"n","ipa":"/əˈɡriːmənt/","vi":"hợp đồng, thỏa thuận"},{"w":"standard","f":"standard","pos":"n/adj","ipa":"/ˈstændərd/","vi":"Tiêu chuẩn"},{"w":"risk","f":"risk","pos":"n/v","ipa":"/rɪsk/","vi":"Rủi ro; liều lĩnh"},{"w":"focus","f":"focus","pos":"v/n","ipa":"/ˈfoʊkəs/","vi":"Tập trung; trọng tâm"},{"w":"average","f":"average","pos":"adj/n","ipa":"/ˈævərɪdʒ/","vi":"trung bình"},{"w":"complete","f":"completing","pos":"adj/v","ipa":"/kəmˈpliːt/","vi":"hoàn thành, đầy đủ"},{"w":"review","f":"review","pos":"n/v","ipa":"/rɪˈvyu/","vi":"xem xét, đánh giá"},{"w":"sign","f":"sign","pos":"n/v","ipa":"/saɪn/","vi":"ký tên; dấu hiệu"},{"w":"expect","f":"expects","pos":"v","ipa":"/ɪkˈspɛkt/","vi":"mong đợi, kỳ vọng"}],"questions":[{"q":"How long did a vendor contract review usually take before?","o":["Three days","Four to six weeks","One hour","One month"],"a":1,"vi":"'a review often took four to six weeks'. Ba ngày là thời gian kỳ vọng sau thay đổi."},{"q":"Which contract can a team lead sign without a full legal review?","o":["An 8,000-dollar testing service","A 15,000-dollar data platform","A 5,000-dollar tool that stores customer data","Any contract after the training"],"a":0,"vi":"Dưới 10.000 đô la và không lưu dữ liệu khách hàng thì dùng mẫu chuẩn. 5.000 đô nhưng lưu dữ liệu khách hàng vẫn cần rà soát đầy đủ."},{"q":"Why is the company making this change, according to Sofia Marin?","o":["To save money on legal fees","To reduce the number of vendors","To protect customer data better","To let legal focus on high-risk agreements"],"a":3,"vi":"'the change will let her team focus on high-risk agreements'. Dữ liệu khách hàng là điều kiện cần rà soát, không phải lý do thay đổi."},{"q":"What will happen on the 14th?","o":["The new process will start","Legal will sign all small contracts","Team leads will attend a training session","Vendors will receive a checklist"],"a":2,"vi":"'A one-hour training session on the checklist will be held on the 14th for all team leads'. Quy trình mới bắt đầu 'from next month'."}],"words":161},{"id":"r2-16","level":2,"type":"email","topic":"Travel","title":"Your trip to the AI Summit","title_vi":"Chuyến đi dự AI Summit của bạn","head":[["From","Paula Reyes <travel@quillmark.io>"],["To","Huy Nguyen <huy.nguyen@quillmark.io>"],["Subject","Travel details: Singapore, Sept 9-12"]],"paras":[[["Dear Huy,","Chào anh Huy,"]],[["Your trip to the Applied AI Summit in Singapore has been approved.","Chuyến đi dự Applied AI Summit tại Singapore của anh đã được phê duyệt."],["You will fly out on September 9 at 7:40 a.m. and return on September 12 in the evening.","Anh sẽ bay đi lúc 7 giờ 40 sáng ngày 9 tháng 9 và quay về vào tối ngày 12 tháng 9."],["I have booked three nights at a hotel ten minutes' walk from the conference center, and breakfast is included.","Tôi đã đặt ba đêm tại một khách sạn cách trung tâm hội nghị mười phút đi bộ, đã bao gồm bữa sáng."]],[["The company will pay for your flight, hotel and conference ticket directly.","Công ty sẽ thanh toán trực tiếp vé máy bay, khách sạn và vé hội nghị."],["For other costs, you will receive a daily allowance of 60 dollars for meals and local transport.","Với các chi phí khác, anh sẽ nhận phụ cấp 60 đô la mỗi ngày cho ăn uống và đi lại tại địa phương."],["Taxis to and from the airport can be claimed separately, but please keep your receipts.","Taxi đi và về sân bay có thể được thanh toán riêng, nhưng anh vui lòng giữ lại hóa đơn."]],[["Please note that the expense policy has changed this year.","Xin lưu ý rằng chính sách chi phí đã thay đổi trong năm nay."],["All claims must now be submitted through the new finance app within ten days of your return, not thirty days as before.","Tất cả yêu cầu thanh toán giờ phải được gửi qua ứng dụng tài chính mới trong vòng mười ngày sau khi về, thay vì ba mươi ngày như trước."],["Also, your manager, Oscar, has asked you to share three key takeaways from the summit at the team meeting on September 16.","Ngoài ra, quản lý của anh, Oscar, đã đề nghị anh chia sẻ ba điểm chính rút ra từ hội nghị tại cuộc họp nhóm ngày 16 tháng 9."]],[["Have a great trip!","Chúc anh có một chuyến đi tốt đẹp!"],["Paula","Paula"]]],"vocab":[{"w":"conference","f":"conference","pos":"n","ipa":"/ˈkɑnfərəns/","vi":"hội nghị, cuộc họp lớn"},{"w":"allowance","f":"allowance","pos":"n","ipa":"/əˈlaʊəns/","vi":"tiền phụ cấp; hạn mức"},{"w":"receipt","f":"receipts","pos":"n","ipa":"/rɪˈsit/","vi":"biên lai; hóa đơn"},{"w":"expense","f":"expense","pos":"n","ipa":"/ɪkˈspens/","vi":"chi phí"},{"w":"policy","f":"policy","pos":"n","ipa":"/ˈpɑːləsi/","vi":"chính sách"},{"w":"separately","f":"separately","pos":"adv","ipa":"/ˈseprətli/","vi":"riêng biệt"},{"w":"directly","f":"directly","pos":"adv","ipa":"/dəˈrektli/","vi":"trực tiếp"},{"w":"airport","f":"airport","pos":"n","ipa":"/ˈɛrpɔrt/","vi":"sân bay"},{"w":"trip","f":"trip","pos":"n/v","ipa":"/trɪp/","vi":"chuyến đi công tác; vấp ngã"},{"w":"share","f":"share","pos":"v/n","ipa":"/ʃɛr/","vi":"chia sẻ, dùng chung; cổ phần"}],"questions":[{"q":"What will Huy have to pay for and claim later?","o":["His hotel room","His conference ticket","His flight","Taxis to and from the airport"],"a":3,"vi":"'Taxis to and from the airport can be claimed separately'. Vé máy bay, khách sạn, vé hội nghị do công ty trả trực tiếp."},{"q":"What has changed in the expense policy?","o":["The daily allowance is now 60 dollars","Receipts are no longer needed","Claims must be submitted within ten days","Breakfast is no longer included"],"a":2,"vi":"'within ten days of your return, not thirty days as before' – đây là thay đổi. 60 đô là mức phụ cấp, không được nói là mới."},{"q":"What is the daily allowance meant to cover?","o":["Meals and local transport","Hotel and breakfast","Conference materials","Airport taxis"],"a":0,"vi":"'a daily allowance of 60 dollars for meals and local transport'. Taxi sân bay được thanh toán riêng."},{"q":"What is Huy expected to do on September 16?","o":["Submit his expense claim","Present key takeaways to his team","Meet Paula at the conference center","Fly back from Singapore"],"a":1,"vi":"Oscar muốn Huy 'share three key takeaways from the summit at the team meeting on September 16'. Huy về ngày 12."}],"words":156},{"id":"r2-17","level":2,"type":"chat","topic":"Data","title":"Evaluation results are delayed","title_vi":"Kết quả đánh giá bị chậm","head":[],"paras":[[["Priya (ML), 8:30: Morning all.","Priya (ML), 8:30: Chào buổi sáng mọi người."],["Priya (ML), 8:30: The nightly evaluation for the ranking model didn't finish, so we don't have new accuracy numbers for today's review.","Priya (ML), 8:30: Đợt đánh giá chạy hằng đêm cho mô hình xếp hạng đã không chạy xong, nên chúng ta chưa có số liệu độ chính xác mới cho buổi review hôm nay."]],[["Marco (Data Eng), 8:36: That's on our side, sorry.","Marco (Data Eng), 8:36: Lỗi là ở phía bọn mình, xin lỗi nhé."],["Marco (Data Eng), 8:36: The pipeline that prepares the test set failed at 2 a.m. because a source table changed its column names.","Marco (Data Eng), 8:36: Pipeline chuẩn bị tập test bị lỗi lúc 2 giờ sáng vì một bảng nguồn đã đổi tên cột."]],[["Priya (ML), 8:38: How long will the fix take?","Priya (ML), 8:38: Sửa mất bao lâu vậy?"]],[["Marco (Data Eng), 8:41: I can update the mapping in about an hour, then the evaluation needs roughly three hours to run.","Marco (Data Eng), 8:41: Mình có thể cập nhật phần mapping trong khoảng một tiếng, sau đó đợt đánh giá cần chạy khoảng ba tiếng."],["Marco (Data Eng), 8:41: Results should be ready around 1 p.m.","Marco (Data Eng), 8:41: Kết quả sẽ có vào khoảng 1 giờ chiều."]],[["Priya (ML), 8:43: The review with the product team is at 11, so we'll use last week's numbers and share the new ones later.","Priya (ML), 8:43: Buổi review với nhóm sản phẩm lúc 11 giờ, nên chúng ta sẽ dùng số liệu của tuần trước và chia sẻ số mới sau."],["Priya (ML), 8:43: Can we also make sure this doesn't happen again?","Priya (ML), 8:43: Chúng ta có thể đảm bảo chuyện này không lặp lại được không?"]],[["Marco (Data Eng), 8:46: Yes, I'll add a schema check that sends an alert before the job starts.","Marco (Data Eng), 8:46: Được, mình sẽ thêm bước kiểm tra schema để gửi cảnh báo trước khi job bắt đầu."],["Marco (Data Eng), 8:46: I'll also ask the team that owns the source table to tell us about changes in advance.","Marco (Data Eng), 8:46: Mình cũng sẽ nhờ nhóm sở hữu bảng nguồn báo trước cho bọn mình khi có thay đổi."]]],"vocab":[{"w":"pipeline","f":"pipeline","pos":"n","ipa":"/ˈpaɪplaɪn/","vi":"đường ống; quy trình xử lý"},{"w":"accuracy","f":"accuracy","pos":"n","ipa":"/ˈækjərəsi/","vi":"độ chính xác"},{"w":"alert","f":"alert","pos":"n/adj/v","ipa":"/əˈlɜrt/","vi":"cảnh báo; tỉnh táo"},{"w":"source","f":"source","pos":"n","ipa":"/sɔːrs/","vi":"nguồn, mã nguồn"},{"w":"fail","f":"failed","pos":"v","ipa":"/feɪl/","vi":"thất bại; hỏng"},{"w":"in advance","f":"in advance","pos":"phrase","ipa":"","vi":"trước, sẵn"},{"w":"make sure","f":"make sure","pos":"phrase","ipa":"","vi":"đảm bảo"},{"w":"model","f":"model","pos":"n/v","ipa":"/ˈmɑːdl/","vi":"mô hình; mẫu"},{"w":"ready","f":"ready","pos":"adj","ipa":"/ˈredi/","vi":"sẵn sàng"},{"w":"review","f":"review","pos":"n/v","ipa":"/rɪˈvyu/","vi":"xem xét, đánh giá"}],"questions":[{"q":"Why did the pipeline fail?","o":["The evaluation took too long","The test set was too large","The ranking model had a bug","A source table changed its column names"],"a":3,"vi":"'failed at 2 a.m. because a source table changed its column names'. Mô hình xếp hạng không có lỗi."},{"q":"When are the new results expected?","o":["At 11 a.m.","At 2 a.m.","Around 1 p.m.","Next week"],"a":2,"vi":"'Results should be ready around 1 p.m.' 11 giờ là giờ review, 2 giờ sáng là lúc pipeline lỗi."},{"q":"What will Priya show at the product review?","o":["The new accuracy numbers","Last week's numbers","A schema check report","An estimate from Marco"],"a":1,"vi":"'we'll use last week's numbers and share the new ones later' vì kết quả mới chỉ có lúc 1 giờ chiều."},{"q":"What will Marco do to prevent the problem in the future?","o":["Add a schema check with an alert","Run the evaluation every hour","Move the review to the afternoon","Take ownership of the source table"],"a":0,"vi":"'I'll add a schema check that sends an alert before the job starts'. Marco chỉ nhờ nhóm sở hữu bảng báo trước, không nhận quyền sở hữu."}],"words":189},{"id":"r2-18","level":2,"type":"notice","topic":"Legal","title":"Open-source license training","title_vi":"Đào tạo về giấy phép mã nguồn mở","head":[],"paras":[[["Mandatory training: using open-source code in our products","Đào tạo bắt buộc: sử dụng mã nguồn mở trong sản phẩm của chúng ta"]],[["All software engineers, including contractors, must complete a new training course on open-source licenses by March 31.","Tất cả kỹ sư phần mềm, kể cả nhân sự hợp đồng, phải hoàn thành khóa đào tạo mới về giấy phép mã nguồn mở trước ngày 31 tháng 3."],["The course was created after a recent audit found several libraries in our mobile app whose licenses had not been checked.","Khóa học được xây dựng sau khi một đợt kiểm toán gần đây phát hiện một số thư viện trong ứng dụng di động mà giấy phép chưa được kiểm tra."]],[["The course takes about 45 minutes and is available on the learning portal.","Khóa học mất khoảng 45 phút và có trên cổng học tập."],["It explains which licenses are safe to use, which ones need approval, and how to record new libraries in the dependency list.","Khóa học giải thích giấy phép nào an toàn để dùng, giấy phép nào cần phê duyệt, và cách ghi lại thư viện mới vào danh sách phụ thuộc."],["You need a score of at least 80 percent on the final quiz to pass, and you may retake it as many times as you like.","Bạn cần đạt ít nhất 80 phần trăm ở bài kiểm tra cuối để qua, và có thể làm lại bao nhiêu lần tùy ý."]],[["From April 1, pull requests that add a new library will be blocked automatically if the author has not passed the course.","Từ ngày 1 tháng 4, các pull request thêm thư viện mới sẽ tự động bị chặn nếu người tạo chưa qua khóa học."],["Team leads will receive a weekly report showing who has not finished yet.","Các trưởng nhóm sẽ nhận báo cáo hằng tuần cho biết ai chưa hoàn thành."],["If you have questions about a specific license, please contact the legal team at oss-help@brennick.dev rather than your team lead.","Nếu có thắc mắc về một giấy phép cụ thể, vui lòng liên hệ nhóm pháp lý qua oss-help@brennick.dev thay vì trưởng nhóm của bạn."]]],"vocab":[{"w":"mandatory","f":"mandatory","pos":"adj","ipa":"/ˈmændəˌtɔri/","vi":"bắt buộc"},{"w":"audit","f":"audit","pos":"n/v","ipa":"/ˈɔːdɪt/","vi":"kiểm toán"},{"w":"contractor","f":"contractors","pos":"n","ipa":"/ˈkɑːntræktər/","vi":"nhà thầu"},{"w":"dependency","f":"dependency","pos":"n","ipa":"/dɪˈpɛndənsi/","vi":"sự phụ thuộc, phần phụ thuộc"},{"w":"specific","f":"specific","pos":"adj","ipa":"/spəˈsɪfɪk/","vi":"cụ thể, đặc trưng"},{"w":"rather than","f":"rather than","pos":"phrase","ipa":"","vi":"hơn là, thay vì"},{"w":"available","f":"available","pos":"adj","ipa":"/əˈveɪləbəl/","vi":"có sẵn; rảnh rỗi"},{"w":"record","f":"record","pos":"n/v","ipa":"/ˈrɛkərd/","vi":"hồ sơ, ghi chép; lưu trữ"},{"w":"pull","f":"pull","pos":"v/n","ipa":"/pʊl/","vi":"kéo; sự kéo"},{"w":"request","f":"requests","pos":"n/v","ipa":"/rɪˈkwest/","vi":"yêu cầu, lời thỉnh cầu"},{"w":"complete","f":"complete","pos":"adj/v","ipa":"/kəmˈpliːt/","vi":"hoàn thành, đầy đủ"}],"questions":[{"q":"Why was the training course created?","o":["An audit found unchecked licenses","New contractors joined the company","The learning portal was updated","A mobile app was launched"],"a":0,"vi":"'created after a recent audit found several libraries ... whose licenses had not been checked'."},{"q":"What is needed to pass the course?","o":["Finishing within 45 minutes","A score of at least 80 percent","Approval from a team lead","Adding a library to the dependency list"],"a":1,"vi":"'You need a score of at least 80 percent on the final quiz to pass'. 45 phút là thời lượng khóa học, không phải điều kiện."},{"q":"What will happen from April 1 to engineers who have not passed?","o":["They will lose access to the portal","Their team lead will call them","Their pull requests adding a new library will be blocked","They must retake the audit"],"a":2,"vi":"'pull requests that add a new library will be blocked automatically if the author has not passed'. Trưởng nhóm chỉ nhận báo cáo hằng tuần."},{"q":"Whom should engineers contact about a specific license?","o":["Their team lead","The audit team","The learning portal","The legal team"],"a":3,"vi":"'contact the legal team at oss-help@brennick.dev rather than your team lead'. Trưởng nhóm là bẫy."}],"words":164},{"id":"r2-19","level":2,"type":"email","topic":"Sales","title":"Engineers needed for sales calls","title_vi":"Cần kỹ sư hỗ trợ các cuộc gọi bán hàng","head":[["From","Ben Carter <ben.carter@altivo.ai>"],["To","Engineering leads"],["Subject","Technical support for Q3 sales calls"]],"paras":[[["Hello everyone,","Chào mọi người,"]],[["As you may know, our sales target for the third quarter has been raised by 20 percent after the launch of the document search product.","Như mọi người có thể đã biết, chỉ tiêu doanh số quý ba đã được nâng thêm 20 phần trăm sau khi ra mắt sản phẩm tìm kiếm tài liệu."],["Many potential customers now ask detailed questions about security and integration, and our sales team cannot always answer them.","Nhiều khách hàng tiềm năng giờ hỏi chi tiết về bảo mật và tích hợp, và đội bán hàng không phải lúc nào cũng trả lời được."]],[["We would like each engineering team to name one engineer who can join two or three customer calls per week.","Chúng tôi muốn mỗi nhóm kỹ thuật cử một kỹ sư có thể tham gia hai đến ba cuộc gọi với khách hàng mỗi tuần."],["Each call lasts about 30 minutes, and the sales representative will lead the conversation.","Mỗi cuộc gọi kéo dài khoảng 30 phút, và nhân viên kinh doanh sẽ dẫn dắt cuộc trò chuyện."],["The engineer only needs to answer technical questions and should not discuss prices or discounts.","Kỹ sư chỉ cần trả lời câu hỏi kỹ thuật và không nên bàn về giá hay chiết khấu."]],[["To thank volunteers, time spent on calls will count toward their quarterly goals, and they will be invited to the sales team's end-of-quarter dinner.","Để cảm ơn những người tham gia, thời gian dành cho các cuộc gọi sẽ được tính vào mục tiêu quý của họ, và họ sẽ được mời dự bữa tối cuối quý của đội bán hàng."],["Please reply with your team's name by Friday, July 5.","Vui lòng phản hồi tên người của nhóm mình trước thứ Sáu, ngày 5 tháng 7."],["We will hold a one-hour briefing for all selected engineers on July 9 to go over common questions.","Chúng tôi sẽ tổ chức buổi hướng dẫn một giờ cho tất cả kỹ sư được chọn vào ngày 9 tháng 7 để điểm qua các câu hỏi thường gặp."]],[["Best regards,","Trân trọng,"],["Ben Carter, Head of Sales","Ben Carter, Trưởng phòng Kinh doanh"]]],"vocab":[{"w":"target","f":"target","pos":"n/v","ipa":"/ˈtɑːrɡɪt/","vi":"mục tiêu; nhắm mục tiêu"},{"w":"quarter","f":"quarter","pos":"n","ipa":"/ˈkwɔːrtər/","vi":"quý (trong năm)"},{"w":"potential","f":"potential","pos":"adj/n","ipa":"/pəˈtɛnʃəl/","vi":"tiềm năng; khả năng"},{"w":"integration","f":"integration","pos":"n","ipa":"/ˌɪntɪˈɡreɪʃn/","vi":"sự tích hợp, hội nhập"},{"w":"security","f":"security","pos":"n","ipa":"/sɪˈkjʊrəti/","vi":"Bảo mật, an ninh"},{"w":"discuss","f":"discuss","pos":"v","ipa":"/dɪˈskʌs/","vi":"thảo luận"},{"w":"representative","f":"representative","pos":"n","ipa":"/ˌrɛprɪˈzɛntətɪv/","vi":"người đại diện, nhân viên bán hàng"},{"w":"go over","f":"go over","pos":"phrase","ipa":"","vi":"xem lại, điểm qua"},{"w":"launch","f":"launch","pos":"v/n","ipa":"/lɔːntʃ/","vi":"ra mắt, khởi động; sự ra mắt"},{"w":"invite","f":"invited","pos":"v","ipa":"/ɪnˈvaɪt/","vi":"mời"},{"w":"quarterly","f":"quarterly","pos":"adj/adv","ipa":"/ˈkwɔrtərli/","vi":"hàng quý"},{"w":"detail","f":"detailed","pos":"n/v","ipa":"/ˈdiːteɪl/","vi":"chi tiết; trình bày chi tiết"}],"questions":[{"q":"Why does the sales team need help from engineers?","o":["The sales team is short of staff","Customers ask detailed technical questions","The product launch was delayed","Engineers must set prices"],"a":1,"vi":"'Many potential customers now ask detailed questions about security and integration, and our sales team cannot always answer them'."},{"q":"What should engineers NOT do during calls?","o":["Answer security questions","Join two or three calls a week","Explain integration","Discuss prices or discounts"],"a":3,"vi":"'should not discuss prices or discounts'. Các lựa chọn còn lại là việc kỹ sư được yêu cầu làm."},{"q":"When should engineering leads reply?","o":["By July 9","By the end of the quarter","By Friday, July 5","Within 30 minutes"],"a":2,"vi":"'Please reply with your team's name by Friday, July 5'. Ngày 9/7 là buổi hướng dẫn."},{"q":"What will volunteers receive?","o":["Time on calls counted toward their goals","A 20 percent bonus","A one-hour training budget","A new product license"],"a":0,"vi":"'time spent on calls will count toward their quarterly goals' và được mời ăn tối. 20 phần trăm là mức tăng chỉ tiêu doanh số."}],"words":154},{"id":"r2-20","level":2,"type":"article","topic":"Service","title":"Chat assistant cuts waiting time","title_vi":"Trợ lý chat giảm thời gian chờ","head":[],"paras":[[["Three months after launching its AI chat assistant, the customer service team at Pelora Insurance has shared its first results.","Ba tháng sau khi ra mắt trợ lý chat AI, đội chăm sóc khách hàng tại Pelora Insurance đã công bố những kết quả đầu tiên."],["The assistant now handles about 35 percent of all incoming questions without help from a human agent.","Trợ lý hiện xử lý khoảng 35 phần trăm tổng số câu hỏi gửi đến mà không cần nhân viên hỗ trợ."]],[["The biggest change has been in waiting time.","Thay đổi lớn nhất là ở thời gian chờ."],["Customers used to wait an average of twelve minutes to reach an agent, but that figure has fallen to four minutes.","Trước đây khách hàng phải chờ trung bình mười hai phút để gặp nhân viên, nhưng con số đó đã giảm xuống còn bốn phút."],["Customer satisfaction scores have also risen slightly, from 7.8 to 8.1 out of 10.","Điểm hài lòng của khách hàng cũng tăng nhẹ, từ 7,8 lên 8,1 trên thang 10."]],[["However, the team says the assistant still struggles with questions about claims that involve several documents.","Tuy nhiên, đội cho biết trợ lý vẫn gặp khó với các câu hỏi về yêu cầu bồi thường liên quan đến nhiều tài liệu."],["In these cases, it now passes the conversation to an agent along with a short summary, so customers do not have to repeat themselves.","Trong những trường hợp này, trợ lý sẽ chuyển cuộc trò chuyện cho nhân viên kèm một bản tóm tắt ngắn để khách hàng không phải nhắc lại."]],[["Service manager Ivan Kowal said no agents have lost their jobs.","Quản lý dịch vụ Ivan Kowal cho biết không có nhân viên nào bị mất việc."],["Instead, several agents have moved to a new team that reviews the assistant's answers every week and suggests improvements.","Thay vào đó, một số nhân viên đã chuyển sang nhóm mới chuyên xem xét câu trả lời của trợ lý hằng tuần và đề xuất cải tiến."],["The company plans to add Vietnamese and Thai language support before the end of the year.","Công ty dự định bổ sung hỗ trợ tiếng Việt và tiếng Thái trước cuối năm."]]],"vocab":[{"w":"launch","f":"launching","pos":"v/n","ipa":"/lɔːntʃ/","vi":"ra mắt, khởi động; sự ra mắt"},{"w":"handle","f":"handles","pos":"v/n","ipa":"/ˈhændl/","vi":"xử lý, giải quyết; tay cầm"},{"w":"incoming","f":"incoming","pos":"adj","ipa":"/ˈɪnˌkʌmɪŋ/","vi":"đến; sắp tới"},{"w":"average","f":"average","pos":"adj/n","ipa":"/ˈævərɪdʒ/","vi":"trung bình"},{"w":"involve","f":"involve","pos":"v","ipa":"/ɚɐnɑːlv/","vi":"bao gồm; liân quan"},{"w":"repeat","f":"repeat","pos":"v/n","ipa":"/rɪˈpiːt/","vi":"lặp lại"},{"w":"improvement","f":"improvements","pos":"n","ipa":"/ɪmˈpruvmənt/","vi":"sự cải tiến, sự cải thiện"},{"w":"suggest","f":"suggests","pos":"v","ipa":"/səɡˈdʒɛst/","vi":"đề xuất, gợi ý"},{"w":"instead","f":"instead","pos":"adv","ipa":"/ɪnˈstɛd/","vi":"Thay vì, thay thế"},{"w":"however","f":"however","pos":"phrase","ipa":"","vi":"tuy nhiên"},{"w":"have to","f":"have to","pos":"phrase","ipa":"/ˈhæftə/","vi":"phải (làm gì)"}],"questions":[{"q":"What is the average waiting time now?","o":["Twelve minutes","Thirty-five minutes","Four minutes","Eight minutes"],"a":2,"vi":"'that figure has fallen to four minutes'. Mười hai phút là thời gian chờ trước đây; 35 là phần trăm câu hỏi trợ lý xử lý."},{"q":"What does the assistant do with difficult claim questions?","o":["Passes them to an agent with a summary","Asks the customer to call later","Sends the customer several documents","Answers them more slowly"],"a":0,"vi":"'it now passes the conversation to an agent along with a short summary'."},{"q":"What happened to some of the agents?","o":["They lost their jobs","They started working part-time","They learned Vietnamese and Thai","They moved to a team that reviews the assistant's answers"],"a":3,"vi":"'several agents have moved to a new team that reviews the assistant's answers every week'. Ivan nói không ai mất việc."},{"q":"What does the company plan to do before the end of the year?","o":["Hire more agents","Add Vietnamese and Thai support","Raise satisfaction to 10","Stop using human agents"],"a":1,"vi":"'plans to add Vietnamese and Thai language support before the end of the year'."}],"words":168},{"id":"r3-01","level":3,"type":"report","topic":"Finance","title":"Q3 cloud cost review","title_vi":"Rà soát chi phí cloud quý 3","head":[],"paras":[[["This report summarises cloud spending for the AI Platform team at Norvale Systems in the third quarter, from July to September.","Báo cáo này tóm tắt chi tiêu cloud của nhóm AI Platform tại Norvale Systems trong quý 3, từ tháng 7 đến tháng 9."],["Total spending reached $184,000, which was 15% above the quarterly budget of $160,000.","Tổng chi tiêu đạt 184.000 đô la, cao hơn 15% so với ngân sách quý là 160.000 đô la."],["The finance department has asked every team that ran over budget to explain the variance by 14 October.","Phòng tài chính đã yêu cầu mọi nhóm vượt ngân sách giải trình phần chênh lệch trước ngày 14 tháng 10."]],[["Most of the overrun came from GPU instances used for model training, which cost $96,000 compared with an estimate of $70,000.","Phần lớn khoản vượt chi đến từ các instance GPU dùng để train model, tốn 96.000 đô la so với mức ước tính 70.000 đô la."],["In August, two training jobs were left running over a long weekend after the experiments had already finished, and they incurred about $11,000 in unnecessary charges.","Vào tháng 8, hai job training bị để chạy suốt một kỳ nghỉ cuối tuần dài dù các thí nghiệm đã kết thúc, và chúng phát sinh khoảng 11.000 đô la phí không cần thiết."],["Storage costs rose by 8%, mainly because older datasets were never moved to cheaper archive storage.","Chi phí lưu trữ tăng 8%, chủ yếu vì các dataset cũ chưa bao giờ được chuyển sang kho lưu trữ archive rẻ hơn."],["By contrast, spending on the inference servers fell slightly, as traffic to the chatbot pilot was lower than expected.","Ngược lại, chi tiêu cho các server inference giảm nhẹ, do lưu lượng truy cập vào bản thử nghiệm chatbot thấp hơn dự kiến."]],[["To prevent a repeat, the team will introduce three changes from 1 November.","Để tránh lặp lại tình trạng này, nhóm sẽ áp dụng ba thay đổi từ ngày 1 tháng 11."],["First, any training job that has been idle for more than two hours will be stopped automatically.","Thứ nhất, bất kỳ job training nào không hoạt động quá hai giờ sẽ tự động bị dừng."],["Second, datasets that have not been accessed for 90 days will be moved to archive storage.","Thứ hai, các dataset không được truy cập trong 90 ngày sẽ được chuyển sang kho archive."],["Third, engineers must get approval from their team lead before launching any job expected to cost more than $2,000.","Thứ ba, kỹ sư phải được trưởng nhóm phê duyệt trước khi chạy bất kỳ job nào dự kiến tốn hơn 2.000 đô la."]],[["Minh Tran, the platform lead, will be responsible for the new rules, and Sara Kowalski from finance will review the figures every month.","Minh Trần, trưởng nhóm platform, sẽ chịu trách nhiệm về các quy định mới, còn Sara Kowalski bên tài chính sẽ rà soát số liệu hằng tháng."],["If the changes work as planned, the team expects to return to budget in the fourth quarter and save roughly $20,000 compared with Q3.","Nếu các thay đổi hiệu quả như kế hoạch, nhóm dự kiến sẽ quay lại mức ngân sách trong quý 4 và tiết kiệm khoảng 20.000 đô la so với quý 3."]]],"vocab":[{"w":"quarterly","f":"quarterly","pos":"adj/adv","ipa":"/ˈkwɔrtərli/","vi":"hàng quý"},{"w":"budget","f":"budget","pos":"n/v","ipa":"/ˈbʌdʒɪt/","vi":"ngân sách; lên ngân sách"},{"w":"finance","f":"finance","pos":"n/v","ipa":"/ˈfaɪnæns/","vi":"tài chính; tài trợ"},{"w":"variance","f":"variance","pos":"n","ipa":"/ˈvɛriəns/","vi":"độ chênh lệch, phương sai"},{"w":"instance","f":"instances","pos":"n","ipa":"/ˈɪnstəns/","vi":"trường hợp, ví dụ"},{"w":"estimate","f":"estimate","pos":"v/n","ipa":"/ˈestɪmeɪt/","vi":"ước tính; bản dự toán"},{"w":"incur","f":"incurred","pos":"v","ipa":"/ɪnˈkɜr/","vi":"gánh chịu (chi phí, nợ)"},{"w":"archive","f":"archive","pos":"n/v","ipa":"/ˈɑr.kaɪv/","vi":"lưu trữ; kho lưu trữ"},{"w":"idle","f":"idle","pos":"adj/v","ipa":"/ˈaɪdəl/","vi":"Nhàn rỗi, không hoạt động"},{"w":"get approval","f":"get approval","pos":"phrase","ipa":"","vi":"được phê duyệt"},{"w":"be responsible for","f":"be responsible for","pos":"phrase","ipa":"","vi":"chịu trách nhiệm về"}],"questions":[{"q":"By how much did total spending exceed the quarterly budget?","o":["$11,000","$24,000","$26,000","$20,000"],"a":1,"vi":"Đoạn 1: tổng chi 184.000 so với ngân sách 160.000 → vượt 24.000. 26.000 là phần vượt riêng của GPU (96.000 − 70.000), 11.000 là phí job chạy thừa, 20.000 là khoản dự kiến tiết kiệm."},{"q":"What is NOT mentioned as a reason for higher costs?","o":["Training jobs left running over a weekend","Old datasets kept in standard storage","GPU training costing more than estimated","Higher traffic to the chatbot pilot"],"a":3,"vi":"Đoạn 2 nêu job chạy quên tắt, dataset cũ không chuyển sang archive và GPU vượt ước tính. Lưu lượng chatbot thì thấp hơn dự kiến, làm chi phí inference giảm, nên D không phải lý do."},{"q":"What will happen to a training job that is idle for over two hours?","o":["It will be stopped automatically","It will need approval from a team lead","It will be moved to archive storage","It will be reported to finance"],"a":0,"vi":"Đoạn 3, thay đổi thứ nhất: job idle quá hai giờ sẽ tự động bị dừng. Phê duyệt của trưởng nhóm là cho job trên 2.000 đô la; chuyển sang archive là dành cho dataset."},{"q":"Who will check the spending figures each month?","o":["Minh Tran","The team leads","Sara Kowalski","The finance director"],"a":2,"vi":"Đoạn 4: Sara Kowalski bên tài chính rà soát số liệu hằng tháng. Minh Trần chịu trách nhiệm về quy định mới, không phải kiểm tra số liệu."}],"words":253},{"id":"r3-02","level":3,"type":"minutes","topic":"Product","title":"Sprint 14 planning","title_vi":"Họp lập kế hoạch Sprint 14","head":[["Meeting","Sprint 14 planning – Mobile team"],["Date","Tuesday, 3 March"],["Attendees","Leah Park (product manager), Duc Nguyen (tech lead), Omar Haddad (QA), Rina Sato (design)"],["Absent","Tom Becker (backend)"]],"paras":[[["Leah opened the meeting by reviewing Sprint 13, in which the team completed 31 of the 38 story points it had planned.","Leah mở đầu cuộc họp bằng việc nhìn lại Sprint 13, trong đó nhóm hoàn thành 31 trên 38 story point đã lên kế hoạch."],["The main issue was the offline sync feature, which was blocked by an API change that the backend team had not finished.","Vấn đề chính là tính năng đồng bộ offline, vốn bị chặn bởi một thay đổi API mà nhóm backend chưa làm xong."],["As a result, the release of version 4.2, originally scheduled for 10 March, will be postponed to 24 March.","Do đó, bản phát hành phiên bản 4.2, ban đầu dự kiến vào ngày 10 tháng 3, sẽ được hoãn sang ngày 24 tháng 3."]],[["Duc explained that the sync logic itself is almost done, but it cannot be tested end to end until the new endpoint is deployed to staging.","Đức giải thích rằng bản thân logic đồng bộ đã gần xong, nhưng chưa thể test end-to-end cho đến khi endpoint mới được deploy lên staging."],["Since Tom was absent, Duc agreed to follow up on the endpoint with him on Wednesday morning and report back in the stand-up meeting.","Vì Tom vắng mặt, Đức nhận sẽ trao đổi tiếp với anh ấy về endpoint vào sáng thứ Tư và báo lại trong buổi họp stand-up."],["Omar raised a concern that two weeks of regression testing would not fit into the new timeline if the endpoint slipped again.","Omar bày tỏ lo ngại rằng hai tuần regression test sẽ không vừa với timeline mới nếu endpoint lại bị trễ."]],[["After some discussion, the team reached a consensus to split the work.","Sau một hồi thảo luận, cả nhóm đã thống nhất chia nhỏ công việc."],["The redesigned settings screen, which does not depend on the backend, will ship in version 4.2 as planned, while offline sync will move to version 4.3 if the endpoint is not ready by 13 March.","Màn hình cài đặt được thiết kế lại, vốn không phụ thuộc vào backend, sẽ ra mắt trong bản 4.2 như kế hoạch, còn đồng bộ offline sẽ chuyển sang bản 4.3 nếu endpoint chưa sẵn sàng trước ngày 13 tháng 3."],["Rina will deliver the final designs for the settings screen by Thursday so that development can start on Friday.","Rina sẽ bàn giao thiết kế cuối cùng của màn hình cài đặt trước thứ Năm để việc phát triển có thể bắt đầu vào thứ Sáu."]],[["Action items: Duc to confirm the endpoint date with Tom by Wednesday; Rina to share final designs by Thursday; Omar to update the test plan by Monday.","Đầu việc cần làm: Đức xác nhận ngày hoàn thành endpoint với Tom trước thứ Tư; Rina chia sẻ thiết kế cuối cùng trước thứ Năm; Omar cập nhật test plan trước thứ Hai."],["Leah will inform the client success team about the new release date and send the minutes to everyone today.","Leah sẽ thông báo ngày phát hành mới cho nhóm client success và gửi biên bản họp cho mọi người trong hôm nay."],["The next planning meeting will be held on 17 March.","Buổi họp lập kế hoạch tiếp theo sẽ diễn ra vào ngày 17 tháng 3."]]],"vocab":[{"w":"be blocked by","f":"blocked by","pos":"phrase","ipa":"","vi":"bị chặn bởi"},{"w":"as a result","f":"as a result","pos":"phrase","ipa":"","vi":"kết quả là"},{"w":"release","f":"release","pos":"v/n","ipa":"/rɪˈliːs/","vi":"phát hành, tung ra; sự phát hành"},{"w":"postpone","f":"postponed","pos":"v","ipa":"/poʊˈspoʊn/","vi":"hoãn lại"},{"w":"deploy","f":"deployed","pos":"v","ipa":"/dɪˈplɔɪ/","vi":"triển khai"},{"w":"absent","f":"absent","pos":"adj","ipa":"/ˈæbsənt/","vi":"vắng mặt"},{"w":"follow up on","f":"follow up on","pos":"phrase","ipa":"","vi":"theo dõi tiếp, hỏi lại về"},{"w":"stand-up meeting","f":"stand-up meeting","pos":"phrase","ipa":"","vi":"họp nhanh hằng ngày (đứng)"},{"w":"raise a concern","f":"raised a concern","pos":"phrase","ipa":"","vi":"nêu mối lo ngại"},{"w":"regression","f":"regression","pos":"n","ipa":"/rɪˈɡrɛʃn/","vi":"sự thoái lùi; kiểm thử hồi quy"},{"w":"reach a consensus","f":"reached a consensus","pos":"phrase","ipa":"","vi":"đạt được đồng thuận"},{"w":"action item","f":"Action items","pos":"phrase","ipa":"","vi":"việc cần làm (sau họp)"}],"questions":[{"q":"Why was the release of version 4.2 delayed?","o":["The settings screen designs were late","QA found too many bugs in Sprint 13","An API change from the backend team was not finished","The tech lead was absent"],"a":2,"vi":"Đoạn 1: tính năng sync bị chặn bởi thay đổi API mà backend chưa xong, \"As a result\" bản 4.2 bị hoãn. Người vắng mặt là Tom (backend), không phải tech lead Đức."},{"q":"What will happen if the endpoint is not ready by 13 March?","o":["Offline sync will be moved to version 4.3","The whole release will be cancelled","Regression testing will be shortened to one week","Tom will join the mobile team"],"a":0,"vi":"Đoạn 3: nếu endpoint chưa sẵn sàng trước 13/3, đồng bộ offline chuyển sang bản 4.3; màn hình cài đặt vẫn ra trong bản 4.2, nên bản phát hành không bị hủy."},{"q":"Who will update the test plan?","o":["Leah","Duc","Rina","Omar"],"a":3,"vi":"Đoạn 4, phần action items: \"Omar to update the test plan by Monday\". Leah gửi biên bản, Đức xác nhận ngày endpoint, Rina gửi thiết kế."},{"q":"The phrase \"reached a consensus\" in paragraph 3, line 1, is closest in meaning to","o":["held a vote","came to a general agreement","asked for more time","made a complaint"],"a":1,"vi":"\"Reach a consensus\" = đạt được sự đồng thuận, tức cả nhóm cùng nhất trí. Không có bỏ phiếu (held a vote) nào được nhắc đến."}],"words":260},{"id":"r3-03","level":3,"type":"email","topic":"IT","title":"Office move: IT checklist","title_vi":"Chuyển văn phòng: danh sách việc cần làm về IT","head":[["From","Huong Le <huong.le@kestrelsoft.io>"],["To","All Hanoi office staff"],["Subject","Office relocation: IT checklist and key dates"]],"paras":[[["Hi everyone,","Chào mọi người,"]],[["As you know, our Hanoi office will relocate from Linh Tower to the new Riverside building on the weekend of 18–19 April.","Như mọi người đã biết, văn phòng Hà Nội của chúng ta sẽ chuyển từ tòa Linh Tower sang tòa nhà Riverside mới vào cuối tuần 18–19 tháng 4."],["To keep disruption to a minimum, IT needs everyone's help with a few tasks before and after the move.","Để hạn chế gián đoạn ở mức thấp nhất, bộ phận IT cần mọi người hỗ trợ một số việc trước và sau khi chuyển."],["Please read this email carefully, as some of the deadlines are earlier than the move itself.","Vui lòng đọc kỹ email này, vì một số hạn chót còn sớm hơn cả ngày chuyển văn phòng."]],[["By Wednesday, 15 April, please back up any files stored only on your desktop computer to the company drive, because desktops will be wiped and reinstalled before they are moved.","Trước thứ Tư, ngày 15 tháng 4, vui lòng sao lưu mọi file chỉ lưu trên máy tính để bàn lên ổ đĩa công ty, vì các máy để bàn sẽ bị xóa sạch và cài đặt lại trước khi chuyển đi."],["Laptops will not be wiped, but you must take them home on Friday, 17 April, and keep them with you over the weekend.","Laptop sẽ không bị xóa dữ liệu, nhưng bạn phải mang về nhà vào thứ Sáu, ngày 17 tháng 4, và giữ bên mình trong suốt cuối tuần."],["Monitors, docking stations and keyboards should be packed in the labelled boxes that Facilities will deliver on Thursday.","Màn hình, dock và bàn phím cần được đóng vào các thùng có dán nhãn mà bộ phận Hành chính sẽ giao vào thứ Năm."]],[["On Saturday, the internet connection and the VPN will be unavailable from 8 a.m. to 6 p.m. while the network is switched to the new building.","Vào thứ Bảy, kết nối internet và VPN sẽ không dùng được từ 8 giờ sáng đến 6 giờ chiều trong lúc hệ thống mạng được chuyển sang tòa nhà mới."],["If you are on call that day, please use your mobile hotspot and contact the IT helpdesk if you run into a problem accessing production systems.","Nếu bạn trực on-call hôm đó, hãy dùng hotspot điện thoại và liên hệ helpdesk IT nếu gặp sự cố khi truy cập hệ thống production."]],[["When you arrive on Monday, 20 April, you will need your new access card, which can be collected from reception on the ground floor.","Khi đến văn phòng vào thứ Hai, ngày 20 tháng 4, bạn sẽ cần thẻ ra vào mới, có thể nhận tại quầy lễ tân ở tầng trệt."],["Old cards will stop working at midnight on Sunday.","Thẻ cũ sẽ ngừng hoạt động lúc nửa đêm Chủ nhật."],["Desk numbers and the floor plan are attached.","Số bàn và sơ đồ mặt bằng được đính kèm theo email này."],["Let me know if you have any questions, and thank you in advance for your help.","Nếu có câu hỏi gì, mọi người cứ cho tôi biết nhé, và cảm ơn trước sự hỗ trợ của mọi người."]],[["Best regards,","Trân trọng,"],["Huong Le, IT Operations","Lê Hương, bộ phận Vận hành IT"]]],"vocab":[{"w":"relocate","f":"relocate","pos":"v","ipa":"/riːˈloʊkeɪt/","vi":"di dời; chuyển địa điểm làm việc"},{"w":"deadline","f":"deadlines","pos":"n","ipa":"/ˈdɛˌdlaɪn/","vi":"hạn chót"},{"w":"back up","f":"back up","pos":"phrase","ipa":"","vi":"sao lưu"},{"w":"keyboard","f":"keyboards","pos":"n","ipa":"/ˈkiˌbɔrd/","vi":"bàn phím"},{"w":"internet","f":"internet","pos":"n","ipa":"/ˈɪntərnet/","vi":"mạng internet"},{"w":"run into a problem","f":"run into a problem","pos":"phrase","ipa":"","vi":"gặp vấn đề"},{"w":"access","f":"access","pos":"n/v","ipa":"/ˈæksɛs/","vi":"quyền truy cập, lối vào; tiếp cận"},{"w":"reception","f":"reception","pos":"n","ipa":"/rɪˈsɛpʃn/","vi":"quầy lễ tân; tiệc chiêu đãi"},{"w":"let me know if you have any questions","f":"let me know if you have any questions","pos":"phrase","ipa":"","vi":"có câu hỏi gì cứ báo tôi"},{"w":"in advance","f":"in advance","pos":"phrase","ipa":"","vi":"trước, sẵn"}],"questions":[{"q":"What is the deadline for backing up desktop files?","o":["15 April","17 April","18 April","20 April"],"a":0,"vi":"Đoạn 3: \"By Wednesday, 15 April, please back up...\". 17/4 là ngày mang laptop về, 18/4 là ngày chuyển, 20/4 là ngày đi làm ở văn phòng mới."},{"q":"What should staff do with their laptops?","o":["Leave them on their desks for IT","Pack them in the labelled boxes","Take them home before the move weekend","Bring them to reception on Monday"],"a":2,"vi":"Đoạn 3: laptop phải mang về nhà vào thứ Sáu 17/4. Thùng có nhãn dành cho màn hình, dock và bàn phím; lễ tân là nơi nhận thẻ ra vào."},{"q":"What is suggested for staff who are on call on Saturday?","o":["Working from the new building","Using a mobile hotspot","Connecting to the VPN after 8 a.m.","Collecting a new access card early"],"a":1,"vi":"Đoạn 4: người trực on-call nên dùng hotspot điện thoại vì internet và VPN ngừng từ 8 giờ sáng đến 6 giờ chiều, nên C sai."},{"q":"What is NOT mentioned in the email?","o":["When old access cards will stop working","Where to collect new access cards","When Facilities will deliver boxes","Who will move the desktop computers"],"a":3,"vi":"Email có nêu thẻ cũ hết hiệu lực lúc nửa đêm Chủ nhật, nhận thẻ mới ở lễ tân, thùng giao vào thứ Năm; nhưng không nói ai sẽ vận chuyển máy để bàn."}],"words":248},{"id":"r3-04","level":3,"type":"article","topic":"Data","title":"From nightly batch to streaming","title_vi":"Từ batch hằng đêm sang streaming","head":[],"paras":[[["For the past three years, the analytics team at Brightwell Logistics has relied on a nightly batch job to load sales and shipment data into the company's data warehouse.","Suốt ba năm qua, nhóm phân tích tại Brightwell Logistics dựa vào một job batch chạy hằng đêm để nạp dữ liệu bán hàng và vận chuyển vào data warehouse của công ty."],["The job starts at 1 a.m. and usually finishes by 6 a.m., which means managers see yesterday's numbers, not today's.","Job bắt đầu lúc 1 giờ sáng và thường xong trước 6 giờ sáng, nghĩa là các quản lý chỉ thấy số liệu của hôm qua chứ không phải hôm nay."],["When the job fails, as it did eleven times last year, dashboards remain out of date until an engineer fixes it, sometimes for an entire morning.","Khi job lỗi, như đã xảy ra mười một lần năm ngoái, các dashboard vẫn chứa dữ liệu cũ cho đến khi kỹ sư sửa xong, có khi mất cả buổi sáng."]],[["This quarter, the data engineering team, led by Priya Raman, began replacing the batch job with a streaming pipeline that updates the warehouse every five minutes.","Quý này, nhóm data engineering do Priya Raman dẫn dắt đã bắt đầu thay job batch bằng một pipeline streaming cập nhật warehouse năm phút một lần."],["The first phase, which covers shipment data only, went live on 2 September after a four-week trial with the warehouse operations team.","Giai đoạn đầu, chỉ bao gồm dữ liệu vận chuyển, đã chạy chính thức vào ngày 2 tháng 9 sau bốn tuần thử nghiệm cùng nhóm vận hành kho."],["During the trial, the average delay between an event and its appearance in dashboards dropped from about 14 hours to under 6 minutes.","Trong thời gian thử nghiệm, độ trễ trung bình từ lúc một sự kiện xảy ra đến khi nó hiện trên dashboard đã giảm từ khoảng 14 giờ xuống dưới 6 phút."]],[["The migration has not been free of problems.","Quá trình chuyển đổi không phải không có trục trặc."],["In the second week, duplicate records appeared when a message queue was restarted, and some reports showed shipment volumes 3% higher than the actual numbers.","Ở tuần thứ hai, bản ghi trùng lặp xuất hiện khi một message queue được khởi động lại, và một số báo cáo cho thấy khối lượng hàng vận chuyển cao hơn 3% so với số thực tế."],["The team fixed the issue by adding a check that removes repeated events before they reach the warehouse.","Nhóm đã khắc phục bằng cách thêm một bước kiểm tra để loại bỏ các sự kiện lặp trước khi chúng vào đến warehouse."]],[["The second phase, covering sales orders, is planned for November, but Priya says it depends on the finance team approving the new data definitions.","Giai đoạn hai, bao gồm đơn hàng bán, được lên kế hoạch vào tháng 11, nhưng Priya cho biết điều đó còn phụ thuộc vào việc nhóm tài chính phê duyệt các định nghĩa dữ liệu mới."],["Until then, sales dashboards will continue to use the nightly batch job.","Cho đến lúc đó, các dashboard bán hàng vẫn sẽ dùng job batch hằng đêm."],["The old job will be fully switched off in January, as long as both phases run without major issues for a month.","Job cũ sẽ bị tắt hoàn toàn vào tháng 1, miễn là cả hai giai đoạn chạy ổn định không có sự cố lớn trong một tháng."],["Teams that build their own reports on warehouse tables should contact the data engineering channel before the end of October to check whether their queries need to change.","Các nhóm tự xây báo cáo trên các bảng của warehouse nên liên hệ kênh data engineering trước cuối tháng 10 để kiểm tra xem query của mình có cần thay đổi không."]]],"vocab":[{"w":"rely on","f":"relied on","pos":"phrase","ipa":"","vi":"dựa vào"},{"w":"shipment","f":"shipment","pos":"n","ipa":"/ˈʃɪpmənt/","vi":"lô hàng; sự vận chuyển"},{"w":"warehouse","f":"warehouse","pos":"n","ipa":"/ˈwɛrˌhaʊs/","vi":"kho hàng"},{"w":"out of date","f":"out of date","pos":"phrase","ipa":"","vi":"lỗi thời, cũ"},{"w":"pipeline","f":"pipeline","pos":"n","ipa":"/ˈpaɪplaɪn/","vi":"đường ống; quy trình xử lý"},{"w":"average","f":"average","pos":"adj/n","ipa":"/ˈævərɪdʒ/","vi":"trung bình"},{"w":"migration","f":"migration","pos":"n","ipa":"/maɪˈɡreɪ.ʃən/","vi":"sự di cư; quá trình chuyển đổi dữ liệu"},{"w":"duplicate","f":"duplicate","pos":"n/v/adj","ipa":"/ˈduːplɪkeɪt/","vi":"bản sao; sao chép"},{"w":"volume","f":"volumes","pos":"n","ipa":"/ˈvɑljum/","vi":"khối lượng, âm lượng"},{"w":"it depends on","f":"it depends on","pos":"phrase","ipa":"","vi":"còn tuỳ vào"},{"w":"until then","f":"until then","pos":"phrase","ipa":"","vi":"cho đến lúc đó"},{"w":"as long as","f":"as long as","pos":"phrase","ipa":"","vi":"miễn là"}],"questions":[{"q":"How often does the new pipeline update the warehouse?","o":["Every night at 1 a.m.","Every hour","Every six minutes","Every five minutes"],"a":3,"vi":"Đoạn 2: pipeline streaming \"updates the warehouse every five minutes\". 1 giờ sáng là giờ chạy job batch cũ; 6 phút là độ trễ trung bình trong thử nghiệm."},{"q":"What problem occurred during the migration?","o":["The trial was extended by four weeks","Some records were counted twice","The finance team rejected the data definitions","Dashboards stopped updating for a whole morning"],"a":1,"vi":"Đoạn 3: bản ghi trùng lặp (duplicate records) làm số liệu cao hơn 3%. Dashboard đứng cả buổi sáng là vấn đề của job batch cũ; nhóm tài chính chưa từ chối gì cả."},{"q":"What does the second phase depend on?","o":["The end of the trial with warehouse operations","The switch-off of the batch job","Approval of new data definitions by finance","Teams changing their queries"],"a":2,"vi":"Đoạn 4: \"it depends on the finance team approving the new data definitions\". Việc tắt job batch diễn ra sau, phụ thuộc vào cả hai giai đoạn."},{"q":"What can be inferred about teams that build their own reports?","o":["They may need to update their queries","They must stop using the warehouse in October","They will lose access to sales data in November","They caused the duplicate records"],"a":0,"vi":"Câu cuối: họ nên liên hệ để kiểm tra \"whether their queries need to change\" → có thể phải sửa query. Không có thông tin họ phải ngừng dùng warehouse."}],"words":285},{"id":"r3-05","level":3,"type":"email","topic":"Finance","title":"New travel expense rules","title_vi":"Quy định mới về chi phí công tác","head":[["From","Grace Oduya <grace.oduya@lumencore.ai>"],["To","Engineering department"],["Subject","Changes to travel expense claims from 1 June"]],"paras":[[["Dear colleagues,","Kính gửi các anh chị,"]],[["Following the internal audit in March, we are updating the travel expense policy, and the changes will apply to all trips that start on or after 1 June.","Sau đợt kiểm toán nội bộ hồi tháng 3, chúng tôi đang cập nhật chính sách chi phí công tác, và các thay đổi sẽ áp dụng cho mọi chuyến đi bắt đầu từ ngày 1 tháng 6 trở đi."],["The audit found that nearly a quarter of claims last year were sent in more than 60 days after the trip, which made it difficult to close our monthly accounts on time.","Đợt kiểm toán phát hiện gần một phần tư số đề nghị thanh toán năm ngoái được nộp sau chuyến đi hơn 60 ngày, khiến việc khóa sổ hằng tháng đúng hạn trở nên khó khăn."]],[["The most important change concerns the deadline: claims must now be sent in within 30 days of your return, instead of 90.","Thay đổi quan trọng nhất liên quan đến hạn chót: đề nghị thanh toán giờ phải được nộp trong vòng 30 ngày sau khi bạn trở về, thay vì 90 ngày."],["Claims received after this period will need written justification from your department head and may not be reimbursed.","Các đề nghị nhận được sau thời hạn này sẽ cần giải trình bằng văn bản từ trưởng bộ phận và có thể không được hoàn tiền."],["In addition, every expense above $25 must be supported by an itemised receipt; card statements alone will no longer be accepted.","Ngoài ra, mọi khoản chi trên 25 đô la phải có hóa đơn ghi chi tiết từng mục; chỉ có sao kê thẻ sẽ không còn được chấp nhận."]],[["The daily meal allowance for domestic trips will rise from $40 to $45, while the allowance for international trips remains at $60.","Phụ cấp ăn uống hằng ngày cho chuyến công tác trong nước sẽ tăng từ 40 lên 45 đô la, còn phụ cấp cho chuyến đi nước ngoài vẫn giữ ở mức 60 đô la."],["Hotel bookings must still be made through our travel portal, but you may now book economy-plus fares on flights longer than six hours without asking in advance.","Việc đặt khách sạn vẫn phải thực hiện qua cổng đặt chỗ công tác của công ty, nhưng giờ đây bạn có thể đặt vé hạng phổ thông đặc biệt cho chuyến bay dài hơn sáu tiếng mà không cần xin phép trước."]],[["To help everyone get used to the new process, the finance team will run two 30-minute online sessions on 20 and 27 May.","Để giúp mọi người làm quen với quy trình mới, nhóm tài chính sẽ tổ chức hai buổi hướng dẫn online, mỗi buổi 30 phút, vào ngày 20 và 27 tháng 5."],["Attendance is not mandatory, but we strongly recommend it if you travel regularly.","Việc tham dự không bắt buộc, nhưng chúng tôi rất khuyến khích nếu bạn thường xuyên đi công tác."],["If you have claims from earlier trips that are still outstanding, please send them in by 31 May so that they can be processed under the current rules.","Nếu bạn còn đề nghị thanh toán từ các chuyến đi trước chưa nộp, vui lòng nộp trước ngày 31 tháng 5 để được xử lý theo quy định hiện hành."]],[["Kind regards,","Trân trọng,"],["Grace Oduya, Finance Manager","Grace Oduya, Trưởng phòng Tài chính"]]],"vocab":[{"w":"audit","f":"audit","pos":"n/v","ipa":"/ˈɔːdɪt/","vi":"kiểm toán"},{"w":"expense","f":"expense","pos":"n","ipa":"/ɪkˈspens/","vi":"chi phí"},{"w":"policy","f":"policy","pos":"n","ipa":"/ˈpɑːləsi/","vi":"chính sách"},{"w":"justification","f":"justification","pos":"n","ipa":"/ˌdʒʌs.tə.fɪˈkeɪ.ʃən/","vi":"sự biện minh, lý do chính đáng"},{"w":"reimburse","f":"reimbursed","pos":"v","ipa":"/ˌriɪmˈbɜrs/","vi":"hoàn trả chi phí"},{"w":"in addition","f":"in addition","pos":"phrase","ipa":"","vi":"ngoài ra"},{"w":"receipt","f":"receipt","pos":"n","ipa":"/rɪˈsit/","vi":"biên lai; hóa đơn"},{"w":"allowance","f":"allowance","pos":"n","ipa":"/əˈlaʊəns/","vi":"tiền phụ cấp; hạn mức"},{"w":"fare","f":"fares","pos":"n","ipa":"/fɛr/","vi":"giá vé (tàu, xe)"},{"w":"get used to","f":"get used to","pos":"phrase","ipa":"","vi":"quen với"},{"w":"mandatory","f":"mandatory","pos":"adj","ipa":"/ˈmændəˌtɔri/","vi":"bắt buộc"},{"w":"outstanding","f":"outstanding","pos":"adj","ipa":"/aʊtˈstændɪŋ/","vi":"xuất sắc; chưa thanh toán"}],"questions":[{"q":"What did the internal audit find?","o":["Many claims had no receipts","Many claims were sent in late","Hotel costs were too high","The meal allowance was too low"],"a":1,"vi":"Đoạn 2: gần một phần tư số đề nghị được nộp sau chuyến đi hơn 60 ngày, tức nộp muộn. Quy định về hóa đơn là thay đổi mới, không phải kết quả kiểm toán."},{"q":"What is the new deadline for sending in a claim?","o":["Within 30 days of returning","Within 60 days of returning","Within 90 days of returning","By the end of each month"],"a":0,"vi":"Đoạn 3: \"within 30 days of your return, instead of 90\". 90 ngày là quy định cũ; 60 ngày là con số trong kết quả kiểm toán."},{"q":"What is true about the meal allowance?","o":["It will rise to $60 for international trips","It will fall for domestic trips","It will stay the same for all trips","It will increase by $5 for domestic trips"],"a":3,"vi":"Đoạn 4: phụ cấp trong nước tăng từ 40 lên 45 đô la (+5); phụ cấp nước ngoài vẫn giữ ở 60 đô la chứ không phải tăng lên 60."},{"q":"What should staff with older unpaid claims do?","o":["Attend the session on 27 May","Ask their department head for justification","Send them in by 31 May","Book through the travel portal"],"a":2,"vi":"Câu cuối đoạn 5: các đề nghị còn tồn đọng (outstanding) nên được nộp trước ngày 31/5 để xử lý theo quy định hiện hành."}],"words":242},{"id":"r3-06","level":3,"type":"report","topic":"Data","title":"Ticket routing model evaluation","title_vi":"Đánh giá model phân loại ticket","head":[],"paras":[[["This report compares two models for automatically routing customer support tickets at Tellora Cloud: the current production model (v2) and a new fine-tuned model (v3).","Báo cáo này so sánh hai model tự động phân loại ticket hỗ trợ khách hàng tại Tellora Cloud: model đang chạy production (v2) và một model fine-tune mới (v3)."],["Both models were tested on a held-out set of 4,200 tickets collected between January and March and labelled by the support team.","Cả hai model được kiểm thử trên một tập held-out gồm 4.200 ticket thu thập từ tháng 1 đến tháng 3 và được nhóm hỗ trợ gán nhãn."]],[["Overall, v3 routed 91.4% of tickets to the correct queue, compared with 86.7% for v2.","Nhìn chung, v3 chuyển đúng hàng đợi 91,4% số ticket, so với 86,7% của v2."],["The largest improvement was in the billing category, where accuracy rose from 78% to 90%, mainly because v3 was trained on more examples of refund requests.","Mức cải thiện lớn nhất nằm ở nhóm thanh toán, nơi độ chính xác tăng từ 78% lên 90%, chủ yếu vì v3 được train trên nhiều ví dụ yêu cầu hoàn tiền hơn."],["However, v3 performed slightly worse on tickets written in languages other than English, scoring 82% against 84% for v2.","Tuy nhiên, v3 làm kém hơn một chút với các ticket viết bằng ngôn ngữ khác tiếng Anh, đạt 82% so với 84% của v2."],["Average response time also increased from 120 to 190 milliseconds per ticket, which is still well below the 300-millisecond limit agreed with the support platform team.","Thời gian phản hồi trung bình cũng tăng từ 120 lên 190 mili giây mỗi ticket, nhưng vẫn thấp hơn nhiều so với giới hạn 300 mili giây đã thống nhất với nhóm support platform."]],[["We also reviewed 200 tickets that v3 misrouted.","Chúng tôi cũng xem xét 200 ticket mà v3 phân loại sai."],["About 40% of these were vague messages, such as \"it doesn't work\", which even human agents found hard to classify.","Khoảng 40% trong số đó là các tin nhắn mơ hồ, kiểu như \"nó không chạy\", mà ngay cả nhân viên hỗ trợ cũng thấy khó phân loại."],["A further 25% came from customers who raised two separate problems in one ticket.","25% khác đến từ những khách hàng nêu hai vấn đề riêng biệt trong cùng một ticket."]],[["We recommend rolling out v3 step by step rather than replacing v2 at once.","Chúng tôi đề xuất triển khai v3 từng bước thay vì thay thế v2 ngay lập tức."],["From 6 May, v3 will handle 20% of English tickets, and the share will increase to 100% by 3 June if the misrouting rate stays below 10%.","Từ ngày 6 tháng 5, v3 sẽ xử lý 20% ticket tiếng Anh, và tỷ lệ này sẽ tăng lên 100% trước ngày 3 tháng 6 nếu tỷ lệ phân loại sai duy trì dưới 10%."],["Non-English tickets will continue to go to v2 until more training data is collected.","Ticket không phải tiếng Anh sẽ tiếp tục được chuyển cho v2 cho đến khi thu thập thêm dữ liệu train."],["Jae-won Kim will monitor the results weekly and share them with the support managers, and the final decision will be made at the review meeting on 4 June.","Jae-won Kim sẽ theo dõi kết quả hằng tuần và chia sẻ với các quản lý bộ phận hỗ trợ, còn quyết định cuối cùng sẽ được đưa ra tại cuộc họp đánh giá ngày 4 tháng 6."]]],"vocab":[{"w":"customer","f":"customer","pos":"n","ipa":"/ˈkʌstəmər/","vi":"khách hàng"},{"w":"overall","f":"overall","pos":"adj/adv","ipa":"/ˌoʊvərˈɔːl/","vi":"tổng thể; toàn bộ"},{"w":"improvement","f":"improvement","pos":"n","ipa":"/ɪmˈpruvmənt/","vi":"sự cải tiến, sự cải thiện"},{"w":"accuracy","f":"accuracy","pos":"n","ipa":"/ˈækjərəsi/","vi":"độ chính xác"},{"w":"refund","f":"refund","pos":"n/v","ipa":"/ˈriˌfʌnd/","vi":"hoàn tiền; sự hoàn tiền"},{"w":"response","f":"response","pos":"n","ipa":"/rɪˈspɑːns/","vi":"phản hồi, câu trả lời"},{"w":"limit","f":"limit","pos":"n/v","ipa":"/ˈlɪmɪt/","vi":"giới hạn"},{"w":"recommend","f":"recommend","pos":"v","ipa":"/ˌrekəˈmend/","vi":"giới thiệu, đề xuất"},{"w":"roll out","f":"rolling out","pos":"phrase","ipa":"","vi":"triển khai dần"},{"w":"rather than","f":"rather than","pos":"phrase","ipa":"","vi":"hơn là, thay vì"},{"w":"share","f":"share","pos":"v/n","ipa":"/ʃɛr/","vi":"chia sẻ, dùng chung; cổ phần"},{"w":"monitor","f":"monitor","pos":"n/v","ipa":"/ˈmɑnətər/","vi":"màn hình; giám sát, theo dõi"}],"questions":[{"q":"In which category did v3 improve the most?","o":["Non-English tickets","Vague messages","Billing","Tickets with two problems"],"a":2,"vi":"Đoạn 2: \"The largest improvement was in the billing category\" (78% → 90%). Với ticket không phải tiếng Anh, v3 còn kém hơn v2."},{"q":"What is true about v3's response time?","o":["It is faster than v2","It is above the agreed limit","It is the same as v2","It is slower than v2 but within the limit"],"a":3,"vi":"Đoạn 2: thời gian phản hồi tăng từ 120 lên 190 ms (chậm hơn v2) nhưng vẫn dưới giới hạn 300 ms."},{"q":"What condition must be met for v3 to handle all English tickets by 3 June?","o":["The misrouting rate must stay below 10%","Accuracy must reach 95%","More non-English data must be collected","Support managers must approve the results"],"a":0,"vi":"Đoạn 4: tăng lên 100% \"if the misrouting rate stays below 10%\". Việc thu thập thêm dữ liệu chỉ liên quan đến ticket không phải tiếng Anh."},{"q":"The word \"vague\" in paragraph 3, line 2, is closest in meaning to","o":["rude","unclear","short","urgent"],"a":1,"vi":"\"Vague\" = mơ hồ, không rõ ràng; ví dụ \"it doesn't work\" không nói rõ cái gì hỏng nên khó phân loại."}],"words":261},{"id":"r3-07","level":3,"type":"minutes","topic":"IT","title":"Login outage post-mortem","title_vi":"Họp rút kinh nghiệm sự cố đăng nhập","head":[["Meeting","Post-incident review: login outage on 12 August"],["Date","Thursday, 14 August"],["Attendees","Karim Aziz (SRE lead, chair), Mai Pham (backend), Lucas Ferreira (security), Nadia Brooks (customer support)"]],"paras":[[["Karim summarised the incident: from 09:40 to 11:05 on Tuesday, about 30% of users could not log in to the Fennix web app, while the mobile app was not affected.","Karim tóm tắt sự cố: từ 9:40 đến 11:05 sáng thứ Ba, khoảng 30% người dùng không đăng nhập được vào web app Fennix, trong khi app mobile không bị ảnh hưởng."],["The outage lasted 85 minutes and generated 640 support tickets, the highest number in a single day this year.","Sự cố kéo dài 85 phút và tạo ra 640 ticket hỗ trợ, con số cao nhất trong một ngày tính từ đầu năm."]],[["Mai explained that the root cause was an expired TLS certificate on one of the three authentication servers.","Mai giải thích rằng nguyên nhân gốc rễ là một chứng chỉ TLS đã hết hạn trên một trong ba server xác thực."],["The certificate should have been renewed automatically, but the renewal script had been failing silently since a configuration change in June.","Lẽ ra chứng chỉ phải được gia hạn tự động, nhưng script gia hạn đã âm thầm bị lỗi kể từ một lần thay đổi cấu hình hồi tháng 6."],["Because the load balancer still sent traffic to the broken server, roughly one in three login attempts failed.","Vì load balancer vẫn chuyển traffic tới server bị lỗi, cứ khoảng ba lượt đăng nhập thì có một lượt thất bại."]],[["The team agreed that detection was too slow: the first alert came from customer support, not from monitoring, about 25 minutes after the problem began.","Cả nhóm thống nhất rằng việc phát hiện quá chậm: cảnh báo đầu tiên đến từ bộ phận hỗ trợ khách hàng chứ không phải từ hệ thống monitoring, khoảng 25 phút sau khi sự cố bắt đầu."],["Lucas pointed out that certificates on other internal services may have the same issue and proposed an audit of all certificates by the end of the month.","Lucas chỉ ra rằng chứng chỉ trên các dịch vụ nội bộ khác có thể gặp vấn đề tương tự và đề xuất kiểm tra toàn bộ chứng chỉ trước cuối tháng."],["Nadia asked for a status page update within 15 minutes of any future incident, since customers were left without information for almost an hour.","Nadia đề nghị cập nhật trang trạng thái trong vòng 15 phút mỗi khi có sự cố trong tương lai, vì khách hàng đã không nhận được thông tin gì trong gần một giờ."]],[["Action items: Mai to fix the renewal script and add an alert for failures by 21 August; Lucas to complete the certificate audit by 31 August; Karim to add a health check so that the load balancer removes failing servers automatically; Nadia to prepare a status page template.","Đầu việc cần làm: Mai sửa script gia hạn và thêm cảnh báo khi lỗi trước ngày 21 tháng 8; Lucas hoàn thành đợt kiểm tra chứng chỉ trước ngày 31 tháng 8; Karim thêm health check để load balancer tự động loại các server lỗi; Nadia chuẩn bị mẫu thông báo cho trang trạng thái."],["Karim will share the written post-mortem with the engineering department by Monday.","Karim sẽ gửi bản post-mortem cho phòng kỹ thuật trước thứ Hai."]]],"vocab":[{"w":"affect","f":"affected","pos":"v","ipa":"/əˈfekt/","vi":"ảnh hưởng"},{"w":"outage","f":"outage","pos":"n","ipa":"/ˈaʊtɪdʒ/","vi":"sự gián đoạn dịch vụ, cúp điện"},{"w":"the root cause","f":"the root cause","pos":"phrase","ipa":"","vi":"nguyên nhân gốc"},{"w":"certificate","f":"certificate","pos":"n","ipa":"/sərˈtɪfɪkət/","vi":"chứng chỉ; giấy chứng nhận"},{"w":"should have","f":"should have","pos":"phrase","ipa":"/ˈʃʊdə/","vi":"lẽ ra nên"},{"w":"renew","f":"renewed","pos":"v","ipa":"/rɪˈnu/","vi":"gia hạn, làm mới"},{"w":"renewal","f":"renewal","pos":"n","ipa":"/rɪˈnuːəl/","vi":"sự gia hạn; sự đổi mới"},{"w":"detection","f":"detection","pos":"n","ipa":"/dɪˈtɛkʃən/","vi":"sự phát hiện, dò tìm"},{"w":"point out","f":"pointed out","pos":"phrase","ipa":"","vi":"chỉ ra"},{"w":"propose","f":"proposed","pos":"v","ipa":"/prəˈpoʊz/","vi":"đề xuất, đề nghị"},{"w":"status","f":"status","pos":"n","ipa":"/ˈsteɪtəs/","vi":"trạng thái, địa vị"},{"w":"template","f":"template","pos":"n","ipa":"/ˈtɛmplɪt/","vi":"mẫu, bản mẫu có sẵn"}],"questions":[{"q":"What caused the outage?","o":["An expired certificate on an authentication server","A failure in the mobile app","A security attack on the load balancer","A shortage of support staff"],"a":0,"vi":"Đoạn 2: \"the root cause was an expired TLS certificate\" trên một server xác thực. App mobile không bị ảnh hưởng; không có tấn công nào được nhắc đến."},{"q":"How did the team first learn about the problem?","o":["Through an automatic monitoring alert","Through reports from customer support","Through the status page","Through a message from the security team"],"a":1,"vi":"Đoạn 3: \"the first alert came from customer support, not from monitoring\". Đây chính là lý do nhóm cho rằng việc phát hiện quá chậm."},{"q":"Who will check the certificates on other services?","o":["Karim","Mai","Lucas","Nadia"],"a":2,"vi":"Lucas đề xuất và được giao hoàn thành \"the certificate audit by 31 August\". Mai chỉ sửa script gia hạn."},{"q":"What can be inferred about the renewal script?","o":["It was written in August","It was removed after the incident","It caused the configuration change in June","It had not worked for about two months before the outage"],"a":3,"vi":"Đoạn 2: script lỗi âm thầm \"since a configuration change in June\", còn sự cố xảy ra ngày 12/8 → đã hỏng khoảng hai tháng. Thay đổi cấu hình gây lỗi cho script, chứ không phải ngược lại."}],"words":244},{"id":"r3-08","level":3,"type":"email","topic":"Product","title":"Extra features for Phase 2","title_vi":"Tính năng bổ sung cho Giai đoạn 2","head":[["From","Daniel Moreau <daniel.moreau@quillbyte.com>"],["To","Ana Ruiz <ana.ruiz@harborlane.co>"],["Cc","Linh Vo (engineering lead)"],["Subject","Re: Additional reporting features for Phase 2"]],"paras":[[["Dear Ana,","Chào chị Ana,"]],[["Thank you for sending over the list of reporting features your team would like to add to Phase 2 of the inventory platform.","Cảm ơn chị đã gửi danh sách các tính năng báo cáo mà nhóm chị muốn bổ sung vào Giai đoạn 2 của nền tảng quản lý hàng tồn kho."],["Linh and I went through the requests with our engineers on Monday, and I would like to explain what we can deliver and when.","Linh và tôi đã cùng các kỹ sư rà soát các yêu cầu vào thứ Hai, và tôi muốn giải thích những gì chúng tôi có thể bàn giao cũng như thời điểm bàn giao."]],[["Of the five items on your list, three can be included without changing the current deadline of 30 September: the export to Excel, the weekly summary email, and the extra filters on the stock report.","Trong năm hạng mục chị đưa ra, có ba hạng mục có thể đưa vào mà không thay đổi hạn chót hiện tại là 30 tháng 9: xuất ra Excel, email tóm tắt hằng tuần và các bộ lọc bổ sung cho báo cáo tồn kho."],["The other two, a forecasting dashboard and integration with your accounting software, are out of scope for the original agreement.","Hai hạng mục còn lại, gồm dashboard dự báo và tích hợp với phần mềm kế toán của bên chị, nằm ngoài phạm vi của thỏa thuận ban đầu."],["Our rough estimate is that they would require an additional six weeks of work and cost around $18,500.","Theo ước tính sơ bộ của chúng tôi, hai hạng mục này cần thêm sáu tuần làm việc và chi phí khoảng 18.500 đô la."]],[["We can offer two options.","Chúng tôi có thể đưa ra hai phương án."],["First, we could add both items to Phase 2, which would move the delivery date to mid-November.","Thứ nhất, chúng tôi có thể thêm cả hai hạng mục vào Giai đoạn 2, khi đó ngày bàn giao sẽ lùi đến giữa tháng 11."],["Second, we could keep the September deadline and deliver the two items as a separate Phase 3, starting in October.","Thứ hai, chúng tôi có thể giữ hạn chót tháng 9 và bàn giao hai hạng mục đó trong một Giai đoạn 3 riêng, bắt đầu từ tháng 10."],["We recommend the second option, because your warehouse teams have said they need the current features before the busy season begins.","Chúng tôi đề xuất phương án thứ hai, vì các nhóm kho của bên chị đã cho biết họ cần các tính năng hiện tại trước khi mùa cao điểm bắt đầu."]],[["Could you let me know which option you prefer by Friday, 8 August?","Chị có thể cho tôi biết chị chọn phương án nào trước thứ Sáu, ngày 8 tháng 8 được không?"],["Once we have your decision, I will send a revised quotation and an updated timeline.","Khi nhận được quyết định của chị, tôi sẽ gửi báo giá điều chỉnh và timeline cập nhật."],["If it would help, Linh and I are happy to jump on a call early next week to go over the details.","Nếu cần, Linh và tôi sẵn sàng gọi nhanh vào đầu tuần sau để cùng xem qua chi tiết."]],[["Best regards,","Trân trọng,"],["Daniel Moreau, Account Manager, Quillbyte","Daniel Moreau, Quản lý khách hàng, Quillbyte"]]],"vocab":[{"w":"inventory","f":"inventory","pos":"n","ipa":"/ˈɪnvəntɔːri/","vi":"hàng tồn kho, kiểm kê"},{"w":"go through","f":"went through","pos":"phrase","ipa":"","vi":"đi qua lần lượt, trình bày từng phần"},{"w":"deadline","f":"deadline","pos":"n","ipa":"/ˈdɛˌdlaɪn/","vi":"hạn chót"},{"w":"integration","f":"integration","pos":"n","ipa":"/ˌɪntɪˈɡreɪʃn/","vi":"sự tích hợp, hội nhập"},{"w":"out of scope","f":"out of scope","pos":"phrase","ipa":"","vi":"ngoài phạm vi"},{"w":"rough estimate","f":"rough estimate","pos":"phrase","ipa":"","vi":"ước lượng sơ bộ"},{"w":"require","f":"require","pos":"v","ipa":"/rɪˈkwaɪər/","vi":"yêu cầu, đòi hỏi"},{"w":"option","f":"options","pos":"n","ipa":"/ˈɑːp.ʃən/","vi":"tùy chọn; sự lựa chọn"},{"w":"quotation","f":"quotation","pos":"n","ipa":"/kwoʊˈteɪʃən/","vi":"bảng báo giá; đoạn trích"},{"w":"timeline","f":"timeline","pos":"n","ipa":"/ˈtaɪmˌlaɪn/","vi":"lịch trình thời gian, tiến độ"},{"w":"jump on a call","f":"jump on a call","pos":"phrase","ipa":"","vi":"gọi nhanh"},{"w":"early next week","f":"early next week","pos":"phrase","ipa":"","vi":"đầu tuần sau"}],"questions":[{"q":"How many of the client's requests can be delivered by 30 September?","o":["One","Five","Two","Three"],"a":3,"vi":"Đoạn 3: \"Of the five items on your list, three can be included\" mà không đổi hạn 30/9. Hai hạng mục còn lại nằm ngoài phạm vi."},{"q":"What is the estimated cost of the two extra items?","o":["$6,000","$8,500","$18,500","$30,000"],"a":2,"vi":"Đoạn 3: ước tính sơ bộ \"cost around $18,500\" và cần thêm sáu tuần (con số 6 là số tuần, không phải tiền)."},{"q":"Why does Daniel recommend the second option?","o":["It is cheaper than the first option","The client's warehouse teams need the current features soon","His engineers are busy in November","The accounting software is not ready"],"a":1,"vi":"Đoạn 4: \"because your warehouse teams have said they need the current features before the busy season begins\". Email không so sánh giá giữa hai phương án."},{"q":"What will Daniel do after receiving Ana's decision?","o":["Send a revised quotation and timeline","Start work on Phase 3 immediately","Cancel the forecasting dashboard","Hire additional engineers"],"a":0,"vi":"Đoạn 5: \"Once we have your decision, I will send a revised quotation and an updated timeline.\""}],"words":243},{"id":"r3-09","level":3,"type":"article","topic":"Finance","title":"A smarter labelling contract","title_vi":"Hợp đồng gán nhãn dữ liệu hiệu quả hơn","head":[],"paras":[[["When Orvia Health's machine-learning team signed its first data-labelling contract in 2023, it paid a fixed monthly fee of $42,000, no matter how many images were actually labelled.","Khi nhóm machine learning của Orvia Health ký hợp đồng gán nhãn dữ liệu đầu tiên vào năm 2023, họ trả một khoản phí cố định 42.000 đô la mỗi tháng, bất kể thực tế có bao nhiêu ảnh được gán nhãn."],["By early this year, the team was using only about 60% of the agreed volume, which meant it was effectively paying for work it never received.","Đến đầu năm nay, nhóm chỉ dùng khoảng 60% khối lượng đã thỏa thuận, nghĩa là trên thực tế họ đang trả tiền cho phần việc mình không hề nhận."]],[["In February, procurement manager Hana Petrov and ML lead Victor Osei began talks on a new agreement with the vendor, Clearmark Data.","Vào tháng 2, trưởng phòng mua sắm Hana Petrov và trưởng nhóm ML Victor Osei bắt đầu đàm phán một thỏa thuận mới với nhà cung cấp Clearmark Data."],["Instead of a fixed fee, the new contract, which started on 1 May, charges $0.38 per labelled image, with a minimum monthly spend of $15,000.","Thay vì phí cố định, hợp đồng mới có hiệu lực từ ngày 1 tháng 5 tính 0,38 đô la cho mỗi ảnh được gán nhãn, với mức chi tối thiểu 15.000 đô la mỗi tháng."],["Clearmark also agreed to a stricter quality standard: if more than 3% of a batch fails review, the vendor must relabel the batch at no cost within five working days.","Clearmark cũng đồng ý với tiêu chuẩn chất lượng khắt khe hơn: nếu hơn 3% một lô không đạt khi kiểm duyệt, nhà cung cấp phải gán nhãn lại cả lô miễn phí trong vòng năm ngày làm việc."]],[["The results after the first quarter are promising.","Kết quả sau quý đầu tiên khá khả quan."],["Monthly labelling costs have averaged $27,600, a reduction of more than a third, while the error rate has fallen from 4.8% to 2.1%.","Chi phí gán nhãn hằng tháng trung bình ở mức 27.600 đô la, giảm hơn một phần ba, trong khi tỷ lệ lỗi giảm từ 4,8% xuống 2,1%."],["Victor says the lower error rate has saved his engineers roughly ten hours a week that they used to spend cleaning up labels.","Victor cho biết tỷ lệ lỗi thấp hơn đã giúp các kỹ sư của anh tiết kiệm khoảng mười giờ mỗi tuần mà trước đây họ phải dành để làm sạch nhãn."]],[["There are trade-offs, however.","Tuy nhiên, cũng có những đánh đổi."],["Urgent requests now carry a 20% extra charge, and the team must give two weeks' notice before any month in which it expects volume to double.","Các yêu cầu gấp giờ bị tính thêm 20% phí, và nhóm phải báo trước hai tuần trước bất kỳ tháng nào dự kiến khối lượng tăng gấp đôi."],["Hana's team will review the contract again in November, before the renewal date in January, and is considering adding a second vendor to reduce the company's dependence on Clearmark.","Nhóm của Hana sẽ xem xét lại hợp đồng vào tháng 11, trước ngày gia hạn vào tháng 1, và đang cân nhắc bổ sung nhà cung cấp thứ hai để giảm sự phụ thuộc của công ty vào Clearmark."]]],"vocab":[{"w":"contract","f":"contract","pos":"n/v","ipa":"/ˈkɑntrækt/","vi":"hợp đồng; ký kết"},{"w":"fee","f":"fee","pos":"n","ipa":"/fiː/","vi":"phí, thù lao"},{"w":"volume","f":"volume","pos":"n","ipa":"/ˈvɑljum/","vi":"khối lượng, âm lượng"},{"w":"procurement","f":"procurement","pos":"n","ipa":"/prəˈkjʊrmənt/","vi":"sự thu mua, sự mua sắm"},{"w":"vendor","f":"vendor","pos":"n","ipa":"/ˈvɛndər/","vi":"nhà cung cấp, người bán hàng"},{"w":"instead of","f":"instead of","pos":"phrase","ipa":"","vi":"thay vì"},{"w":"used to","f":"used to","pos":"phrase","ipa":"/ˈjustə/","vi":"đã từng"},{"w":"clean up","f":"cleaning up","pos":"phrase","ipa":"","vi":"dọn dẹp (code)"},{"w":"trade-off","f":"trade-offs","pos":"phrase","ipa":"","vi":"sự đánh đổi"},{"w":"notice","f":"notice","pos":"n/v","ipa":"/ˈnoʊtɪs/","vi":"thông báo; chú ý"},{"w":"renewal","f":"renewal","pos":"n","ipa":"/rɪˈnuːəl/","vi":"sự gia hạn; sự đổi mới"},{"w":"dependence","f":"dependence","pos":"n","ipa":"/dɪˈpɛndəns/","vi":"sự phụ thuộc, lòng tin"}],"questions":[{"q":"What was the main problem with the original contract?","o":["The quality of the labels was too low","The team paid for more volume than it used","The vendor often missed deadlines","The fee rose every month"],"a":1,"vi":"Đoạn 1: phí cố định 42.000 đô la nhưng chỉ dùng khoảng 60% khối lượng → \"paying for work it never received\"."},{"q":"What happens if more than 3% of a batch fails review?","o":["The vendor pays a 20% penalty","The contract is ended","The team must give two weeks' notice","The vendor relabels the batch at no cost"],"a":3,"vi":"Đoạn 2: nhà cung cấp phải \"relabel the batch at no cost within five working days\". 20% là phụ phí cho yêu cầu gấp; báo trước hai tuần là khi khối lượng tăng gấp đôi."},{"q":"On average, how much has the team spent on labelling per month under the new contract?","o":["$15,000","$42,000","$27,600","$38,000"],"a":2,"vi":"Đoạn 3: \"Monthly labelling costs have averaged $27,600\". 15.000 là mức chi tối thiểu, 42.000 là phí cố định của hợp đồng cũ."},{"q":"What is the team considering for the future?","o":["Adding a second labelling vendor","Returning to a fixed monthly fee","Ending the contract in November","Removing the minimum monthly spend"],"a":0,"vi":"Câu cuối: đang cân nhắc \"adding a second vendor to reduce the company's dependence on Clearmark\". Tháng 11 chỉ là lúc xem xét lại hợp đồng, không phải chấm dứt."}],"words":250},{"id":"r3-10","level":3,"type":"report","topic":"Product","title":"Notewise beta results","title_vi":"Kết quả bản beta Notewise","head":[],"paras":[[["This report summarises the results of the six-week closed beta of Notewise, the AI meeting-notes assistant developed by Pelican Labs.","Báo cáo này tóm tắt kết quả sáu tuần beta kín của Notewise, trợ lý ghi chú cuộc họp bằng AI do Pelican Labs phát triển."],["The beta ran from 2 June to 13 July and involved 350 users from 28 customer companies, selected by the sales team.","Bản beta diễn ra từ ngày 2 tháng 6 đến 13 tháng 7 với 350 người dùng đến từ 28 công ty khách hàng do nhóm sales lựa chọn."]],[["Engagement was higher than we expected.","Mức độ sử dụng cao hơn chúng tôi kỳ vọng."],["On average, users ran Notewise in 4.6 meetings per week, against a target of 3, and 71% were still active in the final week.","Trung bình, người dùng chạy Notewise trong 4,6 cuộc họp mỗi tuần, so với mục tiêu là 3, và 71% vẫn còn hoạt động trong tuần cuối cùng."],["In the closing questionnaire, 64% said they would be prepared to pay for the product, although most preferred a team plan to an individual subscription.","Trong bảng khảo sát cuối kỳ, 64% cho biết họ sẵn sàng trả tiền cho sản phẩm, dù phần lớn thích gói theo nhóm hơn là gói đăng ký cá nhân."]],[["The feedback also revealed two serious problems.","Phản hồi cũng cho thấy hai vấn đề nghiêm trọng."],["First, summaries of meetings longer than 45 minutes often missed decisions made near the end, an issue mentioned by almost half of the respondents.","Thứ nhất, bản tóm tắt của các cuộc họp dài hơn 45 phút thường bỏ sót những quyết định được đưa ra gần cuối, vấn đề được gần một nửa số người trả lời nhắc tới."],["Second, several administrators complained that they could not control where recordings were stored, which is a deal breaker for companies in strictly controlled industries such as banking.","Thứ hai, một số quản trị viên phàn nàn rằng họ không thể kiểm soát nơi lưu trữ bản ghi âm, đây là yếu tố khiến các công ty trong những ngành bị quản lý chặt như ngân hàng từ chối sản phẩm."]],[["Based on these findings, the product team has changed the launch plan.","Dựa trên những phát hiện này, nhóm sản phẩm đã thay đổi kế hoạch ra mắt."],["The public launch, previously set for 1 September, has been pushed back to 6 October so that engineers can improve the handling of long meetings.","Đợt ra mắt công khai, trước đây dự kiến vào ngày 1 tháng 9, đã được lùi sang ngày 6 tháng 10 để kỹ sư có thể cải thiện khả năng xử lý các cuộc họp dài."],["Storage settings for administrators have been moved forward from the Q4 plan and will be included at launch.","Phần cài đặt lưu trữ dành cho quản trị viên đã được đưa lên sớm hơn so với kế hoạch quý 4 và sẽ có mặt ngay khi ra mắt."]],[["Pricing will be decided by the end of August, when Carmen Diaz from the finance team will present three options to the leadership group.","Giá bán sẽ được quyết định trước cuối tháng 8, khi Carmen Diaz bên tài chính trình bày ba phương án cho ban lãnh đạo."],["In the meantime, beta users will keep free access until the launch date and will receive 30% off their first year.","Trong thời gian chờ đợi, người dùng beta vẫn được dùng miễn phí đến ngày ra mắt và sẽ được giảm 30% cho năm đầu tiên."]]],"vocab":[{"w":"customer","f":"customer","pos":"n","ipa":"/ˈkʌstəmər/","vi":"khách hàng"},{"w":"engagement","f":"engagement","pos":"n","ipa":"/ɪnˈɡeɪdʒmənt/","vi":"sự tương tác, mức độ gắn kết"},{"w":"target","f":"target","pos":"n/v","ipa":"/ˈtɑːrɡɪt/","vi":"mục tiêu; nhắm mục tiêu"},{"w":"subscription","f":"subscription","pos":"n","ipa":"/səbˈskrɪpʃn/","vi":"sự đăng ký dài hạn, gói thuê bao"},{"w":"feedback","f":"feedback","pos":"n","ipa":"/ˈfidˌbæk/","vi":"phản hồi; ý kiến đóng góp"},{"w":"respondent","f":"respondents","pos":"n","ipa":"/rɪˈspɑːndənt/","vi":"người trả lời khảo sát; bị đơn"},{"w":"administrator","f":"administrators","pos":"n","ipa":"/ədˈmɪnəˌstreɪtər/","vi":"quản trị viên, người quản lý"},{"w":"deal breaker","f":"deal breaker","pos":"phrase","ipa":"","vi":"điều kiện tiên quyết, lý do huỷ thoả thuận"},{"w":"launch","f":"launch","pos":"v/n","ipa":"/lɔːntʃ/","vi":"ra mắt, khởi động; sự ra mắt"},{"w":"push back","f":"pushed back","pos":"phrase","ipa":"","vi":"lùi lại (lịch)"},{"w":"in the meantime","f":"in the meantime","pos":"phrase","ipa":"","vi":"trong lúc chờ đợi"},{"w":"access","f":"access","pos":"n/v","ipa":"/ˈæksɛs/","vi":"quyền truy cập, lối vào; tiếp cận"}],"questions":[{"q":"How did actual usage compare with the target?","o":["It was lower than the target","It matched the target exactly","It was higher than the target","It was not measured"],"a":2,"vi":"Đoạn 2: trung bình 4,6 cuộc họp/tuần so với mục tiêu 3 → cao hơn mục tiêu; câu mở đầu cũng nói \"Engagement was higher than we expected\"."},{"q":"Why was the public launch delayed?","o":["To improve summaries of long meetings","To finish the pricing options","To add more beta customers","To build storage settings for banks"],"a":0,"vi":"Đoạn 4: lùi sang 6/10 \"so that engineers can improve the handling of long meetings\". Cài đặt lưu trữ được đưa lên sớm nhưng không phải lý do lùi ngày."},{"q":"When will the pricing be decided?","o":["By 1 September","By the end of August","By 6 October","By 13 July"],"a":1,"vi":"Đoạn 5: \"Pricing will be decided by the end of August\". 1/9 là ngày ra mắt cũ, 6/10 là ngày ra mắt mới, 13/7 là ngày kết thúc beta."},{"q":"The phrase \"deal breaker\" in paragraph 3, line 3, is closest in meaning to","o":["a sales opportunity","a legal contract","a minor inconvenience","a reason to reject an agreement"],"a":3,"vi":"\"Deal breaker\" = yếu tố khiến một bên từ chối thỏa thuận/không mua; với ngân hàng, không kiểm soát được nơi lưu dữ liệu là lý do để không dùng sản phẩm."}],"words":256},{"id":"r3-11","level":3,"type":"report","topic":"Logistics","title":"Q3 equipment delivery report","title_vi":"Báo cáo giao thiết bị quý 3","head":[["From","IT Logistics, Larkfield Systems"],["To","Engineering managers"],["Period","July 1 – September 30"]],"paras":[[["This report summarizes equipment deliveries to the Da Nang engineering hub of Larkfield Systems between July 1 and September 30.","Báo cáo này tóm tắt việc giao thiết bị đến trung tâm kỹ thuật Đà Nẵng của Larkfield Systems từ ngày 1 tháng 7 đến ngày 30 tháng 9."],["During the quarter, the hub received 214 laptops, 96 monitors and 12 GPU workstations, against a plan of 240, 110 and 12 respectively.","Trong quý, trung tâm đã nhận 214 laptop, 96 màn hình và 12 máy trạm GPU, so với kế hoạch lần lượt là 240, 110 và 12."],["The shortage of laptops was the most serious issue, because 31 new engineers started work in August and September.","Việc thiếu laptop là vấn đề nghiêm trọng nhất, vì có 31 kỹ sư mới bắt đầu làm việc trong tháng 8 và tháng 9."]],[["The main cause was a customs delay at the port, where one shipment of 40 laptops was held for eleven days in August.","Nguyên nhân chính là sự chậm trễ thông quan tại cảng, nơi một lô hàng 40 laptop bị giữ lại mười một ngày trong tháng 8."],["Our vendor, Brightway Freight, had sent an incomplete invoice that did not list the serial numbers of the devices.","Nhà cung cấp của chúng ta, Brightway Freight, đã gửi một hóa đơn không đầy đủ, không ghi số sê-ri của các thiết bị."],["As a result, eight new hires worked on borrowed machines for up to two weeks, and the onboarding team estimates that about 60 working hours were lost.","Do đó, tám nhân viên mới phải làm việc trên máy mượn trong tối đa hai tuần, và nhóm onboarding ước tính khoảng 60 giờ làm việc đã bị mất."],["Monitor deliveries were also late, but this had little effect on productivity.","Việc giao màn hình cũng bị trễ, nhưng điều này ít ảnh hưởng đến năng suất."]],[["To prevent the same problem in Q4, the logistics team will make three changes.","Để tránh lặp lại vấn đề này trong quý 4, nhóm logistics sẽ thực hiện ba thay đổi."],["First, all orders for new hires must be placed at least six weeks in advance, instead of the current four.","Thứ nhất, mọi đơn đặt thiết bị cho nhân viên mới phải được đặt trước ít nhất sáu tuần, thay vì bốn tuần như hiện nay."],["Second, Minh Tran from Finance will check every vendor invoice before a shipment leaves the warehouse in Singapore.","Thứ hai, Minh Trần bên Tài chính sẽ kiểm tra mọi hóa đơn của nhà cung cấp trước khi lô hàng rời kho ở Singapore."],["Third, the hub will keep an inventory of ten spare laptops so that no new engineer has to wait for a device.","Thứ ba, trung tâm sẽ duy trì một lượng dự trữ mười laptop để không kỹ sư mới nào phải chờ thiết bị."],["The cost of these spare laptops, about 14,000 dollars, will come from the IT budget.","Chi phí cho số laptop dự phòng này, khoảng 14.000 đô la, sẽ lấy từ ngân sách IT."],["Hiring managers should send their Q4 start dates to logistics@larkfield.io by October 15.","Các quản lý tuyển dụng cần gửi ngày bắt đầu làm việc của nhân viên mới trong quý 4 tới logistics@larkfield.io trước ngày 15 tháng 10."]]],"vocab":[{"w":"shortage","f":"shortage","pos":"n","ipa":"/ˈʃɔrtɪdʒ/","vi":"sự thiếu hụt"},{"w":"delay","f":"delay","pos":"n/v","ipa":"/dɪˈleɪ/","vi":"sự chậm trễ; trì hoãn"},{"w":"shipment","f":"shipment","pos":"n","ipa":"/ˈʃɪpmənt/","vi":"lô hàng; sự vận chuyển"},{"w":"vendor","f":"vendor","pos":"n","ipa":"/ˈvɛndər/","vi":"nhà cung cấp, người bán hàng"},{"w":"invoice","f":"invoice","pos":"n/v","ipa":"/ˈɪnvɔɪs/","vi":"hóa đơn; lập hóa đơn"},{"w":"as a result","f":"As a result","pos":"phrase","ipa":"","vi":"kết quả là"},{"w":"hire","f":"hires","pos":"v/n","ipa":"/ˈhaɪər/","vi":"thuê, tuyển dụng"},{"w":"estimate","f":"estimates","pos":"v/n","ipa":"/ˈestɪmeɪt/","vi":"ước tính; bản dự toán"},{"w":"productivity","f":"productivity","pos":"n","ipa":"/ˌprɑːdʌkˈtɪvəti/","vi":"năng suất làm việc"},{"w":"in advance","f":"in advance","pos":"phrase","ipa":"","vi":"trước, sẵn"},{"w":"warehouse","f":"warehouse","pos":"n","ipa":"/ˈwɛrˌhaʊs/","vi":"kho hàng"},{"w":"inventory","f":"inventory","pos":"n","ipa":"/ˈɪnvəntɔːri/","vi":"hàng tồn kho, kiểm kê"}],"questions":[{"q":"What was the most serious problem during the quarter?","o":["Late monitor deliveries","A shortage of laptops","A lack of GPU workstations","A rise in shipping costs"],"a":1,"vi":"Câu 'The shortage of laptops was the most serious issue' cho đáp án B. Màn hình cũng giao trễ nhưng 'had little effect', còn GPU nhận đủ 12/12."},{"q":"Why was a shipment held at the port?","o":["The devices were damaged","The vendor sent the wrong model","The invoice did not list serial numbers","The warehouse in Singapore was closed"],"a":2,"vi":"Đoạn 2: nhà cung cấp gửi 'an incomplete invoice that did not list the serial numbers'. Kho Singapore được nhắc ở đoạn 3 nhưng không phải nguyên nhân."},{"q":"What is NOT one of the changes planned for Q4?","o":["Ordering devices six weeks ahead","Having Finance check vendor invoices","Keeping ten spare laptops","Switching to a new logistics vendor"],"a":3,"vi":"Ba thay đổi là: đặt trước sáu tuần, Minh Trần (Tài chính) kiểm tra hóa đơn, dự trữ mười laptop. Không hề nói đổi nhà cung cấp, nên chọn D."},{"q":"By when must hiring managers send Q4 start dates?","o":["October 15","September 30","Six weeks before Q4","The end of Q4"],"a":0,"vi":"Câu cuối: 'send their Q4 start dates ... by October 15'. September 30 là ngày kết thúc kỳ báo cáo, 'six weeks' là thời hạn đặt hàng."}],"words":248},{"id":"r3-12","level":3,"type":"memo","topic":"Legal","title":"New review process for vendor contracts","title_vi":"Quy trình mới xem xét hợp đồng nhà cung cấp","head":[["From","Grace Okafor, Legal Counsel <grace.okafor@novatide.ai>"],["To","All engineering and product managers"],["Date","March 3"],["Subject","Legal review for vendor contracts"]],"paras":[[["As Novatide grows, more teams are signing agreements with outside vendors for training data, labeling services and cloud tools.","Khi Novatide phát triển, ngày càng nhiều nhóm ký thỏa thuận với các nhà cung cấp bên ngoài về dữ liệu huấn luyện, dịch vụ gán nhãn và công cụ đám mây."],["Last quarter, the Legal team found that four of these contracts allowed the vendor to reuse our data for its own models.","Quý trước, nhóm Pháp chế phát hiện bốn trong số các hợp đồng này cho phép nhà cung cấp tái sử dụng dữ liệu của chúng ta cho các mô hình của riêng họ."],["None of them had been checked by Legal before they were signed.","Không hợp đồng nào trong số đó được Pháp chế kiểm tra trước khi ký."]],[["Effective April 1, every vendor contract worth more than 5,000 dollars a year must go through a formal legal review.","Có hiệu lực từ ngày 1 tháng 4, mọi hợp đồng với nhà cung cấp trị giá trên 5.000 đô la mỗi năm phải qua bước xem xét pháp lý chính thức."],["The requirement also applies to free trials if the vendor will receive any customer data.","Yêu cầu này cũng áp dụng cho các bản dùng thử miễn phí nếu nhà cung cấp sẽ nhận bất kỳ dữ liệu khách hàng nào."],["Managers should open a request in the Legal portal at least ten business days before the planned start date and include the draft contract and a short description of the data involved.","Các quản lý nên mở yêu cầu trên cổng Pháp chế ít nhất mười ngày làm việc trước ngày dự kiến bắt đầu, kèm theo bản nháp hợp đồng và mô tả ngắn về dữ liệu liên quan."],["Contracts that include personal data will also be sent to the compliance team, which may add up to five more days.","Các hợp đồng có dữ liệu cá nhân cũng sẽ được chuyển cho nhóm tuân thủ, việc này có thể kéo dài thêm tối đa năm ngày."],["Legal will reply with comments or a final approval within the same ten days.","Pháp chế sẽ phản hồi bằng nhận xét hoặc phê duyệt cuối cùng trong cùng khoảng mười ngày đó."]],[["Existing contracts are not affected until they are renewed.","Các hợp đồng hiện có không bị ảnh hưởng cho đến khi được gia hạn."],["However, Daniel Reyes, who is in charge of vendor management, will audit the twenty largest agreements by the end of May.","Tuy nhiên, Daniel Reyes, người phụ trách quản lý nhà cung cấp, sẽ rà soát hai mươi thỏa thuận lớn nhất trước cuối tháng 5."],["If he finds terms that put our data at risk, he will contact the responsible manager directly.","Nếu phát hiện điều khoản nào khiến dữ liệu của chúng ta gặp rủi ro, anh ấy sẽ liên hệ trực tiếp với quản lý phụ trách."],["Please do not sign any vendor document yourself, even a simple order form, unless Legal has confirmed it.","Vui lòng không tự ký bất kỳ tài liệu nào của nhà cung cấp, kể cả một mẫu đơn đặt hàng đơn giản, trừ khi Pháp chế đã xác nhận."],["Questions can be sent to legal-help@novatide.ai, and we will hold a 30-minute briefing for managers on March 12.","Câu hỏi có thể gửi tới legal-help@novatide.ai, và chúng tôi sẽ tổ chức một buổi phổ biến 30 phút cho các quản lý vào ngày 12 tháng 3."]]],"vocab":[{"w":"agreement","f":"agreements","pos":"n","ipa":"/əˈɡriːmənt/","vi":"hợp đồng, thỏa thuận"},{"w":"vendor","f":"vendor","pos":"n","ipa":"/ˈvɛndər/","vi":"nhà cung cấp, người bán hàng"},{"w":"contract","f":"contracts","pos":"n/v","ipa":"/ˈkɑntrækt/","vi":"hợp đồng; ký kết"},{"w":"effective","f":"Effective","pos":"adj","ipa":"/ɪˈfektɪv/","vi":"hiệu quả"},{"w":"requirement","f":"requirement","pos":"n","ipa":"/rɪˈkwɑɪərmənt/","vi":"yêu cầu; điều kiện tiên quyết"},{"w":"request","f":"request","pos":"n/v","ipa":"/rɪˈkwest/","vi":"yêu cầu, lời thỉnh cầu"},{"w":"compliance","f":"compliance","pos":"n","ipa":"/kəmˈplaɪ.əns/","vi":"sự tuân thủ"},{"w":"renew","f":"renewed","pos":"v","ipa":"/rɪˈnu/","vi":"gia hạn, làm mới"},{"w":"be in charge of","f":"is in charge of","pos":"phrase","ipa":"","vi":"phụ trách"},{"w":"audit","f":"audit","pos":"n/v","ipa":"/ˈɔːdɪt/","vi":"kiểm toán"},{"w":"risk","f":"risk","pos":"n/v","ipa":"/rɪsk/","vi":"Rủi ro; liều lĩnh"},{"w":"confirm","f":"confirmed","pos":"v","ipa":"/kənˈfɜːrm/","vi":"xác nhận; khẳng định"}],"questions":[{"q":"What problem did Legal find last quarter?","o":["Some vendors charged more than agreed","Some contracts let vendors reuse company data","Several free trials had expired","Managers had lost signed agreements"],"a":1,"vi":"Đoạn 1: 'four of these contracts allowed the vendor to reuse our data for its own models' → B. Các lựa chọn khác không được nhắc."},{"q":"Which of the following will need a legal review under the new rule?","o":["A 3,000-dollar yearly tool that receives no customer data","An existing contract that has not yet been renewed","A free trial in which the vendor receives customer data","An order form that Legal has already confirmed"],"a":2,"vi":"Câu 'The requirement also applies to free trials if the vendor will receive any customer data' → C. A dưới mức 5.000 đô la; B không bị ảnh hưởng 'until they are renewed'."},{"q":"How long before the start date should a manager open a request?","o":["Five business days","Thirty days","By the end of May","At least ten business days"],"a":3,"vi":"'at least ten business days before the planned start date' → D. 'Five more days' là thời gian thêm của nhóm tuân thủ, 'end of May' là hạn rà soát của Daniel."},{"q":"What will Daniel Reyes do?","o":["Audit the 20 largest existing agreements","Approve all free trials","Run the briefing on March 12","Sign order forms on behalf of managers"],"a":0,"vi":"'Daniel Reyes ... will audit the twenty largest agreements by the end of May' → A. Buổi phổ biến 12/3 do nhóm Pháp chế tổ chức, không nói là Daniel."}],"words":241},{"id":"r3-13","level":3,"type":"article","topic":"Sales","title":"How a demo sandbox shortened the sales cycle","title_vi":"Môi trường demo đã rút ngắn chu kỳ bán hàng như thế nào","head":[],"paras":[[["When the sales team at Corvane Analytics began offering prospective clients a self-service demo sandbox in January, few people expected it to change the numbers so quickly.","Khi đội bán hàng của Corvane Analytics bắt đầu cung cấp cho khách hàng tiềm năng một môi trường demo tự phục vụ vào tháng 1, ít ai ngờ nó lại thay đổi các con số nhanh đến vậy."],["In the first two quarters of the year, the average time from first meeting to signed deal fell from 94 days to 61 days.","Trong hai quý đầu năm, thời gian trung bình từ buổi gặp đầu tiên đến khi ký hợp đồng giảm từ 94 ngày xuống 61 ngày."],["The win rate rose from 22 to 29 percent, and revenue from new clients reached 3.4 million dollars, 18 percent above target.","Tỷ lệ thắng tăng từ 22 lên 29 phần trăm, và doanh thu từ khách hàng mới đạt 3,4 triệu đô la, vượt mục tiêu 18 phần trăm."]],[["The sandbox was built in six weeks by a small team led by data engineer Priya Nair.","Sandbox được xây dựng trong sáu tuần bởi một nhóm nhỏ do kỹ sư dữ liệu Priya Nair dẫn dắt."],["It loads a copy of the client's own sample data, so buyers can test real forecasts instead of watching a slide presentation.","Nó tải một bản sao dữ liệu mẫu của chính khách hàng, nhờ đó người mua có thể thử dự báo thật thay vì ngồi xem slide thuyết trình."],["Clients usually see their first results within 20 minutes of signing up.","Khách hàng thường thấy kết quả đầu tiên trong vòng 20 phút sau khi đăng ký."],["According to Nair, the hardest part was not the model but the data pipeline, because every client stores data in a different way.","Theo Nair, phần khó nhất không phải là mô hình mà là pipeline dữ liệu, vì mỗi khách hàng lưu dữ liệu theo một cách khác nhau."],["Her team now supports eleven common file types and adds about one new type each month.","Nhóm của cô hiện hỗ trợ mười một loại tệp phổ biến và bổ sung khoảng một loại mới mỗi tháng."]],[["The results have not been perfect.","Kết quả vẫn chưa hoàn hảo."],["Sales director Tom Becker points out that large enterprise deals still take more than four months, mainly because their security reviews are long.","Giám đốc kinh doanh Tom Becker chỉ ra rằng các thương vụ với doanh nghiệp lớn vẫn mất hơn bốn tháng, chủ yếu vì quy trình đánh giá bảo mật của họ kéo dài."],["Some clients have also used the sandbox for weeks without ever talking to a salesperson.","Một số khách hàng cũng dùng sandbox hàng tuần liền mà không hề trao đổi với nhân viên bán hàng nào."],["To address this, from October every sandbox account will expire after 21 days, and an account manager will follow up on each one within three days of sign-up.","Để giải quyết việc này, từ tháng 10, mỗi tài khoản sandbox sẽ hết hạn sau 21 ngày, và một quản lý tài khoản sẽ liên hệ theo dõi từng tài khoản trong vòng ba ngày sau khi đăng ký."],["Becker hopes to bring the enterprise cycle under 90 days by next summer.","Becker hy vọng rút ngắn chu kỳ bán hàng doanh nghiệp xuống dưới 90 ngày vào mùa hè năm sau."]]],"vocab":[{"w":"client","f":"clients","pos":"n","ipa":"/ˈklaɪənt/","vi":"khách hàng"},{"w":"average","f":"average","pos":"adj/n","ipa":"/ˈævərɪdʒ/","vi":"trung bình"},{"w":"deal","f":"deal","pos":"n/v","ipa":"/dil/","vi":"thỏa thuận; giải quyết"},{"w":"rate","f":"rate","pos":"n/v","ipa":"/reɪt/","vi":"tỷ lệ, mức giá; đánh giá"},{"w":"revenue","f":"revenue","pos":"n","ipa":"/ˈrɛvənuː/","vi":"doanh thu"},{"w":"target","f":"target","pos":"n/v","ipa":"/ˈtɑːrɡɪt/","vi":"mục tiêu; nhắm mục tiêu"},{"w":"sample","f":"sample","pos":"n/v","ipa":"/ˈsæmpəl/","vi":"mẫu, hàng mẫu; lấy mẫu thử"},{"w":"instead of","f":"instead of","pos":"phrase","ipa":"","vi":"thay vì"},{"w":"pipeline","f":"pipeline","pos":"n","ipa":"/ˈpaɪplaɪn/","vi":"đường ống; quy trình xử lý"},{"w":"point out","f":"points out","pos":"phrase","ipa":"","vi":"chỉ ra"},{"w":"expire","f":"expire","pos":"v","ipa":"/ɪkˈspaɪər/","vi":"hết hạn; kết thúc"},{"w":"follow up on","f":"follow up on","pos":"phrase","ipa":"","vi":"theo dõi tiếp, hỏi lại về"}],"questions":[{"q":"By how many days did the average sales cycle become shorter?","o":["7 days","18 days","33 days","61 days"],"a":2,"vi":"Thời gian giảm 'from 94 days to 61 days', tức ngắn hơn 33 ngày → C. 7 là mức tăng tỷ lệ thắng (22→29), 18 là phần trăm vượt mục tiêu."},{"q":"According to Priya Nair, what was the most difficult part of the project?","o":["Building the model","Handling the different ways clients store data","Finishing the work in six weeks","Replacing slide presentations"],"a":1,"vi":"'the hardest part was not the model but the data pipeline, because every client stores data in a different way' → B. A là bẫy vì câu nói rõ 'not the model'."},{"q":"The word \"address\" in paragraph 3 is closest in meaning to","o":["deal with","speak to","send to","write on"],"a":0,"vi":"'To address this' = để giải quyết vấn đề này, nghĩa gần nhất là 'deal with' → A. 'address' còn có nghĩa là nói chuyện với ai hay ghi địa chỉ, nhưng không hợp ngữ cảnh."},{"q":"What will change in October?","o":["Enterprise security reviews will become shorter","New file types will be added every week","The win-rate target will rise to 29 percent","Sandbox accounts will expire after 21 days"],"a":3,"vi":"'from October every sandbox account will expire after 21 days' → D. Loại tệp mới được thêm 'each month', 29% là kết quả đã đạt chứ không phải mục tiêu mới."}],"words":249},{"id":"r3-14","level":3,"type":"job","topic":"HR","title":"Senior ML Engineer, Model Evaluation","title_vi":"Kỹ sư ML cấp cao, Đánh giá mô hình","head":[["Company","Quellstone AI"],["Location","Ho Chi Minh City (hybrid)"],["Apply by","December 5"]],"paras":[[["Quellstone AI is looking for a Senior Machine Learning Engineer to join its Model Evaluation team in Ho Chi Minh City.","Quellstone AI đang tìm một Kỹ sư Machine Learning cấp cao gia nhập nhóm Đánh giá Mô hình tại TP. Hồ Chí Minh."],["The team of seven tests every language model before it is released to our 40 enterprise customers, and reports on accuracy, speed and safety.","Nhóm gồm bảy người kiểm thử mọi mô hình ngôn ngữ trước khi phát hành cho 40 khách hàng doanh nghiệp của chúng tôi, và báo cáo về độ chính xác, tốc độ và mức độ an toàn."],["In the past year, the team has evaluated more than 60 model versions and stopped three releases that did not meet our quality bar.","Trong năm qua, nhóm đã đánh giá hơn 60 phiên bản mô hình và chặn ba lần phát hành không đạt chuẩn chất lượng."],["This position reports to Linh Pham, Head of Evaluation.","Vị trí này báo cáo trực tiếp cho Linh Phạm, Trưởng bộ phận Đánh giá."]],[["Your main responsibilities will be to design test sets, build automated evaluation pipelines and explain results to product managers in clear English.","Trách nhiệm chính của bạn là thiết kế bộ dữ liệu kiểm thử, xây dựng pipeline đánh giá tự động và giải thích kết quả cho các quản lý sản phẩm bằng tiếng Anh rõ ràng."],["You will also take ownership of the weekly quality metric that the leadership team reviews every Monday.","Bạn cũng sẽ chịu trách nhiệm về chỉ số chất lượng hàng tuần mà ban lãnh đạo xem xét vào mỗi thứ Hai."],["We require at least five years of experience in Python and machine learning, including two years working with large language models.","Chúng tôi yêu cầu ít nhất năm năm kinh nghiệm với Python và machine learning, trong đó có hai năm làm việc với các mô hình ngôn ngữ lớn."],["Experience with Kubernetes is helpful but not necessary, as you will receive training in your first month.","Kinh nghiệm với Kubernetes là một lợi thế nhưng không bắt buộc, vì bạn sẽ được đào tạo trong tháng đầu tiên."]],[["The position is hybrid, with three days a week in our District 1 office.","Vị trí này làm việc kết hợp, ba ngày mỗi tuần tại văn phòng Quận 1."],["Benefits include private health insurance for you and your family, a yearly learning budget of 1,500 dollars and 18 days of paid leave.","Phúc lợi bao gồm bảo hiểm sức khỏe tư nhân cho bạn và gia đình, ngân sách học tập hàng năm 1.500 đô la và 18 ngày nghỉ phép có lương."],["The hiring process has three steps: a 30-minute call with HR, a take-home task that should take no more than four hours, and a final interview with the team.","Quy trình tuyển dụng gồm ba bước: một cuộc gọi 30 phút với bộ phận nhân sự, một bài tập về nhà làm không quá bốn giờ, và một buổi phỏng vấn cuối với nhóm."],["To apply, send your CV and a short note about one evaluation project you are proud of to careers@quellstone.ai by December 5.","Để ứng tuyển, hãy gửi CV và một đoạn ngắn về một dự án đánh giá mà bạn tự hào tới careers@quellstone.ai trước ngày 5 tháng 12."],["Applications received after this date will not be considered.","Hồ sơ nhận được sau ngày này sẽ không được xem xét."]]],"vocab":[{"w":"release","f":"released","pos":"v/n","ipa":"/rɪˈliːs/","vi":"phát hành, tung ra; sự phát hành"},{"w":"accuracy","f":"accuracy","pos":"n","ipa":"/ˈækjərəsi/","vi":"độ chính xác"},{"w":"position","f":"position","pos":"n/v","ipa":"/pəˈzɪʃən/","vi":"vị trí công việc; định vị"},{"w":"responsibility","f":"responsibilities","pos":"n","ipa":"/rɪˌspɑːnsəˈbɪləti/","vi":"trách nhiệm; nhiệm vụ"},{"w":"pipeline","f":"pipelines","pos":"n","ipa":"/ˈpaɪplaɪn/","vi":"đường ống; quy trình xử lý"},{"w":"take ownership of","f":"take ownership of","pos":"phrase","ipa":"","vi":"nhận trách nhiệm chính"},{"w":"metric","f":"metric","pos":"n","ipa":"/ˈmetrɪk/","vi":"số đo, hệ thống đo lường"},{"w":"require","f":"require","pos":"v","ipa":"/rɪˈkwaɪər/","vi":"yêu cầu, đòi hỏi"},{"w":"benefit","f":"Benefits","pos":"n/v","ipa":"/ˈbɛnəfɪt/","vi":"Lợi ích; được lợi"},{"w":"budget","f":"budget","pos":"n/v","ipa":"/ˈbʌdʒɪt/","vi":"ngân sách; lên ngân sách"},{"w":"interview","f":"interview","pos":"n/v","ipa":"/ˈɪntərvjuː/","vi":"phuốc phỏng vấn; phỏng vấn"},{"w":"apply","f":"apply","pos":"v","ipa":"/əˈplaɪ/","vi":"nộp đơn; áp dụng"}],"questions":[{"q":"Who will the new engineer report to?","o":["The leadership team","A product manager","Linh Pham","The HR team"],"a":2,"vi":"'This position reports to Linh Pham, Head of Evaluation' → C. Ban lãnh đạo chỉ xem chỉ số hàng tuần, quản lý sản phẩm là người nghe giải thích kết quả."},{"q":"What is stated about experience with Kubernetes?","o":["It is required for all applicants","It is useful but not necessary","At least two years are needed","It will be tested in the take-home task"],"a":1,"vi":"'Experience with Kubernetes is helpful but not necessary' → B. 'Two years' là yêu cầu về mô hình ngôn ngữ lớn, không phải Kubernetes."},{"q":"How many days per week must the engineer work in the office?","o":["Five","Seven","Two","Three"],"a":3,"vi":"'with three days a week in our District 1 office' → D. 'Seven' là số thành viên của nhóm, 'five' là số năm kinh nghiệm."},{"q":"What should applicants send together with their CV?","o":["A note about an evaluation project they are proud of","A list of three references","A completed take-home task","Their expected salary"],"a":0,"vi":"'send your CV and a short note about one evaluation project you are proud of' → A. Bài tập về nhà là bước sau trong quy trình, chưa gửi lúc nộp hồ sơ."}],"words":255},{"id":"r3-15","level":3,"type":"review","topic":"Service","title":"Mid-year performance review: Quang Do","title_vi":"Đánh giá hiệu suất giữa năm: Quang Đỗ","head":[["Employee","Quang Do, Software Engineer II"],["Team","Customer Service Platform"],["Reviewer","Helen Marsh, Engineering Manager"],["Period","January – June"]],"paras":[[["Quang joined the Customer Service Platform team in January and quickly became the main owner of the ticket routing service.","Quang gia nhập nhóm Customer Service Platform vào tháng 1 và nhanh chóng trở thành người phụ trách chính của dịch vụ định tuyến ticket."],["His biggest contribution this period was the new auto-tagging model, which now assigns a category to about 70 percent of incoming customer tickets.","Đóng góp lớn nhất của anh trong kỳ này là mô hình gắn thẻ tự động mới, hiện gán danh mục cho khoảng 70 phần trăm ticket khách hàng gửi đến."],["As a result, the average first response time fell from 9 hours to just under 4 hours, and customer satisfaction scores rose by 11 points.","Nhờ đó, thời gian phản hồi đầu tiên trung bình giảm từ 9 giờ xuống chỉ còn dưới 4 giờ, và điểm hài lòng của khách hàng tăng 11 điểm."]],[["Quang also handled two production outages calmly and wrote clear reports afterwards.","Quang cũng xử lý bình tĩnh hai sự cố ngừng hoạt động trên production và viết báo cáo rõ ràng sau đó."],["Feedback from the support agents was very positive, especially about the dashboard he built to show which tickets were waiting longest.","Phản hồi từ các nhân viên hỗ trợ rất tích cực, đặc biệt về dashboard anh xây dựng để hiển thị những ticket chờ lâu nhất."],["He also mentored two interns, who both received full-time offers in June.","Anh cũng hướng dẫn hai thực tập sinh, và cả hai đều nhận được lời mời làm việc chính thức vào tháng 6."]],[["There are two areas to improve.","Có hai điểm cần cải thiện."],["First, Quang sometimes takes on too much work without telling the team, which caused the March release to be delayed by a week.","Thứ nhất, Quang đôi khi nhận quá nhiều việc mà không báo cho nhóm, điều này khiến bản phát hành tháng 3 bị trễ một tuần."],["He should raise risks early in stand-up meetings instead of trying to fix everything alone.","Anh nên nêu rủi ro sớm trong các buổi họp stand-up thay vì cố tự mình sửa mọi thứ."],["Second, his design documents are technically strong but often too long for non-engineers, so he should add a one-page summary to each one.","Thứ hai, tài liệu thiết kế của anh rất tốt về mặt kỹ thuật nhưng thường quá dài với những người không làm kỹ thuật, vì vậy anh nên thêm một bản tóm tắt một trang cho mỗi tài liệu."]],[["Overall rating: Exceeds expectations.","Đánh giá chung: Vượt kỳ vọng."],["For the second half of the year, Quang will lead the project to extend auto-tagging to Japanese and Korean tickets, with a target of 60 percent coverage by December.","Trong nửa cuối năm, Quang sẽ dẫn dắt dự án mở rộng tính năng gắn thẻ tự động cho ticket tiếng Nhật và tiếng Hàn, với mục tiêu bao phủ 60 phần trăm vào tháng 12."],["Helen and Quang will meet monthly to follow up on this goal, and he will attend a technical writing course in August.","Helen và Quang sẽ gặp nhau hàng tháng để theo dõi mục tiêu này, và anh sẽ tham gia một khóa học viết tài liệu kỹ thuật vào tháng 8."],["His next formal review will take place in January.","Buổi đánh giá chính thức tiếp theo của anh sẽ diễn ra vào tháng 1."]]],"vocab":[{"w":"owner","f":"owner","pos":"n","ipa":"/ˈoʊnər/","vi":"chủ sở hữu; người phụ trách"},{"w":"ticket","f":"tickets","pos":"n","ipa":"/ˈtɪkɪt/","vi":"vé; phiếu yêu cầu hỗ trợ"},{"w":"as a result","f":"As a result","pos":"phrase","ipa":"","vi":"kết quả là"},{"w":"response","f":"response","pos":"n","ipa":"/rɪˈspɑːns/","vi":"phản hồi, câu trả lời"},{"w":"outage","f":"outages","pos":"n","ipa":"/ˈaʊtɪdʒ/","vi":"sự gián đoạn dịch vụ, cúp điện"},{"w":"feedback","f":"feedback","pos":"n","ipa":"/ˈfidˌbæk/","vi":"phản hồi; ý kiến đóng góp"},{"w":"improve","f":"improve","pos":"v","ipa":"/ɪmˈpruːv/","vi":"cải thiện, nâng cao"},{"w":"take on","f":"takes on","pos":"phrase","ipa":"","vi":"nhận thêm (việc)"},{"w":"delay","f":"delayed","pos":"n/v","ipa":"/dɪˈleɪ/","vi":"sự chậm trễ; trì hoãn"},{"w":"instead of","f":"instead of","pos":"phrase","ipa":"","vi":"thay vì"},{"w":"extend","f":"extend","pos":"v","ipa":"/ɪkˈstɛnd/","vi":"kéo dài, mở rộng"},{"w":"follow up on","f":"follow up on","pos":"phrase","ipa":"","vi":"theo dõi tiếp, hỏi lại về"}],"questions":[{"q":"What happened to the average first response time?","o":["It fell to just under 4 hours","It fell by 11 points","It rose to 9 hours","It stayed at 70 percent"],"a":0,"vi":"'the average first response time fell from 9 hours to just under 4 hours' → A. '11 points' là mức tăng điểm hài lòng, '70 percent' là tỷ lệ ticket được gắn thẻ."},{"q":"Why was the March release delayed?","o":["A production outage happened","Quang took on too much work without telling the team","The support agents asked for a new dashboard","The design documents were too long"],"a":1,"vi":"'takes on too much work without telling the team, which caused the March release to be delayed by a week' → B. Sự cố và dashboard được nhắc nhưng không gây trễ."},{"q":"What is suggested about Quang's design documents?","o":["They contain technical errors","They are too short","They are hard for non-engineers to read quickly","They are written only in Japanese"],"a":2,"vi":"'technically strong but often too long for non-engineers' → C. A sai vì tài liệu 'technically strong'; B ngược nghĩa."},{"q":"What will Quang do in August?","o":["Lead the Korean support team","Present at a stand-up meeting","Reach 60 percent coverage","Attend a technical writing course"],"a":3,"vi":"'he will attend a technical writing course in August' → D. Mục tiêu 60% là đến tháng 12, không phải tháng 8."}],"words":244},{"id":"r3-16","level":3,"type":"email","topic":"Logistics","title":"Office move to Lotus Tower","title_vi":"Chuyển văn phòng sang Lotus Tower","head":[["From","Facilities Team <facilities@meridiansoft.vn>"],["To","Platform Engineering"],["Subject","Office move to Lotus Tower – what you need to do"]],"paras":[[["Hi everyone,","Chào mọi người,"]],[["As announced at the town hall, the Platform Engineering team will relocate from the 4th floor of Hanh Building to the 12th floor of Lotus Tower on the weekend of November 22–23.","Như đã thông báo tại buổi họp toàn công ty, nhóm Platform Engineering sẽ chuyển từ tầng 4 tòa Hanh Building sang tầng 12 tòa Lotus Tower vào cuối tuần 22–23 tháng 11."],["The new floor has 64 desks, four meeting rooms and a quiet room for on-call engineers.","Tầng mới có 64 bàn làm việc, bốn phòng họp và một phòng yên tĩnh cho các kỹ sư trực on-call."],["Our current lease ends on November 30, so the move cannot be postponed.","Hợp đồng thuê hiện tại của chúng ta kết thúc vào ngày 30 tháng 11, nên không thể hoãn việc chuyển văn phòng."]],[["Please pack your personal items into the boxes provided by 5 p.m. on Friday, November 21, and label each box with your name and new desk number.","Vui lòng đóng gói đồ cá nhân vào các thùng được phát trước 5 giờ chiều thứ Sáu, ngày 21 tháng 11, và dán nhãn mỗi thùng với tên và số bàn mới của bạn."],["Desk numbers were sent in a separate email on Monday.","Số bàn đã được gửi trong một email riêng vào thứ Hai."],["If you have not received yours, please check your spam folder before contacting us.","Nếu bạn chưa nhận được, vui lòng kiểm tra thư mục spam trước khi liên hệ với chúng tôi."],["The moving company will take care of monitors, docking stations and chairs, but laptops must stay with you.","Công ty vận chuyển sẽ lo màn hình, docking station và ghế, nhưng laptop phải luôn ở bên bạn."],["The two on-premise test servers will be moved separately by the IT team on Saturday morning, so the staging environment will be unavailable from 6 a.m. to 2 p.m. that day.","Hai máy chủ kiểm thử tại chỗ sẽ được nhóm IT chuyển riêng vào sáng thứ Bảy, nên môi trường staging sẽ không dùng được từ 6 giờ sáng đến 2 giờ chiều hôm đó."],["Please do not schedule any deployments during that window.","Vui lòng không lên lịch deploy nào trong khoảng thời gian đó."]],[["Access cards for Lotus Tower will be handed out at reception from 8 a.m. on Monday, November 24.","Thẻ ra vào tòa Lotus Tower sẽ được phát tại quầy lễ tân từ 8 giờ sáng thứ Hai, ngày 24 tháng 11."],["Parking spaces are limited, so staff who drive should register with Facilities in advance.","Chỗ đỗ xe có hạn, nên nhân viên đi xe riêng cần đăng ký trước với bộ phận Hành chính."],["The coffee machine and lockers on the new floor will be ready from the first day.","Máy pha cà phê và tủ đồ cá nhân ở tầng mới sẽ sẵn sàng ngay từ ngày đầu tiên."],["If you have any questions, contact Thu Le, who is responsible for the move, at extension 2207.","Nếu có câu hỏi, hãy liên hệ Thu Lê, người chịu trách nhiệm về đợt chuyển văn phòng, qua số máy lẻ 2207."]],[["Thanks, The Facilities Team","Cảm ơn, Nhóm Hành chính"]]],"vocab":[{"w":"announce","f":"announced","pos":"v","ipa":"/əˈnaʊns/","vi":"thông báo, công bố"},{"w":"relocate","f":"relocate","pos":"v","ipa":"/riːˈloʊkeɪt/","vi":"di dời; chuyển địa điểm làm việc"},{"w":"lease","f":"lease","pos":"n/v","ipa":"/liːs/","vi":"hợp đồng thuê; cho thuê"},{"w":"postpone","f":"postponed","pos":"v","ipa":"/poʊˈspoʊn/","vi":"hoãn lại"},{"w":"personal","f":"personal","pos":"adj","ipa":"/ˈpɜːrsənl/","vi":"cá nhân"},{"w":"take care of","f":"take care of","pos":"phrase","ipa":"","vi":"lo, xử lý"},{"w":"schedule","f":"schedule","pos":"n/v","ipa":"/ˈskɛdʒul/","vi":"lịch trình, tiến độ; lên lịch"},{"w":"in advance","f":"in advance","pos":"phrase","ipa":"","vi":"trước, sẵn"},{"w":"be responsible for","f":"is responsible for","pos":"phrase","ipa":"","vi":"chịu trách nhiệm về"},{"w":"monitor","f":"monitors","pos":"n/v","ipa":"/ˈmɑnətər/","vi":"màn hình; giám sát, theo dõi"},{"w":"limit","f":"limited","pos":"n/v","ipa":"/ˈlɪmɪt/","vi":"giới hạn"}],"questions":[{"q":"Why can't the move be postponed?","o":["The moving company is fully booked","The current lease ends on November 30","Access cards have already been printed","The town hall voted for the date"],"a":1,"vi":"'Our current lease ends on November 30, so the move cannot be postponed' → B. Thẻ ra vào và town hall có nhắc nhưng không phải lý do."},{"q":"Which item should employees NOT leave for the moving company?","o":["Monitors","Chairs","Docking stations","Laptops"],"a":3,"vi":"'The moving company will take care of monitors, docking stations and chairs, but laptops must stay with you' → D."},{"q":"What will happen on Saturday morning?","o":["Access cards will be handed out","Staff will pack their personal items","The staging environment will be unavailable","Parking spaces will be assigned"],"a":2,"vi":"Máy chủ test được chuyển sáng thứ Bảy nên 'the staging environment will be unavailable from 6 a.m. to 2 p.m.' → C. Thẻ phát vào thứ Hai, đóng gói trước chiều thứ Sáu."},{"q":"Who should staff contact if they have questions?","o":["Thu Le","The IT team","The reception desk","The moving company"],"a":0,"vi":"'contact Thu Le, who is responsible for the move' → A. Nhóm IT chỉ chuyển máy chủ, lễ tân chỉ phát thẻ."}],"words":246},{"id":"r3-17","level":3,"type":"report","topic":"Service","title":"Incident report: chatbot gave wrong order status","title_vi":"Báo cáo sự cố: chatbot báo sai trạng thái đơn hàng","head":[["Incident","INC-4471"],["Severity","SEV-2"],["Owner","Arjun Mehta, AI Platform"],["Date","September 9"]],"paras":[[["On September 9, between 10:40 and 13:15, the customer support chatbot of Pellora Home gave wrong order status information to customers.","Ngày 9 tháng 9, từ 10:40 đến 13:15, chatbot hỗ trợ khách hàng của Pellora Home đã cung cấp thông tin trạng thái đơn hàng sai cho khách."],["About 2,300 conversations were affected, and in roughly 400 of them the bot told customers that orders had been delivered when they were still in the warehouse.","Khoảng 2.300 cuộc hội thoại bị ảnh hưởng, và trong khoảng 400 cuộc, bot nói với khách rằng đơn hàng đã được giao trong khi hàng vẫn còn trong kho."],["The support team received 180 complaints by phone and email before the problem was fixed.","Đội hỗ trợ đã nhận 180 khiếu nại qua điện thoại và email trước khi sự cố được khắc phục."]],[["The root cause was a change to the order-tracking API that was released at 10:30 the same morning.","Nguyên nhân gốc là một thay đổi ở API theo dõi đơn hàng được phát hành lúc 10:30 sáng cùng ngày."],["The API team renamed one status field, but the chatbot's data pipeline still expected the old name and filled the empty value with a default of \"delivered\".","Nhóm API đã đổi tên một trường trạng thái, nhưng pipeline dữ liệu của chatbot vẫn chờ tên cũ và điền vào giá trị trống bằng giá trị mặc định \"delivered\" (đã giao)."],["Our monitoring did not catch the error because it only checked whether the chatbot was online, not whether its answers were correct.","Hệ thống giám sát không phát hiện lỗi vì nó chỉ kiểm tra chatbot có đang hoạt động hay không, chứ không kiểm tra câu trả lời có đúng không."],["A support agent noticed the pattern and reported it to the on-call engineer at 12:20.","Một nhân viên hỗ trợ đã nhận ra quy luật này và báo cho kỹ sư trực lúc 12:20."]],[["The on-call engineer rolled back the API change at 13:05, and correct answers returned ten minutes later.","Kỹ sư trực đã rollback thay đổi API lúc 13:05, và câu trả lời đúng xuất hiện trở lại mười phút sau đó."],["Customer Service sent an apology email to all affected customers on September 10, together with a 10-dollar voucher.","Bộ phận Chăm sóc Khách hàng đã gửi email xin lỗi đến tất cả khách hàng bị ảnh hưởng vào ngày 10 tháng 9, kèm một phiếu giảm giá 10 đô la."]],[["Three actions have been agreed.","Ba hành động khắc phục đã được thống nhất."],["The API team will add a contract test so that any field change breaks the build before release (owner: Sara Lindqvist, due September 20).","Nhóm API sẽ thêm contract test để mọi thay đổi trường dữ liệu đều làm hỏng build trước khi phát hành (người phụ trách: Sara Lindqvist, hạn 20 tháng 9)."],["The AI Platform team will add an accuracy check that compares 50 random chatbot answers per hour with the order database (owner: Arjun Mehta, due September 27).","Nhóm AI Platform sẽ thêm bước kiểm tra độ chính xác, so sánh 50 câu trả lời ngẫu nhiên của chatbot mỗi giờ với cơ sở dữ liệu đơn hàng (người phụ trách: Arjun Mehta, hạn 27 tháng 9)."],["Finally, the chatbot will say \"I'm not sure\" instead of guessing when a status is missing.","Cuối cùng, chatbot sẽ nói \"Tôi không chắc\" thay vì đoán khi thiếu thông tin trạng thái."]]],"vocab":[{"w":"deliver","f":"delivered","pos":"v","ipa":"/dɪˈlɪvər/","vi":"giao hàng, phân phát; cung cấp, mang lại"},{"w":"warehouse","f":"warehouse","pos":"n","ipa":"/ˈwɛrˌhaʊs/","vi":"kho hàng"},{"w":"track","f":"tracking","pos":"n/v","ipa":"/træk/","vi":"theo dõi, dấu vết; đường ray"},{"w":"release","f":"released","pos":"v/n","ipa":"/rɪˈliːs/","vi":"phát hành, tung ra; sự phát hành"},{"w":"pipeline","f":"pipeline","pos":"n","ipa":"/ˈpaɪplaɪn/","vi":"đường ống; quy trình xử lý"},{"w":"apology","f":"apology","pos":"n","ipa":"/əˈpɑlədʒi/","vi":"lời xin lỗi"},{"w":"voucher","f":"voucher","pos":"n","ipa":"/ˈvaʊtʃər/","vi":"phiếu mua hàng; chứng từ"},{"w":"break the build","f":"breaks the build","pos":"phrase","ipa":"","vi":"làm hỏng bản build"},{"w":"owner","f":"owner","pos":"n","ipa":"/ˈoʊnər/","vi":"chủ sở hữu; người phụ trách"},{"w":"due","f":"due","pos":"adj","ipa":"/duː/","vi":"đến hạn, do"},{"w":"accuracy","f":"accuracy","pos":"n","ipa":"/ˈækjərəsi/","vi":"độ chính xác"},{"w":"instead of","f":"instead of","pos":"phrase","ipa":"","vi":"thay vì"}],"questions":[{"q":"How long did the incident last?","o":["About 25 minutes","About 1 hour 40 minutes","About 2 hours 35 minutes","About 3 hours"],"a":2,"vi":"Sự cố kéo dài 'between 10:40 and 13:15', tức khoảng 2 giờ 35 phút → C. 12:20 là lúc báo cho kỹ sư trực, không phải lúc bắt đầu."},{"q":"Why did monitoring fail to detect the problem?","o":["It was turned off during the release","It only checked whether the chatbot was online","The on-call engineer ignored an alert","It checked answers only once per hour"],"a":1,"vi":"'it only checked whether the chatbot was online, not whether its answers were correct' → B. 'Per hour' là bước kiểm tra mới sẽ thêm sau này."},{"q":"Who first reported the problem to the on-call engineer?","o":["A support agent","The API team","Arjun Mehta","Sara Lindqvist"],"a":0,"vi":"'A support agent noticed the pattern and reported it to the on-call engineer at 12:20' → A. Arjun và Sara là người phụ trách các hành động khắc phục."},{"q":"What is due on September 27?","o":["A contract test for the API","An apology email to customers","A 10-dollar voucher","An hourly accuracy check"],"a":3,"vi":"'an accuracy check ... (owner: Arjun Mehta, due September 27)' → D. Contract test có hạn 20/9; email xin lỗi đã gửi ngày 10/9."}],"words":258},{"id":"r3-18","level":3,"type":"memo","topic":"HR","title":"Changes to expense claims and travel","title_vi":"Thay đổi về thanh toán chi phí và công tác","head":[["From","Natalia Cruz, HR & Finance Operations"],["To","All employees, Ardent Labs"],["Date","June 2"],["Subject","Changes to expense claims and travel booking"]],"paras":[[["Following feedback from the spring survey, we are updating how expense claims and business travel work at Ardent Labs.","Dựa trên phản hồi từ cuộc khảo sát mùa xuân, chúng tôi đang thay đổi cách thanh toán chi phí và đi công tác tại Ardent Labs."],["Many employees told us that they waited too long for their money, an average of 24 days, and that the paper forms were confusing.","Nhiều nhân viên cho biết họ phải chờ tiền quá lâu, trung bình 24 ngày, và các biểu mẫu giấy rất khó hiểu."]],[["From July 1, all claims must be made in the Spendly app, and paper forms will no longer be accepted.","Từ ngày 1 tháng 7, mọi yêu cầu thanh toán phải được thực hiện trên ứng dụng Spendly, và biểu mẫu giấy sẽ không còn được chấp nhận."],["Take a photo of each receipt and add it to the app within 30 days of the purchase.","Hãy chụp ảnh từng hóa đơn và tải lên ứng dụng trong vòng 30 ngày kể từ ngày mua."],["Claims under 200 dollars will be approved automatically, and larger claims will go to your manager, who must respond within five working days.","Các khoản dưới 200 đô la sẽ được duyệt tự động, còn các khoản lớn hơn sẽ được chuyển đến quản lý của bạn, người phải phản hồi trong vòng năm ngày làm việc."],["Once a claim is approved, you will be reimbursed in the next weekly payment run instead of at the end of the month.","Khi khoản chi được duyệt, bạn sẽ được hoàn tiền trong đợt thanh toán hàng tuần kế tiếp thay vì vào cuối tháng."]],[["There are also changes to travel.","Cũng có một số thay đổi về công tác."],["Flights and hotels for conferences, client visits and training must now be booked through our travel partner, Skyline Desk, at least 14 days in advance.","Vé máy bay và khách sạn cho hội nghị, thăm khách hàng và đào tạo nay phải được đặt qua đối tác du lịch của chúng tôi là Skyline Desk, trước ít nhất 14 ngày."],["The hotel limit rises from 90 to 120 dollars per night in Singapore and Tokyo, but stays the same in other cities.","Mức trần khách sạn tăng từ 90 lên 120 đô la mỗi đêm tại Singapore và Tokyo, nhưng giữ nguyên ở các thành phố khác."],["Taxi rides to and from the airport can be claimed, but meals during a flight cannot.","Tiền taxi đi và về sân bay được thanh toán, nhưng bữa ăn trong chuyến bay thì không."],["Train tickets for trips under 300 kilometers can still be booked by employees themselves.","Vé tàu cho các chuyến đi dưới 300 km thì nhân viên vẫn có thể tự đặt."]],[["Managers will receive a short training session on the new system on June 18, and a guide for all staff will be posted on the intranet next week.","Các quản lý sẽ tham gia một buổi đào tạo ngắn về hệ thống mới vào ngày 18 tháng 6, và hướng dẫn cho toàn bộ nhân viên sẽ được đăng trên intranet vào tuần tới."],["Claims for May and June can still be made on paper until June 30.","Các khoản chi của tháng 5 và tháng 6 vẫn có thể nộp bằng giấy đến hết ngày 30 tháng 6."]]],"vocab":[{"w":"feedback","f":"feedback","pos":"n","ipa":"/ˈfidˌbæk/","vi":"phản hồi; ý kiến đóng góp"},{"w":"expense","f":"expense","pos":"n","ipa":"/ɪkˈspens/","vi":"chi phí"},{"w":"average","f":"average","pos":"adj/n","ipa":"/ˈævərɪdʒ/","vi":"trung bình"},{"w":"accept","f":"accepted","pos":"v","ipa":"/əkˈsɛpt/","vi":"Chấp nhận, thừa nhận"},{"w":"receipt","f":"receipt","pos":"n","ipa":"/rɪˈsit/","vi":"biên lai; hóa đơn"},{"w":"purchase","f":"purchase","pos":"n/v","ipa":"/ˈpɜːrtʃəs/","vi":"mua hàng; vật phẩm, sự mua"},{"w":"respond","f":"respond","pos":"v","ipa":"/rɪˈspɑːnd/","vi":"phản hồi; đáp lại"},{"w":"reimburse","f":"reimbursed","pos":"v","ipa":"/ˌriɪmˈbɜrs/","vi":"hoàn trả chi phí"},{"w":"instead of","f":"instead of","pos":"phrase","ipa":"","vi":"thay vì"},{"w":"conference","f":"conferences","pos":"n","ipa":"/ˈkɑnfərəns/","vi":"hội nghị, cuộc họp lớn"},{"w":"in advance","f":"in advance","pos":"phrase","ipa":"","vi":"trước, sẵn"},{"w":"limit","f":"limit","pos":"n/v","ipa":"/ˈlɪmɪt/","vi":"giới hạn"}],"questions":[{"q":"What problem did employees report in the survey?","o":["Hotel limits were too low everywhere","They waited too long to get their money back","The Spendly app crashed often","Managers rejected too many claims"],"a":1,"vi":"'they waited too long for their money, an average of 24 days' → B. Mức trần khách sạn là thay đổi mới, không phải phàn nàn trong khảo sát."},{"q":"What will happen to a 150-dollar claim under the new system?","o":["It will go to the employee's manager","It must be made on paper","It will be paid at the end of the month","It will be approved automatically"],"a":3,"vi":"'Claims under 200 dollars will be approved automatically' → D. Chỉ khoản lớn hơn 200 đô la mới chuyển cho quản lý (bẫy A)."},{"q":"What is NOT mentioned as a change to travel?","o":["Booking through Skyline Desk","A higher hotel limit in some cities","A new daily meal allowance","Booking at least 14 days ahead"],"a":2,"vi":"Bài chỉ nói bữa ăn trên máy bay không được thanh toán; không có phụ cấp ăn hàng ngày nào → C."},{"q":"Until when can paper forms still be used?","o":["June 30","June 18","July 1","30 days after a purchase"],"a":0,"vi":"'Claims for May and June can still be made on paper until June 30' → A. June 18 là buổi đào tạo quản lý, July 1 là ngày bắt đầu dùng Spendly."}],"words":252},{"id":"r3-19","level":3,"type":"email","topic":"Sales","title":"Request to extend the pilot","title_vi":"Đề nghị gia hạn chương trình thí điểm","head":[["From","Elena Vasquez <elena.vasquez@harborpoint-ins.com>"],["To","Kevin Ngo <kevin.ngo@orrin.ai>"],["Subject","Pilot extension and next steps"]],"paras":[[["Dear Kevin,","Kevin thân mến,"]],[["Thank you for the pilot results you shared last Thursday.","Cảm ơn anh về kết quả thí điểm mà anh đã chia sẻ hôm thứ Năm tuần trước."],["Our claims team was impressed that your document model processed 12,000 claim forms with 93 percent accuracy, compared with 81 percent for our current vendor.","Nhóm bồi thường của chúng tôi rất ấn tượng khi mô hình xử lý tài liệu của anh xử lý 12.000 hồ sơ bồi thường với độ chính xác 93 phần trăm, so với 81 phần trăm của nhà cung cấp hiện tại."],["The pilot also showed that your system needed only 2 seconds per form, while our staff currently spend about 6 minutes on each one.","Chương trình thí điểm cũng cho thấy hệ thống của anh chỉ cần 2 giây cho mỗi hồ sơ, trong khi nhân viên của chúng tôi hiện mất khoảng 6 phút cho mỗi hồ sơ."],["Before we sign a full contract, however, we would like to extend the pilot by six weeks, until January 31.","Tuy nhiên, trước khi ký hợp đồng chính thức, chúng tôi muốn gia hạn chương trình thí điểm thêm sáu tuần, đến ngày 31 tháng 1."]],[["There are two reasons for this request.","Có hai lý do cho đề nghị này."],["First, the pilot only covered car insurance claims, and our board wants to see results for home insurance, which uses handwritten forms.","Thứ nhất, chương trình thí điểm chỉ bao gồm hồ sơ bảo hiểm ô tô, trong khi hội đồng quản trị của chúng tôi muốn xem kết quả với bảo hiểm nhà ở, loại dùng mẫu viết tay."],["Second, our IT security team has not finished its review of your data storage in Singapore, and they expect to need until mid-January.","Thứ hai, nhóm bảo mật IT của chúng tôi chưa hoàn tất việc đánh giá hệ thống lưu trữ dữ liệu của bên anh tại Singapore, và họ dự kiến cần đến giữa tháng 1."]],[["We understand that an extension may involve extra cost.","Chúng tôi hiểu rằng việc gia hạn có thể phát sinh thêm chi phí."],["Our budget allows up to 8,000 dollars for the additional six weeks, and we can provide about 3,000 sample home insurance forms by December 12.","Ngân sách của chúng tôi cho phép tối đa 8.000 đô la cho sáu tuần bổ sung, và chúng tôi có thể cung cấp khoảng 3.000 hồ sơ mẫu bảo hiểm nhà ở trước ngày 12 tháng 12."],["Please note that any price above this amount would need approval from our CFO, which could take another month.","Xin lưu ý rằng mọi mức giá cao hơn số tiền này sẽ cần Giám đốc Tài chính phê duyệt, việc đó có thể mất thêm một tháng."],["Could you send me a revised proposal with the new timeline and price by Friday, December 5?","Anh có thể gửi cho tôi bản đề xuất đã chỉnh sửa với tiến độ và mức giá mới trước thứ Sáu, ngày 5 tháng 12 được không?"],["If the extended pilot is successful, we expect to sign a two-year agreement covering all three of our claims centers.","Nếu chương trình thí điểm mở rộng thành công, chúng tôi dự kiến sẽ ký thỏa thuận hai năm cho cả ba trung tâm bồi thường của chúng tôi."],["I'm happy to discuss the details on a call early next week.","Tôi sẵn lòng trao đổi chi tiết qua một cuộc gọi vào đầu tuần tới."]],[["Best regards,","Trân trọng,"],["Elena Vasquez, Head of Claims Operations, Harborpoint Insurance","Elena Vasquez, Trưởng bộ phận Vận hành Bồi thường, Harborpoint Insurance"]]],"vocab":[{"w":"accuracy","f":"accuracy","pos":"n","ipa":"/ˈækjərəsi/","vi":"độ chính xác"},{"w":"vendor","f":"vendor","pos":"n","ipa":"/ˈvɛndər/","vi":"nhà cung cấp, người bán hàng"},{"w":"sign","f":"sign","pos":"n/v","ipa":"/saɪn/","vi":"ký tên; dấu hiệu"},{"w":"contract","f":"contract","pos":"n/v","ipa":"/ˈkɑntrækt/","vi":"hợp đồng; ký kết"},{"w":"however","f":"however","pos":"phrase","ipa":"","vi":"tuy nhiên"},{"w":"extend","f":"extend","pos":"v","ipa":"/ɪkˈstɛnd/","vi":"kéo dài, mở rộng"},{"w":"request","f":"request","pos":"n/v","ipa":"/rɪˈkwest/","vi":"yêu cầu, lời thỉnh cầu"},{"w":"budget","f":"budget","pos":"n/v","ipa":"/ˈbʌdʒɪt/","vi":"ngân sách; lên ngân sách"},{"w":"additional","f":"additional","pos":"adj","ipa":"/əˈdɪʃənəl/","vi":"bổ sung, thêm"},{"w":"proposal","f":"proposal","pos":"n","ipa":"/prəˈpoʊzl/","vi":"đề xuất, bản đề xuất"},{"w":"timeline","f":"timeline","pos":"n","ipa":"/ˈtaɪmˌlaɪn/","vi":"lịch trình thời gian, tiến độ"},{"w":"early next week","f":"early next week","pos":"phrase","ipa":"","vi":"đầu tuần sau"}],"questions":[{"q":"What accuracy did the client's current vendor achieve?","o":["93 percent","81 percent","12 percent","31 percent"],"a":1,"vi":"'93 percent accuracy, compared with 81 percent for our current vendor' → B. 93% là kết quả của mô hình bên Kevin (bẫy A)."},{"q":"What is one reason Elena gives for extending the pilot?","o":["The model's accuracy was too low","Kevin's team asked for more time","The board wants results for handwritten home insurance forms","The contract with the current vendor ends in January"],"a":2,"vi":"Lý do thứ nhất: 'our board wants to see results for home insurance, which uses handwritten forms' → C. Lý do còn lại là đánh giá bảo mật, không có A, B, D."},{"q":"What does Elena ask Kevin to do by December 5?","o":["Provide 3,000 sample forms","Finish the security review","Sign a two-year agreement","Send a revised proposal"],"a":3,"vi":"'Could you send me a revised proposal ... by Friday, December 5?' → D. 3.000 hồ sơ mẫu là việc bên Elena làm trước 12/12."},{"q":"What is the most the client can pay for the extra six weeks?","o":["8,000 dollars","3,000 dollars","12,000 dollars","The amount is not stated"],"a":0,"vi":"'Our budget allows up to 8,000 dollars for the additional six weeks' → A. 3.000 và 12.000 là số lượng hồ sơ, không phải tiền."}],"words":248},{"id":"r3-20","level":3,"type":"article","topic":"Legal","title":"New 90-day rule for user logs","title_vi":"Quy định 90 ngày mới cho log người dùng","head":[],"paras":[[["Starting March 1, Fenwick Health Tech will delete raw user conversation logs after 90 days instead of keeping them for two years.","Bắt đầu từ ngày 1 tháng 3, Fenwick Health Tech sẽ xóa log hội thoại thô của người dùng sau 90 ngày thay vì lưu giữ trong hai năm."],["The change follows an external audit in October, which found that the company stored far more personal data than it needed and that only 15 percent of old logs were ever used again.","Thay đổi này được đưa ra sau một cuộc kiểm toán bên ngoài vào tháng 10, cho thấy công ty lưu trữ nhiều dữ liệu cá nhân hơn mức cần thiết rất nhiều và chỉ 15 phần trăm log cũ từng được dùng lại."],["According to Chief Legal Officer Ruth Adeyemi, the new policy also prepares the company for stricter privacy rules expected in several of its markets next year.","Theo Giám đốc Pháp chế Ruth Adeyemi, chính sách mới cũng giúp công ty chuẩn bị cho các quy định về quyền riêng tư chặt chẽ hơn dự kiến sẽ áp dụng tại một số thị trường vào năm tới."]],[["For engineers, the biggest impact will be on the machine learning teams, which have used old logs to retrain the symptom-checker model every quarter.","Với kỹ sư, tác động lớn nhất sẽ rơi vào các nhóm machine learning, vốn dùng log cũ để huấn luyện lại mô hình kiểm tra triệu chứng mỗi quý."],["From now on, logs can only be kept longer than 90 days if names, phone numbers and other personal details have been removed.","Từ nay, log chỉ được giữ quá 90 ngày nếu tên, số điện thoại và các thông tin cá nhân khác đã được loại bỏ."],["The data platform team has built a tool that does this automatically, and it was tested on 1.2 million records in January with an error rate below 0.5 percent.","Nhóm nền tảng dữ liệu đã xây dựng một công cụ làm việc này tự động, và nó đã được thử nghiệm trên 1,2 triệu bản ghi vào tháng 1 với tỷ lệ lỗi dưới 0,5 phần trăm."]],[["Every team that runs a data pipeline must confirm by February 14 that its pipeline sends logs through the new tool.","Mọi nhóm vận hành pipeline dữ liệu phải xác nhận trước ngày 14 tháng 2 rằng pipeline của mình đưa log qua công cụ mới."],["Pipelines that are not confirmed will be paused on March 1 until the owner completes the compliance checklist.","Các pipeline chưa được xác nhận sẽ bị tạm dừng vào ngày 1 tháng 3 cho đến khi người phụ trách hoàn tất danh sách kiểm tra tuân thủ."],["Some engineers have raised concerns that cleaned data will lower model accuracy.","Một số kỹ sư đã bày tỏ lo ngại rằng dữ liệu đã làm sạch sẽ làm giảm độ chính xác của mô hình."],["Early tests suggest the drop is small, about one percentage point, and the Legal team says this is a fair price for lower risk.","Các thử nghiệm ban đầu cho thấy mức giảm nhỏ, khoảng một điểm phần trăm, và nhóm Pháp chế cho rằng đây là cái giá hợp lý để giảm rủi ro."],["Questions about the policy should be posted in the #data-retention channel, where Legal and the data platform team answer every weekday.","Câu hỏi về chính sách nên được đăng trong kênh #data-retention, nơi nhóm Pháp chế và nhóm nền tảng dữ liệu trả lời vào tất cả các ngày trong tuần."]]],"vocab":[{"w":"delete","f":"delete","pos":"v","ipa":"/dɪˈliːt/","vi":"xóa"},{"w":"instead of","f":"instead of","pos":"phrase","ipa":"","vi":"thay vì"},{"w":"audit","f":"audit","pos":"n/v","ipa":"/ˈɔːdɪt/","vi":"kiểm toán"},{"w":"personal","f":"personal","pos":"adj","ipa":"/ˈpɜːrsənl/","vi":"cá nhân"},{"w":"policy","f":"policy","pos":"n","ipa":"/ˈpɑːləsi/","vi":"chính sách"},{"w":"privacy","f":"privacy","pos":"n","ipa":"/ˈprɑvəsi/","vi":"sự riêng tư"},{"w":"impact","f":"impact","pos":"n/v","ipa":"/ˈɪmpækt/","vi":"tác động, ảnh hưởng"},{"w":"from now on","f":"From now on","pos":"phrase","ipa":"","vi":"từ giờ trở đi"},{"w":"record","f":"records","pos":"n/v","ipa":"/ˈrɛkərd/","vi":"hồ sơ, ghi chép; lưu trữ"},{"w":"pipeline","f":"pipeline","pos":"n","ipa":"/ˈpaɪplaɪn/","vi":"đường ống; quy trình xử lý"},{"w":"confirm","f":"confirm","pos":"v","ipa":"/kənˈfɜːrm/","vi":"xác nhận; khẳng định"},{"w":"compliance","f":"compliance","pos":"n","ipa":"/kəmˈplaɪ.əns/","vi":"sự tuân thủ"}],"questions":[{"q":"What did the October audit find?","o":["The company kept more personal data than it needed","The symptom-checker model was inaccurate","Logs were being deleted too early","New privacy rules had already started"],"a":0,"vi":"'found that the company stored far more personal data than it needed' → A. Quy định quyền riêng tư mới chỉ 'expected ... next year', chưa có hiệu lực (bẫy D)."},{"q":"Under what condition can logs be kept longer than 90 days?","o":["If the ML team needs them for retraining","If personal details have been removed","If the owner confirms by February 14","If they are less than two years old"],"a":1,"vi":"'logs can only be kept longer than 90 days if names, phone numbers and other personal details have been removed' → B. Ngày 14/2 là hạn xác nhận pipeline."},{"q":"What will happen to pipelines that are not confirmed by the deadline?","o":["They will be deleted","They will be moved to the data platform team","They will be paused on March 1","Their owners will be audited"],"a":2,"vi":"'Pipelines that are not confirmed will be paused on March 1' → C. Thứ bị xóa là log, không phải pipeline (bẫy A)."},{"q":"The word \"raised\" in paragraph 3 is closest in meaning to","o":["lifted","increased","grown","expressed"],"a":3,"vi":"'raised concerns' = nêu ra, bày tỏ mối lo ngại → D 'expressed'. Các nghĩa 'nâng lên, tăng lên' của raise không hợp ngữ cảnh."}],"words":255}];